/** @format */

import { useState, useRef } from "react";
import { FileExport } from "@/Icons";
import Dropdown from "@/designSystem/Dropdown";
import { exportToExcel, exportToCSV, formatDataForExport, generateFilename, mergeTransformedWithRawData } from "@/utilities/exportUtils";
import toast from "@/utilities/toast";

interface ExportButtonProps<T extends Record<string, any>> {
	data: T[];
	rawData?: any[]; // Optional raw API data to merge with transformed data
	idField?: string; // Field to match records when merging (default: 'id')
	filename: string;
	fieldMapping?: Record<string, string>;
	sheetName?: string;
	disabled?: boolean;
	className?: string;
}

export default function ExportButton<T extends Record<string, any>>({
	data,
	rawData,
	idField = 'id',
	filename,
	fieldMapping,
	sheetName = "Data",
	disabled = false,
	className = "",
}: ExportButtonProps<T>) {
	const [isDropdownOpen, setIsDropdownOpen] = useState(false);
	const buttonRef = useRef<HTMLButtonElement>(null);

	const handleExport = async (format: "excel" | "csv") => {
		try {
			if (!data || data.length === 0) {
				toast.error("No data to export");
				return;
			}

			// Merge transformed data with raw data if rawData is provided
			let dataToExport = data;
			if (rawData && rawData.length > 0) {
				dataToExport = mergeTransformedWithRawData(data, rawData, idField) as T[];
			}

			// Format data for export
			const formattedData = formatDataForExport(dataToExport, fieldMapping);
			const exportFilename = generateFilename(filename);

			// Export based on format
			if (format === "excel") {
				exportToExcel(formattedData, exportFilename, sheetName);
				toast.success("Excel file downloaded successfully");
			} else {
				exportToCSV(formattedData, exportFilename);
				toast.success("CSV file downloaded successfully");
			}

			setIsDropdownOpen(false);
		} catch (error) {
			console.error("Export error:", error);
			toast.error(`Failed to export ${format.toUpperCase()}`);
		}
	};

	const dropdownItems = [
		{
			id: "excel",
			label: "Export as Excel (.xlsx)",
			icon: FileExport,
			onClick: () => handleExport("excel"),
		},
		{
			id: "csv",
			label: "Export as CSV (.csv)",
			icon: FileExport,
			onClick: () => handleExport("csv"),
		},
	];

	return (
		<>
			<button
				ref={buttonRef}
				onClick={() => setIsDropdownOpen(!isDropdownOpen)}
				disabled={disabled || !data || data.length === 0}
				className={`flex items-center gap-2 px-2.5 py-2 text-sm font-medium text-text-sub border border-border rounded-lg bg-background hover:bg-bg-weak transition-colors disabled:opacity-50 disabled:cursor-not-allowed ${className}`}
			>
				<FileExport className="size-5 fill-text-sub" />
				<span>Export</span>
			</button>
			<Dropdown
				isOpen={isDropdownOpen}
				onClose={() => setIsDropdownOpen(false)}
				anchorRef={buttonRef}
				items={dropdownItems}
			/>
		</>
	);
}

/** @format */

import { useState, useEffect, useRef, useCallback, useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import { IndividualChatHeader } from "./individual";
import { GroupChatHeader } from "./group";
import { MessageInput, ChatEmptyState } from "./shared";
import { MessageList } from "./MessageList";
import {
   useChatRoom,
   useChatRoomQuery,
   useMessages,
   useTypingIndicator,
   useOnlineUsers,
   useMarkAsRead,
} from "@/hooks/chat";
import { useFileUpload } from "@/hooks/useFileUpload";
import { getChatUsers } from "@/services/chat/chatService";
import { getCurrentUserId } from "@/utils/auth";
import type { Message, RoomMember, ChatUser } from "@/services/chat/types";
import type { ChatMessage } from "./types";
import { findOtherMember, resolveAvatar, buildMediaUrl } from "./utils";
import { convertMessage } from "./messageUtils";
import { ArrowDownSLine } from "@/Icons";

interface ChatWindowNewProps {
   roomId: number | null;
}

function ChatWindowNew({ roomId }: ChatWindowNewProps) {
   const currentUserId = getCurrentUserId();
   const currentUserIdNum = currentUserId ? Number(currentUserId) : null;
   const messagesEndRef = useRef<HTMLDivElement>(null);
   const messagesContainerRef = useRef<HTMLDivElement>(null);

   const [messageValue, setMessageValue] = useState<string>("");
   const [replyingTo, setReplyingTo] = useState<Message | null>(null);
   const [hasScrolledToUnread, setHasScrolledToUnread] = useState(false);
   const [showScrollButton, setShowScrollButton] = useState(false);
   const typingTimeoutRef = useRef<NodeJS.Timeout | null>(null);

   // Load last close time when entering room
   // REMOVED

   // Save current time when leaving room (unmount)
   // REMOVED

   const {
      data: room,
      isLoading: isLoadingRoom,
      error: roomError,
   } = useChatRoomQuery(roomId);

   useChatRoom(roomId);

   const {
      messages,
      isLoading: isLoadingMessages,
      hasMore,
      loadMore,
      sendMessage,
      markAsRead,
   } = useMessages(roomId || 0, currentUserIdNum || 0);

   // Import useFileUpload here? No, it's a hook.
   // I need to import it at top level.
   const { uploadFile } = useFileUpload();

   const { typingUsers, handleTyping, handleStopTyping } =
      useTypingIndicator(roomId);

   const { isUserOnline } = useOnlineUsers();

   // Automatically mark messages as read
   useMarkAsRead(messages, roomId, currentUserIdNum, markAsRead);

   // Extract room type checks to avoid repetition
   const isDirect = room?.room_type === "direct";
   const isGroup = room?.room_type === "group";

   const otherMember = useMemo(() => {
      if (!room || !isDirect) return null;
      return findOtherMember(room, currentUserIdNum);
   }, [room, isDirect, currentUserIdNum]);

   // Fetch all users for avatar fallback (needed for both direct and group chats)
   const { data: allUsersData } = useQuery({
      queryKey: ["chat", "users", "all"],
      queryFn: () => getChatUsers(),
      staleTime: 2 * 60 * 1000,
      refetchOnMount: true,
   });

   const normalizeMedia = useCallback(
      (url?: string | null) =>
         !url || url.startsWith("http") ? url || "" : buildMediaUrl(url),
      []
   );

   // Build avatar map for performance optimization - memoize by room ID and user data version
   // Note: resolveAvatar has fallbacks, so this map is just for speed
   const senderProfilesMap = useMemo(() => {
      const map = new Map<number, string>();

      // Add all room members' profile pictures
      if (room?.members) {
         room.members.forEach((member: RoomMember) => {
            const memberId = Number(member.employee_id);
            const avatarCandidate =
               member.profile_picture_url || (member as any).avatar;
            if (avatarCandidate) {
               map.set(memberId, normalizeMedia(avatarCandidate));
            }
         });
      }

      // Add all users from the users list (fallback for missing avatars)
      if (allUsersData?.data) {
         allUsersData.data.forEach((user: ChatUser) => {
            const userId = Number(user.employee_id);
            if (user.profile_picture_url && !map.has(userId)) {
               map.set(userId, normalizeMedia(user.profile_picture_url));
            }
         });
      }

      return map;
   }, [room?.members, allUsersData?.data, normalizeMedia]);

   // Scroll to bottom helper
   const scrollToBottom = useCallback((behavior: ScrollBehavior = "smooth") => {
      messagesEndRef.current?.scrollIntoView({ behavior, block: "end" });
   }, []);

   // Check if user is near bottom of scroll
   const isNearBottom = useCallback(() => {
      const container = messagesContainerRef.current;
      if (!container) return true;

      const threshold = 150; // pixels from bottom
      const { scrollTop, scrollHeight, clientHeight } = container;
      return scrollHeight - scrollTop - clientHeight < threshold;
   }, []);

   // Handle scroll event to show/hide scroll button
   const handleScroll = useCallback(() => {
      const container = messagesContainerRef.current;
      if (!container) return;

      const atBottom = isNearBottom();
      setShowScrollButton(!atBottom);
   }, [isNearBottom]);

   // Scroll logic: scroll to bottom on initial load and when sending messages
   useEffect(() => {
      if (!roomId || messages.length === 0) return;

      // On initial load, scroll to bottom immediately
      if (!hasScrolledToUnread) {
         scrollToBottom("auto");
         setHasScrolledToUnread(true);
         return;
      }

      // Auto-scroll to bottom only if user is already near bottom
      // This prevents interrupting users reading old messages
      if (isNearBottom()) {
         scrollToBottom("smooth");
      }
   }, [messages, roomId, hasScrolledToUnread, isNearBottom, scrollToBottom]);

   // Reset scroll flag when room changes
   useEffect(() => {
      setHasScrolledToUnread(false);
      setShowScrollButton(false);
   }, [roomId]);

   const handleTypingChange = (value: string) => {
      setMessageValue(value);
      handleTyping();

      if (typingTimeoutRef.current) {
         clearTimeout(typingTimeoutRef.current);
      }
   };

   useEffect(() => {
      const timeoutRef = typingTimeoutRef.current;
      return () => {
         if (timeoutRef) {
            clearTimeout(timeoutRef);
         }
      };
   }, []);

   const handleReply = useCallback(
      (message: ChatMessage) => {
         const originalMessage = messages.find(
            (msg) => msg.message_id.toString() === message.id
         );
         if (originalMessage) {
            setReplyingTo(originalMessage);
         }
      },
      [messages]
   );

   const buildOptimisticReply = useCallback(() => {
      if (!replyingTo) return undefined;

      const replyType: ChatMessage["type"] = replyingTo.attachment_file_id
         ? replyingTo.attachment?.mime_type?.startsWith("audio")
            ? "voice"
            : "file"
         : "text";

      return {
         message_id: replyingTo.message_id,
         message_text:
            replyingTo.message_text ||
            replyingTo.attachment?.original_filename ||
            null,
         type: replyType,
         fileName: replyingTo.attachment?.original_filename || undefined,
         fileSize: replyingTo.attachment?.file_size_kb || undefined,
         fileUrl:
            replyingTo.attachment?.file_url ||
            replyingTo.attachment?.storage_path ||
            undefined,
         sender: replyingTo.sender
            ? {
                 employee_id: replyingTo.sender.employee_id,
                 first_name: replyingTo.sender.first_name,
                 last_name: replyingTo.sender.last_name,
                 email: replyingTo.sender.email,
              }
            : undefined,
      };
   }, [replyingTo]);

   const handleSend = useCallback(() => {
      if (!messageValue.trim() || !roomId) return;

      // Immediate UI update
      const textToSend = messageValue.trim();
      setMessageValue("");
      setReplyingTo(null);
      handleStopTyping();

      // Scroll to bottom immediately when sending
      setTimeout(() => {
         scrollToBottom("smooth");
      }, 0);

      const optimisticReply = buildOptimisticReply();

      sendMessage(
         {
            message_text: textToSend,
            reply_to_message_id: replyingTo?.message_id,
            _optimistic_reply: optimisticReply,
         },
         {
            onError: () => {
               console.error("Message send failed");
            },
         }
      );
   }, [
      messageValue,
      roomId,
      sendMessage,
      replyingTo,
      buildOptimisticReply,
      handleStopTyping,
      scrollToBottom,
   ]);

   // Handle file attachment
   const handleAttachFile = useCallback(
      (
         fileId: number,
         token: string,
         fileName: string,
         fileUrl: string,
         fileSizeBytes: number
      ) => {
         if (!roomId) return;

         // Immediate UI update
         setReplyingTo(null);
         setTimeout(() => {
            scrollToBottom("smooth");
         }, 0);

         // Convert bytes to KB for backend
         const fileSizeKB = Math.round(fileSizeBytes / 1024);

         const optimisticReply = buildOptimisticReply();

         const payload = {
            message_text: undefined, // Explicitly undefined for file-only messages
            attachment_file_id: fileId,
            attachment_token: token, // Include token for backend consumption
            reply_to_message_id: replyingTo?.message_id,
            // Metadata for optimistic UI update
            _optimistic_attachment_metadata: {
               fileName,
               fileSize: fileSizeKB,
               fileUrl,
            },
            _optimistic_reply: optimisticReply,
         };

         sendMessage(payload, {
            onError: (error) => {
               console.error(`[File Attachment] Failed to send file:`, error);
            },
         });
      },
      [roomId, sendMessage, replyingTo, buildOptimisticReply, scrollToBottom]
   );

   const handleVoiceMessage = useCallback(
      async (audioBlob: Blob) => {
         if (!roomId) return;

         // Determine extension based on blob type
         const mimeType = audioBlob.type;
         let extension = "webm";
         if (mimeType.includes("mp4")) extension = "mp4";
         else if (mimeType.includes("ogg")) extension = "ogg";
         else if (mimeType.includes("wav")) extension = "wav";

         // Create a File object from Blob
         const file = new File([audioBlob], `voice_message.${extension}`, {
            type: mimeType,
         });

         try {
            const result = await uploadFile(file, {
               purpose: "chat_attachment",
            });

            const optimisticReply = buildOptimisticReply();

            // Immediate UI update
            setReplyingTo(null);
            setTimeout(() => {
               scrollToBottom("smooth");
            }, 0);

            // Send message with token for backend consumption
            sendMessage(
               {
                  message_text: undefined,
                  attachment_file_id: result.fileId,
                  attachment_token: result.token, // Include token
                  reply_to_message_id: replyingTo?.message_id,
                  _optimistic_attachment_metadata: {
                     fileName: file.name,
                     fileSize: Math.round(file.size / 1024),
                     fileUrl: result.fileUrl,
                     mimeType: file.type,
                  },
                  _optimistic_reply: optimisticReply,
               },
               {
                  onError: (error) => {
                     console.error(`[Voice Message] Failed to send:`, error);
                  },
               }
            );
         } catch (error) {
            console.error("Failed to upload voice message:", error);
         }
      },
      [
         roomId,
         uploadFile,
         sendMessage,
         replyingTo,
         buildOptimisticReply,
         scrollToBottom,
      ]
   );

   const currentUser = useMemo(() => {
      if (!room || !isDirect || !otherMember) return null;

      const memberId = Number(otherMember.employee_id);
      if (currentUserIdNum !== null && memberId === currentUserIdNum) {
         return null;
      }

      const displayName =
         room.room_name?.trim() ||
         `${otherMember.first_name} ${otherMember.last_name || ""}`.trim();

      const resolvedAvatar = resolveAvatar(
         memberId,
         room,
         allUsersData,
         null,
         senderProfilesMap
      );
      const avatarUrl =
         normalizeMedia(
            resolvedAvatar ||
               otherMember.profile_picture_url ||
               (otherMember as any).avatar
         ) || undefined;

      // Find job title from allUsersData
      const userFromList = allUsersData?.data?.find(
         (u: ChatUser) => Number(u.employee_id) === memberId
      );
      const jobTitle = userFromList?.job_title || "";

      return {
         id: otherMember.employee_id.toString(),
         name: displayName,
         jobTitle,
         avatar: avatarUrl,
         isOnline: isUserOnline(memberId),
      };
   }, [
      room,
      isDirect,
      otherMember,
      currentUserIdNum,
      isUserOnline,
      senderProfilesMap,
      allUsersData,
      normalizeMedia,
   ]);

   const currentGroup = useMemo(() => {
      if (!room || !isGroup) return undefined;

      return {
         id: room.room_id.toString(),
         name: room.room_name || "Unnamed Group",
         avatar: room.avatar_url || undefined,
         members: room.members.map((m: RoomMember) => {
            const memberId = Number(m.employee_id);
            return {
               id: m.employee_id.toString(),
               name: `${m.first_name} ${m.last_name || ""}`.trim(),
               role: "",
               avatar:
                  normalizeMedia(
                     m.profile_picture_url || (m as any).avatar || room.avatar_url
                  ) || undefined,
               isOnline: isUserOnline(memberId),
            };
         }),
         memberCount: room.members.length,
         onlineCount: room.members.filter((m: RoomMember) =>
            isUserOnline(Number(m.employee_id))
         ).length,
         lastMessage: room.last_message?.message_text || "",
         timestamp: room.last_message_at || room.created_at,
         isPinned: room.is_pinned,
         hasUnread: room.has_unread,
      };
   }, [room, isGroup, isUserOnline, normalizeMedia]);

   // Wrap imported convertMessage to pass dependencies
   const convertMessageWithDeps = useCallback(
      (msg: Message): ChatMessage => {
         return convertMessage(
            msg,
            room,
            currentUserIdNum,
            senderProfilesMap,
            allUsersData
         );
      },
      [room, currentUserIdNum, senderProfilesMap, allUsersData]
   );

   // Memoize message conversion to avoid re-computing on every render
   const uiMessages = useMemo(
      () => messages.map(convertMessageWithDeps),
      [messages, convertMessageWithDeps]
   );

   // Helper function to format date separators (Today, Yesterday, or date)
   // Memoized to prevent re-creation on every render
   const formatDateSeparator = useCallback((timestamp: string) => {
      const msgDate = new Date(timestamp);
      const today = new Date();
      const yesterday = new Date(today);
      yesterday.setDate(yesterday.getDate() - 1);

      // Reset time to midnight for accurate day comparison
      const msgDay = new Date(
         msgDate.getFullYear(),
         msgDate.getMonth(),
         msgDate.getDate()
      );
      const todayDay = new Date(
         today.getFullYear(),
         today.getMonth(),
         today.getDate()
      );
      const yesterdayDay = new Date(
         yesterday.getFullYear(),
         yesterday.getMonth(),
         yesterday.getDate()
      );

      if (msgDay.getTime() === todayDay.getTime()) {
         return "Today";
      } else if (msgDay.getTime() === yesterdayDay.getTime()) {
         return "Yesterday";
      } else {
         return msgDate.toLocaleDateString("en-US", {
            month: "short",
            day: "numeric",
            year:
               msgDate.getFullYear() !== today.getFullYear()
                  ? "numeric"
                  : undefined,
         });
      }
   }, []);

   // Process messages to add separators (Date)
   const processedItems = useMemo(() => {
      const result: Array<{
         type: "message" | "date";
         data?: ChatMessage;
         date?: string;
      }> = [];
      let lastDate = "";

      // Use originalTimestamp from converted message (no need for messages array)
      uiMessages.forEach((msg) => {
         const fullTimestamp = msg.originalTimestamp || msg.timestamp;

         // Date Separator
         const displayDate = formatDateSeparator(fullTimestamp);

         if (displayDate !== lastDate) {
            result.push({ type: "date", date: displayDate });
            lastDate = displayDate;
         }

         result.push({ type: "message", data: msg });
      });

      return result;
   }, [uiMessages, formatDateSeparator]); // Removed 'messages' dependency

   // Memoize replyingTo message conversion
   const replyingToMessage = useMemo(
      () => (replyingTo ? convertMessageWithDeps(replyingTo) : undefined),
      [replyingTo, convertMessageWithDeps]
   );

   if (!roomId) {
      return (
         <ChatEmptyState
            message="Select a chat to start messaging"
            subMessage="Choose a chat from the left to view messages."
         />
      );
   }

   if (isLoadingRoom) {
      return <ChatEmptyState message="Loading room..." />;
   }

   if (roomError) {
      return (
         <ChatEmptyState
            message="Error loading room. Please try again."
            subMessage={
               roomError instanceof Error ? roomError.message : undefined
            }
         />
      );
   }

   if (!room) {
      return <ChatEmptyState message="Room not found" />;
   }

   return (
      <div className="h-full flex-1 flex flex-col bg-bg-weak rounded-[18px] border border-border p-3 min-w-0 overflow-hidden">
         {isGroup && currentGroup ? (
            <GroupChatHeader group={currentGroup} />
         ) : isDirect && currentUser ? (
            <IndividualChatHeader
               user={currentUser}
               roomAvatarUrl={room?.avatar_url || null}
            />
         ) : null}

         <div className="mt-3 flex-1 flex flex-col rounded-[18px] overflow-hidden relative min-h-0">
            <div
               ref={messagesContainerRef}
               onScroll={handleScroll}
               className="flex-1 overflow-y-auto bg-bg-weak p-6 pb-0 scrollbar-thin scrollbar-thumb-border scrollbar-track-transparent">
               {hasMore && (
                  <div className="flex justify-center mb-4">
                     <button
                        onClick={loadMore}
                        className="px-4 py-2 text-sm bg-background rounded-lg hover:bg-bg-weak">
                        Load older messages
                     </button>
                  </div>
               )}

               {isLoadingMessages && messages.length === 0 ? (
                  <div className="flex justify-center items-center h-full">
                     <p className="text-text-weak">Loading messages...</p>
                  </div>
               ) : messages.length === 0 ? (
                  <div className="flex justify-center items-center h-full">
                     <p className="text-text-weak">
                        No messages yet. Start the conversation!
                     </p>
                  </div>
               ) : (
                  <>
                     <MessageList
                        items={processedItems}
                        currentUserId={currentUserIdNum || 0}
                        onReply={handleReply}
                        messagesEndRef={messagesEndRef}
                        isUserOnline={isUserOnline}
                     />
                     {typingUsers.length > 0 && (
                        <div className="text-sm text-text-weak italic">
                           {typingUsers.map((u) => u.userName).join(", ")}{" "}
                           {typingUsers.length === 1 ? "is" : "are"} typing...
                        </div>
                     )}
                  </>
               )}
            </div>

            {/* Scroll to bottom button */}
            {showScrollButton && (
               <button
                  onClick={() => scrollToBottom("smooth")}
                  className="absolute bottom-20 right-6 z-10 bg-primary text-white p-3 rounded-full shadow-lg hover:bg-primary/90 transition-all duration-200 animate-fadeIn"
                  aria-label="Scroll to bottom">
                  <ArrowDownSLine size={20} />
               </button>
            )}

            <MessageInput
               value={messageValue}
               onChange={handleTypingChange}
               onSend={handleSend}
               onAttachFile={handleAttachFile}
               onVoiceMessage={handleVoiceMessage}
               replyingTo={replyingToMessage}
               onCancelReply={() => setReplyingTo(null)}
            />
         </div>
      </div>
   );
}


export default ChatWindowNew;

/** @format */

import { useState, useMemo, useEffect, useCallback, useRef } from "react";
import { useSearchParams } from "react-router-dom";
import { Plus as PlusIcon } from "@/Icons";
import { IndividualChatListItem } from "./individual";
import { GroupChatListItem } from "./group";
import LoadingState from "@/designSystem/LoadingState";
import { useTranslation } from "@/hooks/useTranslation";
import {
	ChatListItem as ChatListItemType,
	isGroupChat,
	isIndividualChat,
	IndividualChat,
	GroupChat,
} from "./types";
import { CreateGroupChatModal, CreateGroupDetailsModal } from "./group";
import SearchInput from "@/designSystem/SearchInput";
import IconButton from "@/designSystem/IconButton";
import type { Room, ChatUser } from "@/services/chat/types";
import { getCurrentUserId } from "@/utils/auth";
import {
	useCreateGroupRoom,
	useCreateDirectRoom,
	useOnlineUsers,
} from "@/hooks/chat";
import { getChatUsers } from "@/services/chat/chatService";
import { useQuery } from "@tanstack/react-query";
import Avatar from "@/designSystem/Avatar";
import {
	getRoomDisplayName,
	findOtherMember,
	formatTimestamp,
	buildMediaUrl,
} from "./utils";

interface InboxSidebarProps {
	rooms?: Room[];
	isLoading?: boolean;
	onRoomSelect?: (roomId: number | null) => void;
	selectedRoomId?: number | null;
	searchQuery?: string;
	onSearchChange?: (query: string) => void;
}

// Re-export utility functions for backward compatibility
export { getRoomDisplayName, formatTimestamp } from "./utils";

function InboxSidebar({
	rooms,
	isLoading = false,
	onRoomSelect,
	selectedRoomId,
	searchQuery: externalSearchQuery,
	onSearchChange: externalOnSearchChange,
}: InboxSidebarProps) {
	const { t } = useTranslation("common");
	const currentUserId = getCurrentUserId();
	const [searchParams, setSearchParams] = useSearchParams();
	const tabParam = searchParams.get("tab");

	const activeTab: "chats" | "groups" =
		tabParam === "groups" ? "groups" : "chats";

	const hasSetDefaultTab = useRef(false);

	useEffect(() => {
		if (!tabParam && !hasSetDefaultTab.current) {
			hasSetDefaultTab.current = true;
			setSearchParams({ tab: "chats" }, { replace: true });
		}
	}, [tabParam, setSearchParams]);

	const [internalSearchQuery, setInternalSearchQuery] = useState("");
	const [isCreateGroupModalOpen, setIsCreateGroupModalOpen] = useState(false);
	const [isCreateGroupDetailsModalOpen, setIsCreateGroupDetailsModalOpen] =
		useState(false);
	const [selectedMembers, setSelectedMembers] = useState<
		Array<{ id: string; name: string; jobTitle: string; avatar?: string }>
	>([]);

	const { isUserOnline } = useOnlineUsers();

	const getMessageType = useCallback((
		lastMessage: Room["last_message"]
	): "text" | "voice" | "file" | undefined => {
		if (!lastMessage) return undefined;

		if (lastMessage.has_attachment && lastMessage.attachment_mime_type) {
			const mimeType = lastMessage.attachment_mime_type.toLowerCase();
			if (mimeType.startsWith('audio/')) return 'voice';
			if (mimeType.startsWith('image/')) return 'file';
			return 'file';
		}

		if (lastMessage.message_text) return 'text';
		return undefined;
	}, []);

	const createGroupRoom = useCreateGroupRoom();
	const createDirectRoom = useCreateDirectRoom();

	const searchQuery =
		externalSearchQuery !== undefined
			? externalSearchQuery
			: internalSearchQuery;
	const handleSearchChange = externalOnSearchChange || setInternalSearchQuery;

	const { data: usersData, isLoading: isLoadingUsers } = useQuery({
		queryKey: ["chat", "users", searchQuery],
		queryFn: () => getChatUsers(searchQuery || undefined),
		enabled: activeTab === "chats" && !!rooms,
	});

	const convertRoomToChatListItem = useCallback((
		room: Room,
		currentUserId: number | null,
		users: ChatUser[] = []
	): ChatListItemType => {
		if (room.room_type === "direct") {
			const otherMember = findOtherMember(room, currentUserId);

			if (!otherMember) {
				const firstMember = room.members[0];
				const displayName = getRoomDisplayName(room, currentUserId);
				const firstMemberId = firstMember
					? Number(firstMember.employee_id)
					: null;
				const userDetails = firstMemberId ? users.find(u => u.employee_id === firstMemberId) : undefined;
				const avatarUrl =
					normalize(userDetails?.profile_picture_url) ||
					normalize(firstMember?.profile_picture_url) ||
					normalize(room.avatar_url);
				const jobTitle = userDetails?.job_title || "";

				const messageType = getMessageType(room.last_message);
				const isOwnMessage = room.last_message?.sender_id === currentUserId;
				const shouldShowUnread = room.has_unread && !isOwnMessage;

				return {
					id: room.room_id.toString(),
					user: {
						id: firstMember?.employee_id.toString() || "",
						name: displayName,
						jobTitle: jobTitle,
						avatar: avatarUrl || undefined,
						isOnline: isUserOnline(firstMemberId),
					},
					lastMessage: room.last_message?.message_text || "",
					timestamp: formatTimestamp(room.last_message_at),
					isPinned: room.is_pinned,
					hasUnread: shouldShowUnread,
					messageType,
				} as IndividualChat;
			}

			const displayName = getRoomDisplayName(room, currentUserId);
			const otherMemberId = Number(otherMember.employee_id);
			const userDetails = users.find(u => u.employee_id === otherMemberId);
				const avatarUrl =
					normalize(userDetails?.profile_picture_url) ||
					normalize(otherMember.profile_picture_url) ||
					normalize(room.avatar_url);
			const jobTitle = userDetails?.job_title || "";

			const messageType = getMessageType(room.last_message);
			const isOwnMessage = room.last_message?.sender_id === currentUserId;
			const shouldShowUnread = room.has_unread && !isOwnMessage;

			return {
				id: room.room_id.toString(),
				user: {
					id: otherMember.employee_id.toString(),
					name: displayName,
					jobTitle: jobTitle,
					avatar: avatarUrl || undefined,
					isOnline: isUserOnline(otherMemberId),
				},
				lastMessage: room.last_message?.message_text || "",
				timestamp: formatTimestamp(room.last_message_at),
				isPinned: room.is_pinned,
				hasUnread: shouldShowUnread,
				messageType,
			} as IndividualChat;
		} else {
			const displayName = getRoomDisplayName(room, currentUserId);
			const messageType = getMessageType(room.last_message);
			const isOwnMessage = room.last_message?.sender_id === currentUserId;
			const shouldShowUnread = room.has_unread && !isOwnMessage;

			return {
				id: room.room_id.toString(),
				name: displayName,
				avatar: room.avatar_url || undefined,
				members: room.members.map((m) => {
					const memberId = Number(m.employee_id);
					const memberDetails = users.find((u) => u.employee_id === memberId);
					const avatar =
						normalize(m.profile_picture_url) ||
						normalize(memberDetails?.profile_picture_url) ||
						undefined;
					return {
						id: m.employee_id.toString(),
						name: `${m.first_name} ${m.last_name || ""}`.trim(),
						role: "",
						avatar,
						isOnline: isUserOnline(memberId),
					};
				}),
				memberCount: room.members.length,
				onlineCount: room.members.filter((m) =>
					isUserOnline(Number(m.employee_id))
				).length,
				lastMessage: room.last_message?.message_text || "",
				timestamp: formatTimestamp(room.last_message_at),
				isPinned: room.is_pinned,
				hasUnread: shouldShowUnread,
				messageType,
			} as GroupChat;
		}
	}, [isUserOnline, getMessageType]);

	const filteredRooms = useMemo(() => {
		if (!rooms) return [];

		return rooms.filter((room) => {
			const hasMultipleMembers = room.members.length > 1;
			const hasOtherMember = room.members.some((m) => m.employee_id !== currentUserId);

			return room.room_type !== "direct" || (hasMultipleMembers && hasOtherMember);
		});
	}, [rooms, currentUserId]);

	const chatListItems = useMemo(() => {
		if (filteredRooms) {
			return filteredRooms.map((room) =>
				convertRoomToChatListItem(room, currentUserId, usersData?.data || [])
			);
		}
		return [];
	}, [filteredRooms, currentUserId, convertRoomToChatListItem, usersData]);

	const directChats = useMemo(() => {
		return chatListItems.filter((chat) => isIndividualChat(chat));
	}, [chatListItems]);

	const groupChats = useMemo(() => {
		return chatListItems.filter((chat) => isGroupChat(chat));
	}, [chatListItems]);

	const currentList = activeTab === "chats" ? directChats : groupChats;

	const filteredChats = useMemo(() => {
		if (!searchQuery) return currentList;
		const searchLower = searchQuery.toLowerCase();
		return currentList.filter((chat) => {
			if (isGroupChat(chat)) {
				return chat.name.toLowerCase().includes(searchLower);
			}
			return chat.user.name.toLowerCase().includes(searchLower);
		});
	}, [currentList, searchQuery]);

	const handleCreateGroup = async (groupName: string, avatar?: { fileId: number; token: string }) => {
		if (selectedMembers.length === 0) return;

		try {

			// Include current user in member_ids (creator must be a member)
			const memberIds = selectedMembers.map((m) => parseInt(m.id, 10));
			if (currentUserId && !memberIds.includes(currentUserId)) {
				memberIds.push(currentUserId);
			}

			const newRoom = await createGroupRoom.mutateAsync({
				name: groupName,
				member_ids: memberIds,
				...(avatar && { avatar }), // Send avatar object with fileId and token
			});

			setIsCreateGroupDetailsModalOpen(false);
			setSelectedMembers([]);
			setSearchParams({ tab: "groups" }, { replace: false });
			onRoomSelect?.(newRoom.room_id);
		} catch (error: any) {
			console.error('❌ [InboxSidebar] Failed to create group:', error);
			// Show user-friendly error message
			const errorMessage = error?.response?.data?.message || error?.message || 'Failed to create group';
			alert(`Error creating group: ${errorMessage}`);
		}
	};

	const handleUserClick = async (user: ChatUser) => {
		try {
			if (rooms) {
				const existingRoom = rooms.find(
					(room) =>
						room.room_type === "direct" &&
						room.members.some((m) => m.employee_id === user.employee_id)
				);

				if (existingRoom) {
					setSearchParams({ tab: "chats" }, { replace: false });
					onRoomSelect?.(existingRoom.room_id);
					return;
				}
			}

			const newRoom = await createDirectRoom.mutateAsync({
				employee_id: user.employee_id,
			});
			setSearchParams({ tab: "chats" }, { replace: false });
			onRoomSelect?.(newRoom.room_id);
		} catch (error) {
			console.error("Failed to create direct room:", error);
		}
	};

	return (
		<div className='w-full max-w-[360px] h-full flex flex-col bg-background rounded-[16px] border border-border overflow-hidden flex-shrink-0'>
			<div className='px-4 pt-4 pb-3 border-b border-border'>
				<h2 className='text-sm font-semibold text-text-strong mb-3'>Inbox</h2>
				<div className='flex items-center gap-2'>
					<SearchInput
						value={searchQuery}
						onChange={handleSearchChange}
						placeholder='Search Chats'
					/>
					<IconButton
						Icon={PlusIcon}
						ariaLabel='Create group'
						onClick={() => setIsCreateGroupModalOpen(true)}
						className='h-11 w-11 rounded-[10px]'
					/>
				</div>
			</div>

			<div className='px-4 pt-3 pb-2 border-b border-border'>
				<div className='inline-flex w-full max-w-[328px] h-[32px] items-stretch bg-bg-weak p-0.5 rounded-lg gap-[6px]'>
					<button
						onClick={() => {
							setSearchParams({ tab: "chats" }, { replace: false });
							if (directChats.length > 0) {
								onRoomSelect?.(parseInt(directChats[0].id, 10));
							}
						}}
						className={`flex-1 text-xs font-medium rounded-md ${
							activeTab === "chats"
								? "bg-background text-text-strong shadow-sm"
								: "text-text-soft hover:bg-background/50 bg-transparent border-0"
						}`}>
						Chats
					</button>
					<button
						onClick={() => {
							setSearchParams({ tab: "groups" }, { replace: false });
							if (groupChats.length > 0) {
								onRoomSelect?.(parseInt(groupChats[0].id, 10));
							}
						}}
						className={`flex-1 text-xs font-medium rounded-md ${
							activeTab === "groups"
								? "bg-background text-text-strong shadow-sm"
								: "text-text-soft hover:bg-background/50 bg-transparent border-0"
						}`}>
						Groups
					</button>
				</div>
			</div>

			<div className='flex-1 overflow-y-auto scrollbar-hide'>
				{activeTab === "chats" ? (
					(isLoading || isLoadingUsers) ? (
						<LoadingState size="medium" label={t("loading.general")} />
					) : (
						<>
							{filteredChats.map((chat) => {
								const roomId = parseInt(chat.id, 10);
								const isActive = selectedRoomId !== null &&
									  selectedRoomId !== undefined &&
									  selectedRoomId === roomId;

								const handleChatClick = () => {
									if (!isNaN(roomId) && roomId > 0) {
										onRoomSelect?.(roomId);
									}
								};

								return (
									<div key={chat.id} className={isActive ? "bg-bg-weak" : ""}>
										{isIndividualChat(chat) ? (
											<IndividualChatListItem
												chat={{ ...chat, isActive }}
												onClick={handleChatClick}
											/>
										) : (
											<GroupChatListItem
												chat={{ ...chat, isActive }}
												onClick={handleChatClick}
											/>
										)}
									</div>
								);
							})}

							{usersData?.data && usersData.data.length > 0 && (
								<>
									{filteredChats.length > 0 && (
										<div className='px-4 py-2 border-t border-border'>
											<p className='text-xs font-medium text-text-soft uppercase tracking-wide'>
												Start New Chat
											</p>
										</div>
									)}
									{usersData.data
										.filter((user) => {
											if (user.employee_id === currentUserId) return false;
											if (rooms) {
												const hasDirectRoom = rooms.some(
													(room) =>
														room.room_type === "direct" &&
														room.members.some(
															(m) => m.employee_id === user.employee_id
														)
												);
												if (hasDirectRoom) return false;
											}
											return !directChats.some((chat) => {
												if (isIndividualChat(chat)) {
													return chat.user.id === user.employee_id.toString();
												}
												return false;
											});
										})
										.map((user) => (
											<div
												key={user.employee_id}
												className='flex flex-col items-start p-4 gap-2 h-[94px] cursor-pointer bg-background border-b border-border hover:bg-bg-weak transition-colors'
												onClick={() => handleUserClick(user)}>
												<div className='flex flex-row items-start p-0 gap-3 w-full'>
													<Avatar
														src={normalize(user.profile_picture_url)}
														alt={
															user.full_name ||
															`${user.first_name} ${user.last_name}`
														}
														size='md'
														showOnlineIndicator={false}
													/>
													<div className='flex flex-col items-start p-0 gap-1 flex-1 min-w-0'>
														<div className='flex flex-col items-start p-0 gap-0.5 w-full'>
															<div className='flex flex-row justify-between items-center p-0 gap-2 w-full h-5'>
																<h3 className='text-sm font-medium text-text-strong leading-5 tracking-[-0.006em] flex-1'>
																	{user.full_name ||
																		`${user.first_name} ${user.last_name}`}
																</h3>
															</div>
															<p className='text-xs font-normal text-text-soft leading-4 w-full h-4'>
																{user.job_title || ""}
															</p>
														</div>
													</div>
												</div>
											</div>
										))}
								</>
							)}
							{filteredChats.length === 0 &&
								(!usersData?.data || usersData.data.length === 0) && (
									<div className='flex justify-center items-center h-full'>
										<p className='text-text-weak'>No chats yet</p>
									</div>
								)}
						</>
					)
				) : isLoading ? (
					<div className='flex justify-center items-center h-full'>
						<p className='text-text-weak'>Loading groups...</p>
					</div>
				) : filteredChats.length === 0 ? (
					<div className='flex justify-center items-center h-full'>
						<p className='text-text-weak'>No groups yet</p>
					</div>
				) : (
					filteredChats.map((chat) => {
						const roomId = parseInt(chat.id, 10);
						const isActive = selectedRoomId !== null &&
							  selectedRoomId !== undefined &&
							  selectedRoomId === roomId;

						const handleChatClick = () => {
							onRoomSelect?.(roomId);
						};

						return (
							<div key={chat.id} className={isActive ? "bg-bg-weak" : ""}>
								{isIndividualChat(chat) ? (
									<IndividualChatListItem
										chat={{ ...chat, isActive }}
										onClick={handleChatClick}
									/>
								) : (
									<GroupChatListItem
										chat={{ ...chat, isActive }}
										onClick={handleChatClick}
									/>
								)}
							</div>
						);
					})
				)}
			</div>

			<CreateGroupChatModal
				isOpen={isCreateGroupModalOpen}
				onClose={() => {
					setIsCreateGroupModalOpen(false);
					setSelectedMembers([]);
				}}
				onNext={(members) => {
					setSelectedMembers(members);
					setIsCreateGroupModalOpen(false);
					setIsCreateGroupDetailsModalOpen(true);
				}}
			/>

			<CreateGroupDetailsModal
				isOpen={isCreateGroupDetailsModalOpen}
				onClose={() => {
					setIsCreateGroupDetailsModalOpen(false);
					setSelectedMembers([]);
				}}
				onBack={() => {
					setIsCreateGroupDetailsModalOpen(false);
					setIsCreateGroupModalOpen(true);
				}}
				onCreate={handleCreateGroup}
				selectedMembers={selectedMembers}
				isCreating={createGroupRoom.isPending}
			/>
		</div>
	);
}

export default InboxSidebar;
	const normalize = (url?: string | null) =>
		!url || url.startsWith("http") ? url || undefined : buildMediaUrl(url);

import KPICard from "@/designSystem/KPICard";
import ContractsTable from "./ContractsTable";
import ContractsEmptyState from "./ContractsEmptyState";
import ContractsNoResults from "./ContractsNoResults";
import type { Contract } from "./data";
import { useTranslation } from "react-i18next";
import { MemoCheckCircle, MemoMinusCircle } from "@/Icons";
import ContractsToolbar from "./ui/ContractsToolbar";
import { useState, useMemo, useCallback } from "react";
import toast from "@/utilities/toast";
import Modal from "@/designSystem/Modal";
import ConfirmModal from "@/designSystem/ConfirmModal";
import LoadingState from "@/designSystem/LoadingState";
import AddContractWizard from "./addContractWizard/AddContractWizard";
import type { ContractFormData } from "./addContractWizard/types";
import { useAvailableAssetDictionary } from "@/hooks/assets/useAssets";
import {
   useEmployeeDictionary,
   useListEmployees,
} from "@/hooks/employees/useEmployee";
import { useContracts } from "@/hooks/contracts/useContracts";
import { formatPermissionName } from "@/utilities/permissionFormatters";
import type { ContractResponse } from "@/services/contractService";
import { useTableSort, useLocalTableData, useTableFilter } from "@/hooks/table";
import type { ContractFilters } from "./ui/ContractsFilterDropdown";
import { usePermissions } from "@/contexts/PermissionContext";
import NoPermissionMessage from "@/components/common/NoPermissionMessage";

function ContractsContent() {
   const { t } = useTranslation("common");
   const [searchQuery, setSearchQuery] = useState("");
   const [isWizardOpen, setIsWizardOpen] = useState(false);
   const [contractDraft, setContractDraft] = useState<ContractFormData | null>(null);
   const [showDiscardConfirm, setShowDiscardConfirm] = useState(false);
   const { can } = usePermissions();

   const canViewContracts = can("read_contract");
   const canViewEmployees = can("read_employee_basic");
   const canCreateContract = can("create_contract");
   const canTerminateContract = can("terminate_contract");

   const canAccessContracts = canViewContracts || canCreateContract || canTerminateContract;

   // Fetch contracts from API
   const { useList } = useContracts();
   const { data: contractsResponse, isLoading: isLoadingContracts, error: contractsError } = useList(undefined, {
      enabled: canViewContracts,
   });

   // Fetch all employees to map to contracts by employee_id
   const { data: employeesListResponse } = useListEmployees(undefined, {
      enabled: canViewContracts && canViewEmployees,
   });

   // Fetch employees and available assets from API only when wizard is open
   // Only fetch if user can read employees/assets (assets might vary, assumig canViewEmployees implies some access)
   const { data: wizardEmployeesData = [] } = useEmployeeDictionary({
      enabled: canViewContracts && isWizardOpen && canViewEmployees,
   });

   const { data: assetsData = [] } = useAvailableAssetDictionary({
      enabled: canViewContracts && isWizardOpen && can("read_asset"),
   });

   // Transform API contracts to table format
   const transformedContracts = useMemo((): Contract[] => {
      if (!contractsResponse?.data) {
         return [];
      }

      // Create employee map for quick lookup by ID
      const employeeMap = new Map(
         employeesListResponse?.data?.map((emp) => [emp.id, emp]) || []
      );

      return contractsResponse.data.map((apiContract: ContractResponse) => {
         // Try to get employee from API response first, fallback to fetched list
         let employee = apiContract.core.employee;
         if (!employee && apiContract.core.employee_id) {
            const fetchedEmployee = employeeMap.get(
               apiContract.core.employee_id
            );
            if (fetchedEmployee) {
               employee = {
                  id: fetchedEmployee.id,
                  name: fetchedEmployee.name,
                  email: fetchedEmployee.email,
                  avatar: fetchedEmployee.avatar,
                  job_title: fetchedEmployee.job_title,
               };
            }
         }

         const startDate = new Date(apiContract.core.start_date);
         const endDate = apiContract.core.end_date
            ? new Date(apiContract.core.end_date)
            : new Date(startDate.getTime() + 365 * 24 * 60 * 60 * 1000); // Default 1 year if no end date

         // Calculate progress
         const now = new Date();
         const totalDuration = endDate.getTime() - startDate.getTime();
         const elapsed = now.getTime() - startDate.getTime();
         const progress = Math.min(
            100,
            Math.max(0, (elapsed / totalDuration) * 100)
         );

         // Determine status
         let status: "Active" | "Near Expired" | "Expired" | "Terminated" =
            "Active";

         // Check if terminated or ended from API
         if (
            apiContract.status?.toLowerCase() === "terminated" ||
            apiContract.status?.toLowerCase() === "ended" ||
            apiContract.custom_fields?.termination
         ) {
            status = "Terminated";
         } else if (now > endDate) {
            // Contract has passed end date without being terminated
            status = "Expired";
         } else if (progress >= 80) {
            // Contract is 80% through duration
            status = "Near Expired";
         }


         // Calculate years and months duration
         const totalMonths = Math.round(
            totalDuration / (30 * 24 * 60 * 60 * 1000)
         );
         const years = Math.floor(totalMonths / 12);
         const months = totalMonths % 12;

         // Format dates
         const formatDate = (date: Date) => {
            const months = [
               "Jan",
               "Feb",
               "Mar",
               "Apr",
               "May",
               "Jun",
               "Jul",
               "Aug",
               "Sep",
               "Oct",
               "Nov",
               "Dec",
            ];
            return `${date.getDate()} ${
               months[date.getMonth()]
            }, ${date.getFullYear()}`;
         };

         const transformed = {
            id: `#${apiContract.id}`,
            contractName: apiContract.core.contract_name,
            assignedTo: {
               id: employee?.id?.toString() || "0",
               name: !canViewEmployees ? "Unauthorized" : (employee?.name || "Unknown Employee"),
               avatar: employee?.avatar || "/icons/defAvatar.png",
               jobTitle: !canViewEmployees ? "Unauthorized" : (employee?.job_title || "N/A"),
               avatarBg: "bg-[#E1E4EA]",
            },
            status,
            contractDuration: {
               years,
               months,
               startDate: formatDate(startDate),
               endDate: formatDate(endDate),
               progress: Math.round(progress),
            },
            contractAmount: apiContract.compensation?.salary || 0,
         };

         return transformed;
      });
   }, [contractsResponse, employeesListResponse, canViewEmployees]);

   // Calculate KPIs from transformed contracts
   const kpis = useMemo(() => {
      const active = transformedContracts.filter(
         (c) => c.status === "Active"
      ).length;
      const nearExpired = transformedContracts.filter(
         (c) => c.status === "Near Expired"
      ).length;
      const expired = transformedContracts.filter(
         (c) => c.status === "Expired"
      ).length;
      const terminated = transformedContracts.filter(
         (c) => c.status === "Terminated"
      ).length;

      return {
         active,
         nearExpired,
         expired,
         terminated,
         draft: 0, // Not available from current API
      };
   }, [transformedContracts]);

   // ===== NEW TABLE ARCHITECTURE =====
   // Use table sorting hook
   const { sortConfig, handleSort } = useTableSort<Contract>();

   // Use table filter hook
   const { filters, updateFilters } = useTableFilter<ContractFilters>();

   // Handle filter apply
   const handleFiltersApply = useCallback(
      (newFilters: ContractFilters) => {
         updateFilters(newFilters);
      },
      [updateFilters]
   );

   // Custom filter function for contracts
   const contractFilterFn = useCallback((contract: Contract, filters: ContractFilters) => {
      // Status filter
      if (filters.status && filters.status.length > 0) {
         if (!filters.status.includes(contract.status)) {
            return false;
         }
      }

      // Assigned To filter (by employee name)
      if (filters.assignedTo && filters.assignedTo.length > 0) {
         // assignedTo contains employee IDs, we need to match by name
         // This is a simplified check - in production you'd want to match by ID
         const employeeName = contract.assignedTo.name;
         if (!filters.assignedTo.some(id => employeeName.includes(id))) {
            return false;
         }
      }

      // Amount range filter
      if (filters.minAmount !== undefined && contract.contractAmount < filters.minAmount) {
         return false;
      }

      if (filters.maxAmount !== undefined && contract.contractAmount > filters.maxAmount) {
         return false;
      }

      return true;
   }, []);

   // Map sort option IDs to actual contract fields
   const sortFieldMap: Record<string, keyof Contract> = {
      contractName: "contractName",
      assignedTo: "assignedTo",
      status: "status",
      contractAmount: "contractAmount",
   };

   // Process data with local table hook
   const { data: processedContracts } = useLocalTableData({
      data: transformedContracts,
      searchQuery,
      searchFields: ["contractName", "id"],
      sortField: sortConfig?.field ? sortFieldMap[sortConfig.field as string] || sortConfig.field : undefined,
      sortDirection: sortConfig?.direction,
      filters,
      customFilterFn: contractFilterFn,
   });

   const handleSearchChange = (value: string) => {
      setSearchQuery(value);
   };

   const handleAddContractClick = () => {
      setIsWizardOpen(true);
   };

   const isContractDraftDirty = useMemo(() => {
      if (!contractDraft) return false;
      return Boolean(
         contractDraft.contractName ||
            contractDraft.memberId ||
            contractDraft.contractType ||
            contractDraft.startDate ||
            contractDraft.endDate ||
            contractDraft.attachedDocuments?.length ||
            contractDraft.baseSalary ||
            contractDraft.salaryCycle ||
            contractDraft.overtimeRate ||
            contractDraft.assets?.length ||
            contractDraft.noticePeriod ||
            contractDraft.sickLeave ||
            contractDraft.casualLeave ||
            contractDraft.annualLeave ||
            contractDraft.absenceLimit
      );
   }, [contractDraft]);

   const handleWizardClose = () => {
      if (isContractDraftDirty) {
         setShowDiscardConfirm(true);
         return;
      }
      setIsWizardOpen(false);
      setContractDraft(null);
   };

   const handleWizardComplete = async () => {
      toast.success(t("messages.createSuccess"));
      setIsWizardOpen(false);
      setContractDraft(null);
      // TODO: Add API call to save contract data
   };

   // Sample data for contract types and salary cycles - these are usually static
   const availableContractTypes = [
      { id: "full_time", label: "Full Time" },
      { id: "part_time", label: "Part Time" },
      { id: "contract", label: "Contract" },
      { id: "intern", label: "Intern" },
      { id: "temporary", label: "Temporary" },
   ];

   const availableSalaryCycles = [
      { id: "monthly", label: "Monthly" },
      { id: "weekly", label: "Weekly" },
      { id: "biweekly", label: "Bi-Weekly" },
      { id: "yearly", label: "Yearly" },
   ];

   // Use dynamic data from API
   // First, extract active contract employee IDs (stable dependency)
   const activeContractEmployeeIds = useMemo(() => {
      return new Set(
         transformedContracts
            .filter((c) => c.status === "Active")
            .map((c) => c.assignedTo.id)
      );
   }, [transformedContracts]);

   // Filter out employees who already have an ACTIVE contract
   const availableMembers = useMemo(() => {
      return wizardEmployeesData.filter(
         (emp) => !activeContractEmployeeIds.has(emp.id.toString())
      );
   }, [wizardEmployeesData, activeContractEmployeeIds]);

   const availableAssets = assetsData;



   if (!canAccessContracts) {
      return (
         <NoPermissionMessage
            message={t("permissions.noAccess.title", "Access Restricted")}
            description={t("permissions.noAccess.message", "You don't have permission to access the contracts module.")}
         />
      );
   }

   return (
      <>
            {/* Toolbar */}

            {/* KPIs */}
            {canViewContracts && (
                <>
                <div className="flex gap-3 w-full overflow-x-auto pb-2 mb-6">
               <KPICard
                  icon={<MemoCheckCircle className="fill-success" />}
                  label={t("contracts.activeContract")}
                  value={kpis.active.toString()}
               />
               <KPICard
                  icon={<MemoCheckCircle className="fill-warning" />}
                  label={t("contracts.contractNearExpire")}
                  value={kpis.nearExpired.toString()}
               />
               <KPICard
                  icon={<MemoMinusCircle className="fill-text-sub" />}
                  label={t("contracts.draftContract")}
                  value={kpis.draft.toString()}
               />
               <KPICard
                  icon={<MemoCheckCircle className="fill-danger" />}
                  label={t("contracts.expiredContract")}
                  value={kpis.expired.toString()}
               />
               <KPICard
                  icon={<MemoMinusCircle className="fill-error" />}
                  label={t("contracts.terminatedContract")}
                  value={kpis.terminated.toString()}
               />
            </div>
                </>
            )}

            <ContractsToolbar
               searchQuery={searchQuery}
               onSearchChange={handleSearchChange}
               onSortChange={handleSort}
               onAddContractClick={handleAddContractClick}
               onFiltersApply={handleFiltersApply}
               exportData={processedContracts}
               rawData={contractsResponse?.data || []}
               rawDataIdField="id"
            />

            {/* Table Section with Empty/No Results States */}
            {!canViewContracts ? (
               <NoPermissionMessage 
                  message={t("permissions.noReadAccess.title", "Access Restricted")}
                  description={`${t("permissions.noReadAccess.message", "You don't have permission to view contracts.")} (Missing: ${formatPermissionName("read_contract")})`}
                  className="mt-12"
               />
            ) : isLoadingContracts ? (
               <LoadingState size="large" label={t("contracts.loadingContracts")} />
            ) : contractsError ? (
               (contractsError as any)?.response?.status === 403 ? (
                  <NoPermissionMessage 
                     message={t("permissions.noReadAccess.title", "Access Restricted")}
                     description={`${t("permissions.noReadAccess.message", "You don't have permission to view contracts.")} (Missing: ${formatPermissionName("read_contract")})`}
                     className="mt-12"
                  />
               ) : (
                  <div className="flex items-center justify-center py-12">
                     <p className="text-danger">{t("contracts.errorLoadingContracts") || "Failed to load contracts"}</p>
                  </div>
               )
            ) : transformedContracts.length === 0 ? (
               <ContractsEmptyState />
            ) : processedContracts.length === 0 ? (
               <ContractsNoResults />
            ) : (
               <ContractsTable data={processedContracts} />
            )}

         <Modal
            isOpen={isWizardOpen}
            onClose={handleWizardClose}
            title={t("actions.createContract")}
            size="large">
            <AddContractWizard
               onClose={handleWizardClose}
               onComplete={handleWizardComplete}
               onFormDataChange={setContractDraft}
               availableMembers={availableMembers}
               availableContractTypes={availableContractTypes}
               availableSalaryCycles={availableSalaryCycles}
               availableAssets={availableAssets}
            />
         </Modal>
         <ConfirmModal
            isOpen={showDiscardConfirm}
            onClose={() => setShowDiscardConfirm(false)}
            onConfirm={() => {
               setShowDiscardConfirm(false);
               setIsWizardOpen(false);
               setContractDraft(null);
            }}
            title={t("unsavedChanges.title")}
            description={t("unsavedChanges.description")}
            confirmText={t("unsavedChanges.confirm")}
            cancelText={t("unsavedChanges.cancel")}
         />
      </>
   );
}

export default ContractsContent;

