                     />
                     <YAxis
                        tickLine={false}
                        axisLine={false}
                        tickMargin={8}
                        tick={<CustomYAxisTick />}
                     />
                     <ChartTooltip
                        cursor={false}
                        content={<CustomTooltipContent />}
