	const getTabClassName = (isActive: boolean) =>
		`!px-4 !py-1 !text-sm !font-medium !rounded-md !transition-colors ${
			isActive
				? "!bg-background !shadow-sm !text-text-strong hover:!bg-background"
				: "!text-text-soft hover:!bg-background/50 !bg-transparent !border-0"
		}`;

	return (
		<div
			className={`flex items-center gap-4 mb-6 ${
				isRTL ? "flex-row-reverse" : ""
			}`}
			dir={isRTL ? "rtl" : "ltr"}>
			{/* Tabs */}
			<div className='bg-bg-weak flex p-0.5 rounded-lg w-fit'>
				<Button
					onClick={() => onTabChange("all")}
					className={getTabClassName(activeTab === "all")}>
					{t("invoices.tabs.all")}
				</Button>
				<Button
					onClick={() => onTabChange("draft")}
					className={getTabClassName(activeTab === "draft")}>
					{t("invoices.tabs.draft")}
				</Button>
				<Button
					onClick={() => onTabChange("pending")}
					className={getTabClassName(activeTab === "pending")}>
					{t("invoices.tabs.pending")}
				</Button>
				<Button
					onClick={() => onTabChange("partially_paid")}
					className={getTabClassName(activeTab === "partially_paid")}>
					{t("invoices.tabs.partially_paid")}
				</Button>
				<Button
					onClick={() => onTabChange("fully_paid")}
					className={getTabClassName(activeTab === "fully_paid")}>
					{t("invoices.tabs.fully_paid")}
				</Button>
				<Button
					onClick={() => onTabChange("cancelled")}
					className={getTabClassName(activeTab === "cancelled")}>
					{t("invoices.tabs.cancelled")}
				</Button>
				<Button
					onClick={() => onTabChange("gov_paid")}
					className={getTabClassName(activeTab === "gov_paid")}>
					{t("invoices.tabs.gov_paid")}
				</Button>
			</div>

			{/* Search, Filter, and Sort */}
			<div
				className={`flex items-center gap-2 flex-1 ${
					isRTL ? "justify-start" : "justify-end"
				}`}>
				<div className='max-w-xs flex-1'>
					<div className='relative'>
						<div
							className={`absolute top-1/2 -translate-y-1/2 ${
								isRTL ? "right-3" : "left-3"
							}`}>
							<Search2Line size={20} />
						</div>
						<input
							type='text'
							placeholder={t("invoices.searchPlaceholder")}
							value={searchQuery}
							onChange={(e) => onSearchChange(e.target.value)}
							className={`w-full ${
								isRTL ? "pr-10 pl-3" : "pl-10 pr-3"
							} py-2 text-sm border border-border rounded-lg bg-background text-text-sub placeholder:text-text-soft focus:outline-none focus:ring-2 focus:ring-primary/20`}
							dir={isRTL ? "rtl" : "ltr"}
						/>
					</div>
				</div>

				<div
					className={`flex items-center gap-2 ${
						isRTL ? "flex-row-reverse" : ""
					}`}>
					<InvoicesFilterDropdown onApply={onFiltersApply} />

					<SortDropdown
						label={t("invoices.sortBy")}
						options={sortOptions}
						onSelect={onSortChange}
					/>

					<ExportButton
						data={exportData}
						rawData={rawData}
						idField={rawDataIdField}
						filename="invoices"
						sheetName="Invoices"
					/>

					<PermissionGate permission="create_invoice">
						<Button onClick={onAddInvoiceClick} className='px-4'>
							<Plus size={20} className='text-white fill-white' />
							<span className='whitespace-nowrap'>
								{t("invoices.addInvoice")}
							</span>
						</Button>
					</PermissionGate>
				</div>
			</div>
		</div>
	);
}

