/** @format */

import { useState, useEffect, useMemo, useRef } from "react";
import { motion } from "framer-motion";
import Button from "@/designSystem/Button";
import StepIndicator from "@/designSystem/StepIndicator";
import StepCaseBasics from "./StepCaseBasics";
import StepPeopleAndFiles from "./StepPeopleAndFiles";
import StepCaseSummary from "./StepCaseSummary";
import { type AddCaseWizardProps, type CaseFormData, STEPS } from "./types";
import { caseSchema } from "@/utilities/schemas/caseSchema";
import { UseFormReturn } from "react-hook-form";
import { buildValidationSummaryItems } from "@/designSystem/GenericForm";
import toast from "@/utilities/toast";

function AddCaseWizard({
	onSubmit,
	onCancel,
	onFormDataChange,
	initialData,
}: AddCaseWizardProps) {
	const [currentStep, setCurrentStep] = useState(1);
	const [isValidating, setIsValidating] = useState(false);
	const step1FormRef = useRef<UseFormReturn<any> | null>(null);

	// Initialize form data
	const getInitialFormData = (): CaseFormData => {
		return (
			initialData || {
				title: "",
				caseType: "",
				caseNumber: "",
				year: "",
				client: "",
				people: [],
				files: [],
				description: "",
			}
		);
	};

	const [formData, setFormData] = useState<CaseFormData>(getInitialFormData());

	// Reset form data when initialData changes
	useEffect(() => {
		if (initialData) {
			setFormData(initialData);
			setCurrentStep(1);
		} else {
			setFormData({
				title: "",
				caseType: "",
				caseNumber: "",
				year: "",
				client: "",
				people: [],
				files: [],
				description: "",
			});
			setCurrentStep(1);
		}
	}, [initialData]);

	// Notify parent component of form data changes
	useEffect(() => {
		if (onFormDataChange) {
			onFormDataChange(formData);
		}
	}, [formData, onFormDataChange]);

	const validateStepOne = async () => {
		if (!step1FormRef.current) return true;
		let isValid = false;
		await step1FormRef.current.handleSubmit(
			() => {
				isValid = true;
			},
			(errors) => {
				isValid = false;
				const { items } = buildValidationSummaryItems(errors, {}, {});
				if (items[0]) {
					step1FormRef.current?.setFocus(items[0].field as never);
				}
			}
		)();
		return isValid;
	};

	const validateStepTwo = async () => {
		try {
			await caseSchema
				.pick(["people", "files"])
				.validate(
					{ people: formData.people, files: formData.files },
					{ abortEarly: false }
				);
			return true;
		} catch (error) {
			if (error instanceof Error) {
				toast.error(error.message);
			}
			return false;
		}
	};

	const validateStepThree = async () => {
		try {
			await caseSchema
				.pick(["description"])
				.validate({ description: formData.description }, { abortEarly: false });
			return true;
		} catch (error) {
			if (error instanceof Error) {
				toast.error(error.message);
			}
			return false;
		}
	};

	const validateCurrentStep = async (): Promise<boolean> => {
		if (currentStep === 1) {
			return validateStepOne();
		}
		if (currentStep === 2) {
			return validateStepTwo();
		}
		if (currentStep === 3) {
			return validateStepThree();
		}
		return true;
	};

	const handleNext = async () => {
		setIsValidating(true);
		const isValid = await validateCurrentStep();
		setIsValidating(false);
		if (!isValid) return;

		if (currentStep < STEPS.length) {
			setCurrentStep(currentStep + 1);
		} else {
			onSubmit(formData);
		}
	};

	const handleBack = () => {
		if (currentStep > 1) {
			setCurrentStep(currentStep - 1);
		} else {
			onCancel();
		}
	};

	const updateFormData = (field: keyof CaseFormData, value: unknown) => {
		setFormData((prev) => ({ ...prev, [field]: value }));
	};

	// Check if save button should be disabled
	const isSaveDisabled = useMemo(() => {
		// Only disable on the last step (Save button)
		if (currentStep !== STEPS.length) return false;

		// For new case, require all basic fields
		return (
			!formData.title.trim() ||
			!formData.caseType ||
			!formData.caseNumber.trim() ||
			!formData.year.trim() ||
			!formData.client.trim()
		);
	}, [currentStep, formData]);

	return (
		<div className='flex flex-col h-full'>
			<div className='flex flex-col xl:flex-row flex-1 overflow-hidden'>
				{/* Left Sidebar - Steps */}
				<div className='w-full xl:w-auto xl:min-w-[500px] bg-bg-weak ps-4 sm:ps-6 md:ps-8 xl:ps-32 pe-4 sm:pe-6 pt-4 pb-4 flex flex-col'>
					<StepIndicator
						steps={STEPS}
						currentStep={currentStep}
						onStepChange={async (step) => {
							if (step <= currentStep) {
								setCurrentStep(step);
								return;
							}
							setIsValidating(true);
							const isValid = await validateCurrentStep();
							setIsValidating(false);
							if (isValid) {
								setCurrentStep(step);
							}
						}}
					/>
				</div>

				{/* Right Content Area */}
				<div className='flex-1 flex flex-col overflow-hidden'>
					<div className='flex-1 overflow-y-auto pl-4 sm:pl-6 md:pl-8 xl:pl-32 pr-4 sm:pr-6 md:pr-8 pt-4 pb-4 bg-bg-weak [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]'>
						<motion.div
							key={currentStep}
							initial={{ opacity: 0, x: 0, y: 10 }}
							animate={{ opacity: 1, x: 0, y: 0 }}
							exit={{ opacity: 0, x: 0, y: -10 }}
							transition={{ duration: 0.3 }}>
							{currentStep === 1 && (
								<StepCaseBasics
									formData={formData}
									updateFormData={updateFormData}
									formRef={step1FormRef}
								/>
							)}
							{currentStep === 2 && (
								<StepPeopleAndFiles
									formData={formData}
									updateFormData={updateFormData}
								/>
							)}
							{currentStep === 3 && (
								<StepCaseSummary
									formData={formData}
									updateFormData={updateFormData}
								/>
							)}
						</motion.div>
					</div>
				</div>
			</div>

			{/* Footer Actions */}
			<div className='flex flex-col md:flex-row items-stretch md:items-center justify-end gap-2 sm:gap-3 px-4 sm:px-6 md:px-8 pt-3 sm:pt-4 pb-3 sm:pb-4 border-t border-border'>
				<Button
					variant='secondary'
					onClick={handleBack}
					disabled={isValidating}
					className='w-full md:w-auto px-4 sm:px-6 py-2.5 sm:py-3 text-[#d1d1d1] bg-gray-100 hover:bg-gray-200 rounded-xl sm:rounded-2xl !border-0'>
					Back
				</Button>
				<Button
					variant='primary'
					onClick={handleNext}
					disabled={isSaveDisabled || isValidating}
					className='w-full md:w-auto px-4 sm:px-6 py-2.5 sm:py-3 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed transition-all'>
					{isValidating
						? "Validating..."
						: currentStep === STEPS.length
						? "Create Case"
						: "Continue"}
				</Button>
			</div>
		</div>
	);
}

