	const activities = activitiesResponse?.data || [];
	const events = eventsResponse?.data || [];

	const handleAddPeople = (selectedPeople: any[]) => {
		selectedPeople.forEach((person) => {
			addEmployeeMutation.mutate({
				caseId: legalCase.id,
				data: {
					employee_id: person.id,
					role: "Viewer",
				},
			});
		});
		setIsAddPeopleModalOpen(false);
	};

	const handleUpdateSummary = (newSummary: string) => {
		updateCaseMutation.mutate({
			id: legalCase.id,
			data: { summary: newSummary }
		});
	};

	const handleAddEvent = (data: AddUpdateFormValues) => {
		createEventMutation.mutate({
			caseId: legalCase.id,
			data: {
				event_title: data.title,
				event_date: data.date,
				description: data.description,
			}
		});
		setIsAddUpdateModalOpen(false);
	};

	const handleEditEvent = (data: EditEventFormValues) => {
		if (!editingEvent) return;
		updateEventMutation.mutate({
			caseId: legalCase.id,
			eventId: editingEvent.id,
			data: {
				event_title: data.event_title,
				event_date: data.event_date,
				description: data.description,
			},
		});
		setEditingEvent(null);
	};

const handleEditCaseDetails = (data: EditCaseDetailsFormValues) => {
		const toApiStatus = (status?: string) => {
			if (!status) return undefined;
			const normalized = status.toLowerCase().replace(/_/g, " ");
			if (normalized === "open") return "Open";
			if (normalized === "in progress") return "In Progress";
			if (normalized === "closed") return "Closed";
			if (normalized === "on hold") return "On Hold";
			if (normalized === "cancelled") return "Cancelled";
			return status;
		};

		updateCaseMutation.mutate({
			id: legalCase.id,
			data: {
				...data,
				status: toApiStatus(data.status),
			},
		});
		setIsEditCaseModalOpen(false);
	};

	const handleCloseCase = () => {
		updateCaseMutation.mutate({
			id: legalCase.id,
			data: {
				status: "Closed",
				end_date: new Date().toISOString().split("T")[0],
			},
		});
		setIsCloseCaseModalOpen(false);
	};

	const handleAddDocument = (data: { file_id: number; file_name?: string; event_id?: number }) => {
		attachDocumentMutation.mutate({
			caseId: legalCase.id,
			data,
		});
		setIsAddDocumentModalOpen(false);
	};

	const handleDeleteDocument = (documentId: string) => {
		removeDocumentMutation.mutate({
			caseId: legalCase.id,
			documentId,
		});
	};

	return (
		<div className='flex-1 overflow-y-auto px-6 py-6 relative'>
			{/* Case Header Section */}
			<div className='bg-bg-weak border border-border rounded-2xl p-5 mb-6'>
				<div className='flex items-center gap-8 mb-6'>
					<div className='flex items-center gap-4 flex-1'>
						<IconButton
							Icon={ArrowLeftSmall}
							ariaLabel='Back'
							variant='ghost'
							onClick={onBack}
							className='border border-border bg-background'
						/>
						<div className='flex items-center gap-2'>
							<h1 className='text-xl font-medium text-text-strong'>
								{legalCase.title}
							</h1>
							<BadgeTag
								label={t(`legalCases.status.${getLegalCaseStatusLabel(legalCase.status)}`)}
								variant={getLegalCaseStatusVariant(legalCase.status)}
								size='sm'
							/>
						</div>
					</div>
					<div className='flex items-center gap-3'>
						{/* <IconButton
							Icon={MoreVertical}
							ariaLabel='More options'
							variant='ghost'
							className='border border-border bg-background'
						/> */}
						{legalCase.status !== "closed" && (
							<Button variant='primary' onClick={() => setIsCloseCaseModalOpen(true)}>
								<span>Close Case</span>
							</Button>
						)}
					</div>
				</div>

				{/* Case Details Grid */}
				<div className='grid grid-cols-4 gap-6'>
					<div className='flex flex-col gap-1'>
						<p className='text-sm text-text-soft'>Case Type</p>
						<p className='text-base font-medium text-text-strong'>
							{legalCase.type}
						</p>
					</div>
					<div className='flex flex-col gap-1'>
						<p className='text-sm text-text-soft'>Case Number/Year</p>
						<p className='text-base font-medium text-text-strong'>
							{legalCase.case_number}
						</p>
					</div>
					<div className='flex flex-col gap-1'>
					<p className='text-sm text-text-soft'>Lawyer Name</p>
						<MemberTag2
							name={
								legalCase.Lawyer
									? `${legalCase.Lawyer.first_name} ${legalCase.Lawyer.last_name}`
									: legalCase.assigned_to_name || "-"
							}
							avatar={legalCase.Lawyer?.avatar || "/icons/defAvatar.png"}
							jobTitle={legalCase.Lawyer?.job_title}
							onClick={() => {
								if (legalCase.Lawyer?.employee_id) {
									navigate(`/dashboard/members/profile/${legalCase.Lawyer.employee_id}`);
								}
							}}
							className={legalCase.Lawyer?.employee_id ? "cursor-pointer" : ""}
						/>
				</div>
					<div className='flex flex-col gap-1'>
						<p className='text-sm text-text-soft'>Client</p>
						<p className='text-base font-medium text-text-strong'>
							{legalCase.client || "-"}
						</p>
					</div>
				</div>
			</div>

			{/* Tabs */}
			<div className='flex items-center gap-6 border-b border-border mb-6'>
				<button
					onClick={() => setActiveTab("information")}
					className={`flex items-center gap-1.5 pb-3.5 px-1 relative cursor-pointer ${
						activeTab === "information"
							? "text-text-strong border-b-2 border-primary"
							: "text-text-sub"
					}`}>
					<ClipboardList
						size={20}
						className={
							activeTab === "information" ? "fill-primary" : "fill-text-sub"
						}
					/>
					<span className='text-sm font-medium'>Case Information</span>
				</button>
				<button
					onClick={() => setActiveTab("documents")}
					className={`flex items-center gap-1.5 pb-3.5 px-1 relative cursor-pointer ${
						activeTab === "documents"
							? "text-text-strong border-b-2 border-primary"
							: "text-text-sub"
					}`}>
					<Files
						size={20}
						className={
							activeTab === "documents" ? "fill-primary" : "fill-text-sub"
						}
					/>
					<span className='text-sm font-medium'>Documents</span>
					<span className='bg-bg-weak text-text-sub text-xs font-medium px-1.5 py-0.5 rounded-full ml-1'>
						{documents.length}
					</span>
				</button>
			</div>

			{/* Main Content */}
			<div className='flex gap-6'>
				{/* Left Column */}
				<div className='flex-[3] flex flex-col gap-6'>
					{activeTab === "information" && (
						<CaseInformationContent 
							summary={legalCase.description} 
							events={events}
							onUpdateSummary={handleUpdateSummary}
							onAddEvent={() => setIsAddUpdateModalOpen(true)}
							onEditEvent={(event) => setEditingEvent(event)}
						/>
					)}
					{activeTab === "documents" && (
						<DocumentsContent 
							documents={documents} 
							onAddDocument={() => setIsAddDocumentModalOpen(true)}
							onDeleteDocument={handleDeleteDocument}
						/>
					)}
				</div>

				{/* Right Sidebar */}
				{activeTab === "information" && (
					<div className='flex-[2] flex flex-col gap-6'>
						{/* Activity Log */}
						<div className='bg-background border border-border rounded-2xl p-4 shadow-sm flex flex-col gap-5'>
							<h2 className='text-lg font-medium text-text-strong'>
								Activity Log
							</h2>
							<div className='flex flex-col relative'>
								{/* Connecting line - spans from first to last circle */}
								<div
									className='absolute left-5 top-10 w-0.5 border-l border-dashed border-[#d1d1d1]'
									style={{ height: "calc(100% - 40px)" }}
								/>

								{activities.length === 0 && (
									<p className='text-sm text-text-soft py-4 text-center'>
										No activity recorded yet.
									</p>
								)}

								{activities.map((activity) => {
									const performedAt = activity.performed_at
										? new Date(activity.performed_at)
										: null;
									const showDate =
										performedAt && isValid(performedAt)
											? format(performedAt, "dd MMMM, yyyy")
											: null;
									const showTime =
										performedAt && isValid(performedAt)
											? format(performedAt, "hh:mm a")
											: null;

									return (
										<div key={activity.id} className='flex gap-4 relative'>
											<div className='flex flex-col items-center'>
												<div className='w-10 h-10 rounded-full bg-background border border-border flex items-center justify-center shadow-sm p-2 relative z-10'>
													{activity.action === "created" ? (
														<Loader2Line size={24} className='fill-text-sub' />
													) : (
														<FileText size={24} className='fill-primary' />
													)}
												</div>
											</div>
											<div className='flex-1 flex flex-col gap-3 pb-5'>
												<div className='flex flex-col gap-1'>
													<h3 className='text-base font-medium text-text-strong leading-6'>
														{activity.action}
													</h3>
													<p className='text-sm text-text-sub leading-5'>
														{activity.description}
													</p>
												</div>
												{(showDate || showTime) && (
													<div className='flex items-center gap-2 text-xs text-text-sub leading-4'>
														{showDate && <span>{showDate}</span>}
														{showDate && showTime && <span>•</span>}
														{showTime && <span>{showTime}</span>}
													</div>
												)}
											</div>
										</div>
									);
								})}
							</div>
						</div>

						{/* People Involved */}
						<div className='bg-background border border-border rounded-2xl p-4 shadow-sm flex flex-col gap-5'>
							<div className='flex items-center justify-between gap-2'>
								<h2 className='text-lg font-medium text-text-strong'>
									People Involved
								</h2>
								<button
									onClick={() => setIsAddPeopleModalOpen(true)}
									className='flex items-center gap-1 text-primary text-sm font-medium cursor-pointer'>
									<AddLine size={20} className='fill-primary' />
									<span>Add People</span>
								</button>
							</div>
							<div className='flex flex-col gap-6'>
								{employees.length === 0 && (
									<p className='text-sm text-text-soft py-4 text-center'>
										No people assigned yet.
									</p>
								)}
								{employees.map((employee) => {
									const fullName = employee.Employee
										? `${employee.Employee.first_name} ${employee.Employee.last_name}`
										: employee.name || "Unknown";
									const employeeId = employee.employee_id;
									const avatarUrl = employee.Employee?.avatar || employee.avatar || "/icons/defAvatar.png";

									const jobTitle = employee.Employee?.job_title || employee.role;

									return (
										<MemberTag1
											key={employee.id}
											name={fullName}
											jobTitle={jobTitle}
											avatar={avatarUrl}
											onClick={() => {
												window.location.href = `/dashboard/members/profile/${employeeId}`;
											}}
										/>
									);
								})}
							</div>
						</div>
					</div>
				)}
			</div>

			{/* Add People Modal */}
			<AddPeopleModal
				isOpen={isAddPeopleModalOpen}
				onClose={() => setIsAddPeopleModalOpen(false)}
				onAdd={handleAddPeople}
				existingPeople={employees.map((e) => ({
					id: String(e.employee_id),
					name: e.name,
					role: e.role,
				}))}
			/>

			{/* Add Update Modal */}
			<AddUpdateModal
				isOpen={isAddUpdateModalOpen}
				onClose={() => setIsAddUpdateModalOpen(false)}
				onAdd={handleAddEvent}
			/>

			{/* Edit Case Details Modal */}
			<EditCaseDetailsModal
				isOpen={isEditCaseModalOpen}
				onClose={() => setIsEditCaseModalOpen(false)}
				legalCase={legalCase}
				onUpdate={handleEditCaseDetails}
			/>

			{/* Edit Event Modal */}
			{editingEvent && (
				<EditEventModal
					isOpen={!!editingEvent}
					onClose={() => setEditingEvent(null)}
					event={editingEvent}
					onUpdate={handleEditEvent}
				/>
			)}

			{/* Close Case Modal */}
			<CloseCaseModal
				isOpen={isCloseCaseModalOpen}
				onClose={() => setIsCloseCaseModalOpen(false)}
				onConfirm={handleCloseCase}
				caseTitle={legalCase.title}
			/>

			{/* Add Document Modal */}
			<AddDocumentModal
				isOpen={isAddDocumentModalOpen}
				onClose={() => setIsAddDocumentModalOpen(false)}
				onAdd={handleAddDocument}
				events={events}
			/>
		</div>
	);
}

import { useState, useCallback, useEffect } from "react";
import { useNavigate } from "react-router-dom";

import LoadingState from "@/designSystem/LoadingState";
import LoadingOverlay from "@/designSystem/LoadingOverlay";
import LegalCasesTable from "./LegalCasesTable";
import LegalCasesToolbar from "./ui/LegalCasesToolbar";
import type { LegalCaseFilters } from "./ui/LegalCasesFilterDropdown";
import { format } from "date-fns";
import LegalCasesFloatingActionBar from "./LegalCasesFloatingActionBar";
import type { LegalCase } from "./data";
import ConfirmModal from "@/designSystem/ConfirmModal";
import Modal from "@/designSystem/Modal";
import AddCaseWizard from "./AddCaseWizard/AddCaseWizard";
import { formatPermissionName } from "@/utilities/permissionFormatters";
import type { CaseFormData } from "./AddCaseWizard/types";
import { useTranslation } from "@/hooks/useTranslation";
import {
	useListLegalCases,
	useGetLegalCaseById,
} from "@/hooks/legalCases/legalCase.queries";
import {
	useCreateLegalCase,
	useDeleteLegalCase,
} from "@/hooks/legalCases/legalCase.mutations";
import toast from "@/utilities/toast";
import { usePermissions } from "@/contexts/PermissionContext";
import NoPermissionMessage from "@/components/common/NoPermissionMessage";

function LegalCasesContent() {
	const { t } = useTranslation("settings");
	const { t: tCommon } = useTranslation("common");
	const navigate = useNavigate();
	const { can } = usePermissions();
	const canViewCases = can("read_legal_case");
    const canCreateCases = can("create_legal_case");
    const canUpdateCases = can("update_legal_case");
    const canDeleteCases = can("delete_legal_case");

    const canAccessCases = canViewCases || canCreateCases || canUpdateCases || canDeleteCases;

	const [searchQuery, setSearchQuery] = useState("");
	const [sortBy, setSortBy] = useState<string>("created_at");
	const [sortOrder, setSortOrder] = useState<"asc" | "desc">("desc");
	const [page] = useState(1);
	const [limit] = useState(10);
	const [filters, setFilters] = useState<LegalCaseFilters>({});

	// State for details and delete actions
	const [selectedCase, setSelectedCase] = useState<LegalCase | null>(null);
	const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
	const [selectedRows, setSelectedRows] = useState<LegalCase[]>([]);
	const [bulkDeleteModalState, setBulkDeleteModalState] = useState<{
		isOpen: boolean;
		cases: LegalCase[];
	}>({
		isOpen: false,
		cases: [],
	});

	// State for add case modal
	const [isAddCaseModalOpen, setIsAddCaseModalOpen] = useState(false);
	const [editingCase, setEditingCase] = useState<LegalCase | null>(null);
	const [editingCaseId, setEditingCaseId] = useState<string | null>(null);
	const [initialCaseData, setInitialCaseData] = useState<
		CaseFormData | undefined
	>();
	const [caseDraft, setCaseDraft] = useState<CaseFormData | null>(null);
	const [showDiscardConfirm, setShowDiscardConfirm] = useState(false);

	const createCaseMutation = useCreateLegalCase();
	const deleteCaseMutation = useDeleteLegalCase();

	const { data, isLoading, isError, error, refetch } = useListLegalCases(
		{
			page,
			limit,
			search: searchQuery || undefined,
			sort_by: sortBy,
			sort_order: sortOrder,
			status: filters.status,
			lawyer_id: filters.lawyerId,
			start_date: filters.dateFrom
				? format(filters.dateFrom, "yyyy-MM-dd")
				: undefined,
			end_date: filters.dateTo
				? format(filters.dateTo, "yyyy-MM-dd")
				: undefined,
		},
		{ enabled: canViewCases }
	);

	const { data: caseDetails, isLoading: isLoadingDetails } = useGetLegalCaseById(
		editingCaseId,
		{ enabled: canViewCases && !!editingCaseId }
	);

	const mapCaseToForm = useCallback((legalCase: LegalCase): CaseFormData => {
		const extractYear = (): string => {
			if (legalCase.start_date && /^\d{4}/.test(legalCase.start_date)) {
				return legalCase.start_date.slice(0, 4);
			}
			const match = legalCase.case_number.match(/(\d{4})/);
			return match ? match[1] : "";
		};

		return {
			title: legalCase.title || "",
			caseType: legalCase.case_type_id
				? String(legalCase.case_type_id)
				: "",
			caseNumber: legalCase.case_number || "",
			year: extractYear(),
			client: legalCase.client || "",
			people: [], // Should come from details
			files: [], // Should come from details
			description: legalCase.description || "",
		};
	}, []);

	useEffect(() => {
		if (caseDetails && editingCaseId) {
			setInitialCaseData(mapCaseToForm(caseDetails as unknown as LegalCase));
			setIsAddCaseModalOpen(true);
		}
	}, [caseDetails, editingCaseId, mapCaseToForm]);

	const handleSortChange = (optionId: string) => {
		const sortMap: Record<
			string,
			{ sort_by: string; sort_order: "asc" | "desc" }
		> = {
			dateCreated: { sort_by: "created_at", sort_order: "desc" },
			lastUpdated: { sort_by: "updated_at", sort_order: "desc" },
			caseNumber: { sort_by: "case_number", sort_order: "asc" },
			title: { sort_by: "title", sort_order: "asc" },
		};

		const sortConfig = sortMap[optionId];
		if (sortConfig) {
			setSortBy(sortConfig.sort_by);
			setSortOrder(sortConfig.sort_order);
		}
	};

	const handleFiltersApply = (newFilters: LegalCaseFilters) => {
		setFilters(newFilters);
	};

	const handleAddCaseClick = () => {
		setIsAddCaseModalOpen(true);
		setEditingCase(null);
		setEditingCaseId(null);
		setInitialCaseData(undefined);
		setCaseDraft(null);
	};

	const isCaseDraftDirty = (() => {
		if (!caseDraft) return false;
		const baseline =
			initialCaseData ||
			({
				title: "",
				caseType: "",
				caseNumber: "",
				year: "",
				client: "",
				people: [],
				files: [],
				description: "",
			} as CaseFormData);
		return (
			caseDraft.title !== baseline.title ||
			caseDraft.caseType !== baseline.caseType ||
			caseDraft.caseNumber !== baseline.caseNumber ||
			caseDraft.year !== baseline.year ||
			caseDraft.client !== baseline.client ||
			caseDraft.description !== baseline.description ||
			caseDraft.people.length !== baseline.people.length ||
			caseDraft.files.length !== baseline.files.length
		);
	})();

	const handleCloseAddCaseModal = () => {
		if (isCaseDraftDirty) {
			setShowDiscardConfirm(true);
			return;
		}
		setIsAddCaseModalOpen(false);
		setEditingCaseId(null);
		setCaseDraft(null);
	};

	const handleSubmitCase = async (data: CaseFormData) => {
		try {
			// TODO: Handle Edit logic if editingCase is set
			const parsedCaseTypeId = data.caseType ? Number(data.caseType) : undefined;
			const peoplePayload = (data.people || [])
				.map((person) => ({
					employee_id: Number(person.personId),
					role: person.role,
				}))
				.filter(
					(person) =>
						Number.isFinite(person.employee_id) && person.employee_id > 0
				);
			const attachmentsPayload = (data.files || [])
				.filter((file) => Boolean(file.fileId))
				.map((file) => ({
					fileId: file.fileId as number | string,
					fileName: file.fileName,
				}));

			await createCaseMutation.mutateAsync({
				case_number: data.caseNumber?.trim() || undefined,
				title: data.title,
				summary: data.description?.trim() || "",
				client_name: data.client?.trim() || undefined,
				lawyer_id: 1,
				status: "Open",
				start_date: data.year ? `${data.year}-01-01` : undefined,
				end_date: data.year ? `${data.year}-12-31` : undefined,
				case_type_id:
					parsedCaseTypeId && !Number.isNaN(parsedCaseTypeId)
						? parsedCaseTypeId
						: undefined,
				people: peoplePayload.length ? peoplePayload : undefined,
				core: attachmentsPayload.length
					? { attachments: attachmentsPayload }
					: undefined,
			});
			setIsAddCaseModalOpen(false);
			setEditingCaseId(null);
			setCaseDraft(null);
			refetch();
		} catch (error) {
			console.error("Error creating case:", error);
		}
	};

	const handleViewDetails = (legalCase: LegalCase) => {
		navigate(`/dashboard/legal-cases/${legalCase.id}`);
	};

	const handleEditClick = useCallback((legalCase: LegalCase) => {
		setEditingCase(legalCase);
		setEditingCaseId(legalCase.id);
		// Modal will open via useEffect when data loads
	}, []);

	const handleDeleteClick = (legalCase: LegalCase) => {
		setSelectedCase(legalCase);
		setIsDeleteModalOpen(true);
	};

	const handleConfirmDelete = async () => {
		if (selectedCase) {
			try {
				await deleteCaseMutation.mutateAsync(selectedCase.id);
				toast.success(
					t("legalCases.toast.deleteSuccess") || "Case deleted successfully"
				);
				setIsDeleteModalOpen(false);
				setSelectedCase(null);
				refetch();
			} catch (error) {
				console.error("Error deleting case:", error);
				toast.error(
					t("legalCases.toast.deleteError") || "Failed to delete case"
				);
			}
		}
	};

	const handleRowSelectionChange = useCallback((selectedRows: LegalCase[]) => {
		setSelectedRows(selectedRows);
		// selectedRows is used by the floating action bar via renderFloatingBar
	}, []);

	const handleBulkDelete = useCallback((cases: LegalCase[]) => {
		setBulkDeleteModalState({ isOpen: true, cases });
	}, []);

	const handleConfirmBulkDelete = async () => {
		try {
			setBulkDeleteModalState({ isOpen: false, cases: [] });
			setSelectedRows([]);
			refetch();
		} catch (error) {
			console.error("Error bulk deleting cases:", error);
		}
	};

	const handleCancelBulkDelete = () => {
		setBulkDeleteModalState({ isOpen: false, cases: [] });
	};

	const renderFloatingBar = useCallback(
		(selectedCount: number, selectedCases: LegalCase[]) => (
			<LegalCasesFloatingActionBar
				selectedCount={selectedCount}
				selectedRows={selectedCases}
				onDelete={handleBulkDelete}
				onEdit={(caseItem) => handleEditClick(caseItem)}
			/>
		),
		[handleBulkDelete, handleEditClick]
	);

	if (!canAccessCases) {
		return (
			<div className="p-6">
				<NoPermissionMessage
					message={t("permissions.noAccess.title", "Access Restricted")}
					description={t("permissions.noAccess.message", "You don't have permission to access the legal cases module.")}
				/>
			</div>
		);
	}

	return (
		<>
			{isLoadingDetails && <LoadingOverlay isLoading={true} message="Loading case details..." />}
                <LegalCasesToolbar
                    searchQuery={searchQuery}
                    onSearchChange={setSearchQuery}
                    onSortChange={handleSortChange}

                    onAddCaseClick={handleAddCaseClick}
                    onFiltersApply={handleFiltersApply}
                />
            {!canViewCases ? (
                <NoPermissionMessage 
                    message={t("permissions.noReadAccess.title", "Access Restricted")}
                    description={`${t("permissions.noReadAccess.message", "You don't have permission to view legal cases.")} (Missing: ${formatPermissionName("read_legal_case")})`}
                    className="mt-12"
                />
            ) : (
                <>
                {/* Table Logic */}
                { isError ? (
					// Check for 403 Forbidden
					(error as any)?.response?.status === 403 ? (
						<NoPermissionMessage 
							message={t("permissions.noReadAccess.title", "Access Restricted")}
							description={`${t("permissions.noReadAccess.message", "You don't have permission to view legal cases.")} (Missing: ${formatPermissionName("read_legal_case")})`}
							className="mt-12"
						/>
					) : (
						<div className='text-error text-sm mb-4'>
							{t("common:error") || "Failed to load legal cases."}
						</div>
					)
				) : isLoading ? (
					<LoadingState
						size='large'
						label={t("legalCases.loading", "Loading legal cases...")}
					/>
				) : (
					<LegalCasesTable
						data={data?.data || []}
						onViewDetails={handleViewDetails}
						onEdit={handleEditClick}
						onDelete={handleDeleteClick}
						onRowSelectionChange={handleRowSelectionChange}
						renderFloatingBar={renderFloatingBar}
					/>
				)}
                </>
            )}

			<LegalCasesFloatingActionBar
				selectedCount={selectedRows.length}
				selectedRows={selectedRows}
				onDelete={handleBulkDelete}
				onEdit={(caseItem) => handleEditClick(caseItem)}
			/>

			{/* Delete Confirmation Modal */}
			<ConfirmModal
				isOpen={isDeleteModalOpen}
				onClose={() => {
					if (!deleteCaseMutation.isPending) {
						setIsDeleteModalOpen(false);
					}
				}}
				onConfirm={handleConfirmDelete}
				title={t("legalCases.confirmDelete.title")}
				description={t("legalCases.confirmDelete.description", {
					caseNumber: selectedCase?.case_number,
				})}
				confirmText={t("legalCases.confirmDelete.confirmButton")}
				cancelText={t("legalCases.confirmDelete.cancelButton")}
				variant='error'
				icon='exclamation'
				isLoading={deleteCaseMutation.isPending}
			/>

			{/* Bulk Delete Confirmation Modal */}
			<ConfirmModal
				isOpen={bulkDeleteModalState.isOpen}
				onClose={handleCancelBulkDelete}
				onConfirm={handleConfirmBulkDelete}
				title={t("legalCases.confirmBulkDelete.title")}
				description={t("legalCases.confirmBulkDelete.description", {
					count: bulkDeleteModalState.cases.length,
				})}
				confirmText={t("legalCases.confirmBulkDelete.confirmButton")}
				cancelText={t("legalCases.confirmBulkDelete.cancelButton")}
				variant='error'
				icon='exclamation'
			/>

			{/* Add Case Modal */}
			<Modal
				isOpen={isAddCaseModalOpen}
				onClose={handleCloseAddCaseModal}
				title={
					editingCase
						? t("legalCases.addCaseModal.editTitle")
						: t("legalCases.addCaseModal.title")
				}
				size='large'>
				<AddCaseWizard
					onSubmit={handleSubmitCase}
					onCancel={handleCloseAddCaseModal}
					onFormDataChange={setCaseDraft}
					initialData={initialCaseData}
				/>
			</Modal>
			<ConfirmModal
				isOpen={showDiscardConfirm}
				onClose={() => setShowDiscardConfirm(false)}
				onConfirm={() => {
					setShowDiscardConfirm(false);
					setIsAddCaseModalOpen(false);
					setEditingCaseId(null);
					setCaseDraft(null);
				}}
				title={tCommon("unsavedChanges.title")}
				description={tCommon("unsavedChanges.description")}
				confirmText={tCommon("unsavedChanges.confirm")}
				cancelText={tCommon("unsavedChanges.cancel")}
			/>
		</>
	);
}

