import { SummaryCardData } from "../types";
import {
   CalendarXmarkCircle,
   AlarmDollar,
   AlarmXmarkCircle,
   Inbox,
   WalletClock,
} from "@/Icons";
import ContractStatusValue from "../ContractStatusValue";
import type {
   AttendanceTimelineResponse,
   TimeOffSummaryResponse,
   OvertimeSummaryResponse,
   EmployeeContract,
} from "@/services/employeeService";
import type { ContractResponse } from "@/services/contractService";

type TranslationFunction = (
   key: string,
   options?: Record<string, unknown>
) => string;

export const getSummaryCards = (
   t: TranslationFunction,
   onExtendDuration?: () => void
): SummaryCardData[] => [
   {
      id: "absence",
      title: t("profile.summary.absenceDays"),
      value: "12/30",
      icon: <CalendarXmarkCircle className="fill-error" />,
      badge: {
         label: t("profile.summary.badges.medium"),
         tone: "warning",
         level: "medium",
      },
   },
   {
      id: "overtime",
      title: t("profile.summary.overtime"),
      value: "26.5 Hours",
      icon: <AlarmDollar className="fill-success-dark" />,
   },
   {
      id: "late",
      title: t("profile.summary.lateArrivals"),
      value: "7 Times",
      icon: <AlarmXmarkCircle className="fill-warning" />,
   },
   {
      id: "requests",
      title: t("profile.summary.pendingRequests"),
      value: "3 Requests",
      icon: <Inbox className="fill-warning" />,
   },
   {
      id: "contract",
      title: t("profile.summary.contractStatus"),
      value: (
         <ContractStatusValue
            status="Active"
            onExtendDuration={onExtendDuration}
         />
      ),
      icon: <WalletClock className="fill-highlighted" />,
   },
];

// Dynamic summary cards based on API data
export const getDynamicSummaryCards = (
   t: TranslationFunction,
   data: {
      attendanceTimeline?: AttendanceTimelineResponse;
      timeOffSummary?: TimeOffSummaryResponse;
      overtimeSummary?: OvertimeSummaryResponse;
      contract?: EmployeeContract;
      contractsList?: ContractResponse[];
   },
   options?: {
      onExtendDuration?: () => void;
      canExtendContract?: boolean;
   }
): SummaryCardData[] => {
   const { attendanceTimeline, timeOffSummary, overtimeSummary, contract, contractsList } =
      data;
   const { onExtendDuration, canExtendContract } = options || {};
   const hasContract = Boolean(contract);

   // Calculate absence days from time off balances
   const totalAllocated =
      timeOffSummary?.balances.reduce(
         (sum, balance) => sum + parseFloat(balance.allocated),
         0
      ) || 0;
   const totalUsed =
      timeOffSummary?.balances.reduce(
         (sum, balance) => sum + balance.used,
         0
      ) || 0;

   // Calculate late arrivals from attendance timeline (based on clock_in time)
   // For now, we'll count days where clock_in is after expected time
   // This is a placeholder since the API doesn't have a "late" status
   const lateArrivals =
      attendanceTimeline?.data.filter((day) => {
         // Check if day has actual clock_in and clock_out (not day off)
         return day.clock_in && day.clock_out && day.duration_hours < 8;
      }).length || 0;

   // Get pending requests count
   const pendingTimeOffRequests =
      timeOffSummary?.requests.filter(
         (req) => req.status.toLowerCase() === "pending"
      ).length || 0;

   const pendingOvertimeRequests = overtimeSummary?.pending_requests || 0;
   const totalPendingRequests =
      pendingTimeOffRequests + pendingOvertimeRequests;

   // Determine absence badge level
   const absencePercentage =
      totalAllocated > 0 ? (totalUsed / totalAllocated) * 100 : 0;
   let absenceBadge: SummaryCardData["badge"];

   if (hasContract) {
      if (absencePercentage > 70) {
         absenceBadge = {
            label: t("profile.summary.badges.high"),
            tone: "warning", // Using warning instead of danger since that's the allowed type
            level: "high",
         };
      } else if (absencePercentage > 40) {
         absenceBadge = {
            label: t("profile.summary.badges.medium"),
            tone: "warning",
            level: "medium",
         };
      } else if (absencePercentage > 0) {
         absenceBadge = {
            label: t("profile.summary.badges.low"),
            tone: "success",
            level: "low",
         };
      }
   }

   const absenceValue = hasContract
      ? `${totalUsed}/${Math.round(totalAllocated)}`
      : t("profile.summary.noContractYet");

   // Find matching contract in the list for termination check (same approach as ContractsTable)
   const getContractStatus = (contract: EmployeeContract) => {
      // Find the matching contract in the list
      const matchingContract = contractsList?.find(
         (c) => c.id === contract.contract_id
      );

      // Check for termination - same logic as ContractsContent.tsx
      if (
         contract.duration.status === "Terminated" ||
         matchingContract?.status?.toLowerCase() === "terminated" ||
         matchingContract?.status?.toLowerCase() === "ended" ||
         matchingContract?.custom_fields?.termination
      ) {
         return "Terminated";
      }

      return contract.duration.status;
   };

   const contractStatus = contract ? getContractStatus(contract) : "Active";
   const canTriggerExtend =
      Boolean(canExtendContract && onExtendDuration && contractStatus !== "Terminated");

   const contractSummaryValue = contract ? (
      <ContractStatusValue
         status={contractStatus as any}
         daysRemaining={contract.duration.days_remaining}
         onExtendDuration={canTriggerExtend ? onExtendDuration : undefined}
      />
   ) : (
      <p className="text-xs text-text-sub">
         {t("profile.contract.noContractFound")}
      </p>
   );

   return [
      {
         id: "absence",
         title: t("profile.summary.absenceDays"),
         value: absenceValue,
         icon: <CalendarXmarkCircle className="fill-error" />,
         badge: absenceBadge,
      },
   {
      id: "overtime",
      title: t("profile.summary.overtime"),
      value: t("profile.summary.overtimeValue", {
         hours: overtimeSummary?.total_hours_this_month || 0,
      }),
      icon: <AlarmDollar className="fill-success-dark" />,
   },
   {
      id: "late",
      title: t("profile.summary.lateArrivals"),
      value: t("profile.summary.lateArrivalsValue", { count: lateArrivals }),
      icon: <AlarmXmarkCircle className="fill-warning" />,
   },
      {
         id: "requests",
         title: t("profile.summary.pendingRequests"),
      value: t("profile.summary.pendingRequestsValue", {
         count: totalPendingRequests,
      }),
      icon: <Inbox className="fill-warning" />,
   },
   {
      id: "contract",
      title: t("profile.summary.contractStatus"),
         value: contractSummaryValue,
         icon: <WalletClock className="fill-highlighted" />,
      },
   ];
};

/** @format */

import { useState } from "react";
import Modal from "@/designSystem/Modal";
import Button from "@/designSystem/Button";
import GenericForm from "@/designSystem/GenericForm";
import ConfirmModal from "@/designSystem/ConfirmModal";
import { useTranslation } from "@/hooks/useTranslation";
import { useUploadEmployeeDocument } from "@/hooks/employees/employee.mutations";
import toast from "@/utilities/toast";
import * as Yup from "yup";

interface UploadDocumentModalProps {
   isOpen: boolean;
   onClose: () => void;
   employeeId: string;
}

interface DocumentFormData {
   documents: Array<{
      fileName: string;
      fileSize: number;
      fileType: string;
      fileUrl?: string;
      fileId?: number;
      token?: string;
      key?: string;
      purpose?: string;
      progress: number;
      isUploading: boolean;
      error?: string;
   }>;
}

const documentSchema = Yup.object().shape({
   documents: Yup.array().min(1, "Please upload at least one document"),
});

function UploadDocumentModal({
   isOpen,
   onClose,
   employeeId,
}: UploadDocumentModalProps) {
   const { t } = useTranslation("members");
   const { t: tCommon } = useTranslation("common");
   const [formData, setFormData] = useState<DocumentFormData>({
      documents: [],
   });
   const [isDirty, setIsDirty] = useState(false);
   const [showDiscardConfirm, setShowDiscardConfirm] = useState(false);
   const uploadDocumentMutation = useUploadEmployeeDocument();

   const isBusy = uploadDocumentMutation.isPending;

   // Check if any files are still uploading
   const hasUploadingFiles = formData.documents.some((doc) => doc.isUploading);

   const handleClose = () => {
      if (isBusy) return;
      if (isDirty) {
         setShowDiscardConfirm(true);
         return;
      }
      setFormData({ documents: [] });
      onClose();
   };

   const handleFieldChange = (field: string, value: unknown) => {
      setFormData((prev) => ({
         ...prev,
         [field]: value,
      }));
   };

   const handleSubmit = async (data: any) => {
      try {
         // Get uploaded documents (filter out uploading/failed ones)
         const uploadedDocs = (data.documents || []).filter(
            (doc: any) => doc.fileId && doc.token && !doc.isUploading && !doc.error
         );

         if (uploadedDocs.length === 0) {
            toast.error("Please wait for uploads to complete");
            return;
         }

         // Get current date in ISO format (YYYY-MM-DD)
         const currentDate = new Date().toISOString().split('T')[0];

         // Upload each document to the backend
         for (const doc of uploadedDocs) {
            await uploadDocumentMutation.mutateAsync({
               id: employeeId,
               payload: {
                  file_id: doc.fileId!,
                  document_type: "other", // Default type
                  issue_date: currentDate, // Automatically set to current date
               },
            });
         }

         toast.success(
            uploadedDocs.length === 1
               ? t("documents.uploadSuccess", { name: uploadedDocs[0].fileName })
               : `${uploadedDocs.length} documents uploaded successfully`
         );
         setFormData({ documents: [] });
         setIsDirty(false);
         onClose();
      } catch (err) {
         console.error("Failed to upload documents", err);
         toast.error("Failed to upload documents");
      }
   };


   const fields = [
      {
         name: "documents",
         type: "uploadField" as const,
         label: "Attach Documents",
         accept: "image/jpeg,image/png,application/pdf",
         multiple: true,
         uploadPurpose: "employee_document",
      },
   ];

   return (
      <Modal
         isOpen={isOpen}
         onClose={handleClose}
         title="Upload Documents"
         width="w-[600px]"
         contentClassName="flex flex-col items-start p-5 gap-5 w-full bg-background"
         showHeaderDivider={false}
         footer={
            <div className="flex flex-row justify-end items-center gap-3 flex-1">
               <Button
                  variant="secondary"
                  onClick={handleClose}
                  disabled={isBusy}
                  className="px-4 py-2 rounded-xl">
                  Cancel
               </Button>
               <Button
                  type="submit"
                  form="upload-document-form"
                  disabled={isBusy || hasUploadingFiles || formData.documents.length === 0}
                  className="px-4 py-2 rounded-xl">
                  {isBusy ? "Uploading..." : "Upload Documents"}
               </Button>
            </div>
         }>
         <div className="w-full">
            <GenericForm
               id="upload-document-form"
               schema={documentSchema}
               defaultValues={formData}
               formData={formData}
               onSubmit={handleSubmit}
               onFieldChange={handleFieldChange}
               showSubmitButton={false}
               mode="onChange"
               fields={fields}
               onDirtyChange={setIsDirty}
            />
         </div>
         <ConfirmModal
            isOpen={showDiscardConfirm}
            onClose={() => setShowDiscardConfirm(false)}
            onConfirm={() => {
               setFormData({ documents: [] });
               onClose();
            }}
            title={tCommon("unsavedChanges.title")}
            description={tCommon("unsavedChanges.description")}
            confirmText={tCommon("unsavedChanges.confirm")}
            cancelText={tCommon("unsavedChanges.cancel")}
            variant="primary"
            icon="exclamation"
         />
      </Modal>
   );
}

export default UploadDocumentModal;

/** @format */

import { useState, useMemo, useRef, useEffect, useLayoutEffect, useCallback } from "react";
import { ColumnDef } from "@tanstack/react-table";
import { useTranslation } from "@/hooks/useTranslation";
import { DataTable } from "@/designSystem/ui/data-table";
import {
   Search2Line,
   SortDescending,
   AddLine,
   SackDollar,
   Tag,
   Calender,
   ChatText,
   MoreVertical,
   Briefcase,
   Edit,
   Trash,
   AlertFill,
   ArrowDownSLine,
} from "@/Icons";
import Dropdown from "@/designSystem/Dropdown";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import {
   getEmployeePayrollStructure,
   PayrollItem,
   createPayrollItem,
   updatePayrollItem,
   deletePayrollItem,
   createPayroll,
} from "@/services/payrollService";
import LoadingState from "@/designSystem/LoadingState";
import DirhamLabel from "@/designSystem/DirhamLabel";
import PayrollItemModal from "./PayrollItemModal";
import ConfirmModal from "@/designSystem/ConfirmModal";
import toast from "@/utilities/toast";
import { format } from "date-fns";
import { useLocalTableData } from "@/hooks/table/useLocalTableData";
import { usePermissions } from "@/contexts/PermissionContext";

interface PayrollsTabProps {
   employeeId: string;
}

export default function PayrollsTab({ employeeId }: PayrollsTabProps) {
   const { t } = useTranslation("members");
   const queryClient = useQueryClient();
   const currentDate = new Date();
   const currentMonthIndex = currentDate.getMonth();
   const currentYearValue = currentDate.getFullYear();
   const [searchQuery, setSearchQuery] = useState("");
   const [selectedYear, setSelectedYear] = useState<number>(currentYearValue);
   const [selectedMonth, setSelectedMonth] = useState<number | null>(currentMonthIndex);
   const [isMonthDropdownOpen, setIsMonthDropdownOpen] = useState(false);
   const monthButtonRef = useRef<HTMLButtonElement>(null);
   const months = [
      "January", "February", "March", "April", "May", "June",
      "July", "August", "September", "October", "November", "December"
   ];
   const selectedPeriodLabel =
      selectedMonth !== null
         ? `${months[selectedMonth]} ${selectedYear}`
         : `${months[currentMonthIndex]} ${selectedYear}`;

   // Permission checks
   const { can } = usePermissions();
   const canViewPayroll = can("payroll.view");
   const canCreatePayroll = can("payroll.create");
   const canEditPayroll = can("payroll.edit");
   const canDeletePayroll = can("payroll.delete");

   // Modal States
   const [isModalOpen, setIsModalOpen] = useState(false);
   const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
   const [selectedItem, setSelectedItem] = useState<PayrollItem | null>(null);

   // Build query parameters for API
   const queryParams = useMemo(() => {
      const params: Record<string, string> = {};

      // Use current month/year if selectedMonth is null
      const monthToUse = selectedMonth !== null ? selectedMonth : currentMonthIndex;
      const yearToUse = selectedYear;

      // Check if selected date is in the future
      const selectedDate = new Date(yearToUse, monthToUse, 1);
      const currentDateObj = new Date(currentYearValue, currentMonthIndex, 1);
      const isFutureDate = selectedDate > currentDateObj;

      if (isFutureDate) {
         // If future date, use current date for both fromDate and toDate
         const currentDateStr = format(new Date(), "yyyy-MM-dd");
         params.fromDate = currentDateStr;
         params.toDate = currentDateStr;
      } else {
         // Backend expects fromDate and toDate in YYYY-MM-DD
         const year = yearToUse;
         const month = String(monthToUse + 1).padStart(2, "0"); // Month is 0-indexed
         const firstDay = "01";

         // Get the last day of the selected month
         const lastDayOfMonth = new Date(yearToUse, monthToUse + 1, 0);
         const currentDate = new Date();

         // Check if the end of the month is in the future
         const isEndOfMonthInFuture = lastDayOfMonth > currentDate;

         params.fromDate = `${year}-${month}-${firstDay}`;

         if (isEndOfMonthInFuture) {
            // If end of month is in future, use current date for toDate
            params.toDate = format(currentDate, "yyyy-MM-dd");
         } else {
            // Use the last day of the month
            const lastDay = String(lastDayOfMonth.getDate()).padStart(2, "0");
            params.toDate = `${year}-${month}-${lastDay}`;
         }
      }
      return params;
   }, [selectedMonth, selectedYear, currentMonthIndex, currentYearValue]);

   const { data, isLoading } = useQuery({
      queryKey: ["employee-payroll-structure", employeeId, queryParams],
      queryFn: () => getEmployeePayrollStructure(employeeId, queryParams),
      enabled: !!employeeId && canViewPayroll,
   });

   const payrollItems = data?.items || [];
   const payrollData = data?.payroll || null;
   const [payrollId, setPayrollId] = useState<string | null>(null);

   useEffect(() => {
      if (data?.payrollId) {
         setPayrollId(String(data.payrollId));
      }
   }, [data?.payrollId]);

   // Mutations
   const createMutation = useMutation({
      mutationFn: (newItem: Partial<PayrollItem>) => {
         if (!canCreatePayroll) {
            throw new Error("You don't have permission to create payroll items");
         }
         if (!payrollId) throw new Error("No active payroll found");
         return createPayrollItem(String(payrollId), newItem);
      },
      onSuccess: () => {
         queryClient.invalidateQueries({
            queryKey: ["employee-payroll-structure", employeeId],
         });
         toast.success(t("payroll.messages.addSuccess"));
         setIsModalOpen(false);
      },
      onError: (error) => {
         console.error(error);
         toast.error(t("error"));
      },
   });

   const createPayrollMutation = useMutation({
      mutationFn: async () => {
         const now = new Date();
         const periodStart = format(
            new Date(now.getFullYear(), now.getMonth(), 1),
            "yyyy-MM-dd"
         );

         // Get the last day of the current month
         const lastDayOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);

         // Check if the end of the month is in the future
         const isEndOfMonthInFuture = lastDayOfMonth > now;

         // If end of month is in future, use current date for periodEnd
         const periodEnd = isEndOfMonthInFuture
            ? format(now, "yyyy-MM-dd")
            : format(lastDayOfMonth, "yyyy-MM-dd");

         return createPayroll(employeeId, {
            periodStart,
            periodEnd,
            cycleType: "Monthly",
            notes: `Auto-generated payroll for ${format(now, "MMMM yyyy")}`,
         });
      },
      onSuccess: (response) => {
         const createdPayroll = response?.data || response;
         const newId =
            createdPayroll?.payroll_id ??
            createdPayroll?.id ??
            createdPayroll?.payrollId;
         if (newId) setPayrollId(String(newId));
         queryClient.invalidateQueries({
            queryKey: ["employee-payroll-structure", employeeId],
         });
         setIsModalOpen(true);
      },
      onError: (error) => {
         console.error(error);
         toast.error(t("error"));
      },
   });

   const updateMutation = useMutation({
      mutationFn: (updatedItem: Partial<PayrollItem>) => {
         if (!canEditPayroll) {
            throw new Error("You don't have permission to edit payroll items");
         }
         if (!payrollId || !selectedItem)
            throw new Error("No item selected or payroll found");
         return updatePayrollItem(
            String(payrollId),
            selectedItem.id,
            updatedItem
         );
      },
      onSuccess: () => {
         queryClient.invalidateQueries({
            queryKey: ["employee-payroll-structure", employeeId],
         });
         toast.success(t("payroll.messages.updateSuccess"));
         setIsModalOpen(false);
         setSelectedItem(null);
      },
      onError: (error) => {
         console.error(error);
         toast.error(t("error"));
      },
   });

   const deleteMutation = useMutation({
      mutationFn: () => {
         if (!canDeletePayroll) {
            throw new Error("You don't have permission to delete payroll items");
         }
         if (!payrollId || !selectedItem)
            throw new Error("No item selected or payroll found");
         return deletePayrollItem(String(payrollId), selectedItem.id);
      },
      onSuccess: () => {
         queryClient.invalidateQueries({
            queryKey: ["employee-payroll-structure", employeeId],
         });
         toast.success(t("payroll.messages.deleteSuccess"));
         setIsDeleteModalOpen(false);
         setSelectedItem(null);
      },
      onError: (error) => {
         console.error(error);
         toast.error(t("error"));
      },
   });

   // Handlers
   const handleAdd = () => {
      if (!canCreatePayroll) {
         toast.error("You don't have permission to create payroll items");
         return;
      }
      setSelectedItem(null);
      if (payrollId) {
         setIsModalOpen(true);
      } else {
         createPayrollMutation.mutate();
      }
   };

   const handleEdit = useCallback((item: PayrollItem) => {
      if (!canEditPayroll) {
         toast.error("You don't have permission to edit payroll items");
         return;
      }
      setSelectedItem(item);
      setIsModalOpen(true);
   }, [canEditPayroll]);

   const handleDelete = useCallback((item: PayrollItem) => {
      if (!canDeletePayroll) {
         toast.error("You don't have permission to delete payroll items");
         return;
      }
      setSelectedItem(item);
      setIsDeleteModalOpen(true);
   }, [canDeletePayroll]);

   const handleSave = (formData: Partial<PayrollItem>) => {
      if (selectedItem) {
         updateMutation.mutate(formData);
      } else {
         createMutation.mutate(formData);
      }
   };

   const columns = useMemo<ColumnDef<PayrollItem>[]>(
      () => [
         {
            accessorKey: "itemName",
            header: () => (
               <div className="flex items-center gap-2">
                  <Briefcase className="size-4 text-text-sub" />
                  <span>{t("payroll.table.payrollItem")}</span>
               </div>
            ),
            cell: ({ row }) => (
               <span className="text-sm font-medium text-text-strong">
                  {row.original.itemName}
               </span>
            ),
         },
         {
            accessorKey: "componentType",
            header: () => (
               <div className="flex items-center gap-2">
                  <Tag className="size-4 text-text-sub" />
                  <span>{t("payroll.table.type")}</span>
               </div>
            ),
            cell: ({ row }) => (
               <span className="text-sm text-text-sub">
                  {t(`payroll.types.${row.original.componentType}`, {
                     defaultValue: row.original.componentType,
                  })}
               </span>
            ),
         },
         {
            accessorKey: "amount",
            header: () => (
               <div className="flex items-center gap-2">
                  <SackDollar className="size-4 text-text-sub" />
                  <span>{t("payroll.table.amount")}</span>
               </div>
            ),
            cell: ({ row }) => <DirhamLabel value={row.original.amount} />,
         },
         {
            accessorKey: "effectiveDate",
            header: () => (
               <div className="flex items-center gap-2">
                  <Calender className="size-4 text-text-sub" />
                  <span>{t("payroll.table.effectiveDate")}</span>
               </div>
            ),
            cell: ({ row }) => {
               const date = new Date(row.original.effectiveDate);
               return (
                  <span className="text-sm text-text-sub">
                     {date.toLocaleDateString("en-GB", {
                        day: "2-digit",
                        month: "short",
                        year: "numeric",
                     })}
                  </span>
               );
            },
         },
         {
            accessorKey: "notes",
            header: () => (
               <div className="flex items-center gap-2">
                  <ChatText className="size-4 text-text-sub" />
                  <span>{t("payroll.table.notes")}</span>
               </div>
            ),
            cell: ({ row }) => (
               <span className="text-sm text-text-sub truncate max-w-[200px] block">
                  {row.original.notes || "-"}
               </span>
            ),
         },
         {
            id: "actions",
            header: () => (
               <div className="flex justify-end pr-2 text-text-soft">
                  <MoreVertical className="size-4" />
               </div>
            ),
            cell: ({ row }) => (
               <div className="flex justify-end pr-2">
                  <ActionCell
                     item={row.original}
                     onEdit={() => handleEdit(row.original)}
                     onDelete={() => handleDelete(row.original)}
                  />
               </div>
            ),
            size: 80,
         },
      ],
      [t, handleEdit, handleDelete]
   );

   const [sortBy, setSortBy] = useState<string>("effectiveDate_desc");

   // Use local table data hook for client-side search and sorting only
   const { data: filteredData } = useLocalTableData({
      data: payrollItems,
      searchQuery,
      searchFields: ["itemName", "componentType", "notes"],
      sortField: sortBy.split("_")[0],
      sortDirection: (sortBy.split("_")[1] as "asc" | "desc") || "desc",
   });

   if (isLoading) {
      return <LoadingState label={t("loading.profile")} />;
   }

   // Show permission denied message if user cannot view payroll
   if (!canViewPayroll) {
      return (
         <div className="flex items-center justify-center py-12">
            <p className="text-text-sub">
               {t("payroll.messages.noPermission") || "You don't have permission to view payroll information"}
            </p>
         </div>
      );
   }

   // Show empty state when no payroll exists for selected period
   if (!data || !payrollData) {
      const selectedPeriod = selectedMonth !== null 
         ? `${months[selectedMonth]} ${selectedYear}`
         : selectedPeriodLabel;

      return (
         <div className="w-full flex flex-col gap-6">
            {/* Toolbar - keep it visible */}
            <div className="flex items-center justify-between gap-4">
               {/* Search */}
               <div className="flex-1 max-w-md bg-background border border-border rounded-lg flex items-center px-2.5 py-2 gap-2">
                  <Search2Line className="size-5 fill-text-sub" />
                  <input
                     type="text"
                     placeholder={t("payroll.searchPlaceholder")}
                     value={searchQuery}
                     onChange={(e) => setSearchQuery(e.target.value)}
                     className="flex-1 bg-transparent outline-none text-sm text-text-strong placeholder:text-text-soft min-w-0"
                  />
               </div>

               {/* Actions */}
               <div className="flex items-center gap-2">
                  {/* Month/Year Filter */}
                  <button
                     ref={monthButtonRef}
                     onClick={() => setIsMonthDropdownOpen(!isMonthDropdownOpen)}
                     className="flex items-center gap-2 px-2.5 py-2 text-sm font-medium text-text-sub border border-border rounded-lg bg-background hover:bg-bg-weak transition-colors">
                     <span>
                        {selectedPeriodLabel}
                     </span>
                  </button>
                  {isMonthDropdownOpen && (
                     <MonthYearPicker
                        selectedYear={selectedYear}
                        selectedMonth={selectedMonth}
                        onYearChange={setSelectedYear}
                        onMonthChange={setSelectedMonth}
                        onClose={() => setIsMonthDropdownOpen(false)}
                        anchorRef={monthButtonRef}
                     />
                  )}
               </div>
            </div>

            {/* Empty State */}
            <div className="flex flex-col items-center justify-center py-16 px-4 bg-background border border-border rounded-2xl">
               <div className="text-center max-w-md">
                  <div className="mb-4">
                     <SackDollar className="size-16 fill-text-soft mx-auto" />
                  </div>
                  <h3 className="text-lg font-semibold text-text-strong mb-2">
                     No Payroll Found
                  </h3>
                  <p className="text-sm text-text-sub mb-4">
                     There is no payroll data for {selectedPeriod}. Try selecting a different month or create a new payroll.
                  </p>
               </div>
            </div>
         </div>
      );
   }

   return (
      <div className="w-full flex flex-col gap-6">
         {/* Toolbar */}
         <div className="flex items-center justify-between gap-4">
            {/* Search */}
            <div className="flex-1 max-w-md bg-background border border-border rounded-lg flex items-center px-2.5 py-2 gap-2">
               <Search2Line className="size-5 fill-text-sub" />
               <input
                  type="text"
                  placeholder={t("payroll.searchPlaceholder")}
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="flex-1 bg-transparent outline-none text-sm text-text-strong placeholder:text-text-soft min-w-0"
               />
            </div>

            {/* Actions */}
            <div className="flex items-center gap-2">
               {/* Month/Year Filter */}
               <button
                  ref={monthButtonRef}
                  onClick={() => setIsMonthDropdownOpen(!isMonthDropdownOpen)}
                  className="flex items-center gap-2 px-2.5 py-2 text-sm font-medium text-text-sub border border-border rounded-lg bg-background hover:bg-bg-weak transition-colors">
                  <span>
                     {selectedPeriodLabel}
                  </span>
               </button>
               {isMonthDropdownOpen && (
                  <MonthYearPicker
                     selectedYear={selectedYear}
                     selectedMonth={selectedMonth}
                     onYearChange={setSelectedYear}
                     onMonthChange={setSelectedMonth}
                     onClose={() => setIsMonthDropdownOpen(false)}
                     anchorRef={monthButtonRef}
                  />
               )}

               <Dropdown
                  trigger={
                     <button className="flex items-center gap-2 px-2.5 py-2 text-sm font-medium text-text-sub border border-border rounded-lg bg-background hover:bg-bg-weak transition-colors">
                        <span className="flex items-center gap-2">
                           <SortDescending className="size-5 fill-text-sub" />{" "}
                           {t("filters.sortBy")}
                        </span>
                     </button>
                  }
                  items={[
                     {
                        id: "effectiveDate_desc",
                        label: t("payroll.sort.newest"),
                        icon: SortDescending,
                        onClick: () => setSortBy("effectiveDate_desc"),
                     },
                     {
                        id: "effectiveDate_asc",
                        label: t("payroll.sort.oldest"),
                        icon: SortDescending,
                        onClick: () => setSortBy("effectiveDate_asc"),
                     },
                     {
                        id: "amount_desc",
                        label: t("payroll.sort.amountHighToLow"),
                        icon: SackDollar,
                        onClick: () => setSortBy("amount_desc"),
                     },
                     {
                        id: "amount_asc",
                        label: t("payroll.sort.amountLowToHigh"),
                        icon: SackDollar,
                        onClick: () => setSortBy("amount_asc"),
                     },
                  ]}
               />

               {canCreatePayroll && (
                  <button
                     onClick={handleAdd}
                     disabled={isLoading || createPayrollMutation.isPending}
                     className="flex items-center gap-2 px-3 py-2 bg-text-strong text-text-main rounded-lg hover:bg-text-strong/90 transition-colors text-sm font-medium cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed">
                     <AddLine className="size-5 fill-current" />
                     <span>{t("payroll.addPayItem")}</span>
                  </button>
               )}
            </div>
         </div>

         {/* Payroll Summary Card */}
         {data && payrollData && (
            <PayrollSummaryCard
               payroll={payrollData}
            />
         )}

         {/* Table */}
         <div className="border border-border rounded-xl overflow-hidden">
            <DataTable
               columns={columns}
               data={filteredData as PayrollItem[]}
               showPagination
               pageSize={10}
            />
         </div>

         {/* Add/Edit Modal */}
         <PayrollItemModal
            isOpen={isModalOpen}
            onClose={() => setIsModalOpen(false)}
            onSubmit={handleSave}
            initialData={selectedItem || undefined}
            isLoading={createMutation.isPending || updateMutation.isPending}
         />

         {/* Delete Confirmation Modal */}
         <ConfirmModal
            isOpen={isDeleteModalOpen}
            onClose={() => setIsDeleteModalOpen(false)}
            onConfirm={() => deleteMutation.mutate()}
            title={t("payroll.messages.deleteConfirmTitle")}
            description={t("payroll.messages.deleteConfirmDescription")}
            confirmText={t("payroll.messages.confirmDelete")}
            variant="error"
            isLoading={deleteMutation.isPending}
         />
      </div>
   );
}

function ActionCell({
   item,
   onEdit,
   onDelete,
}: {
   item: PayrollItem;
   onEdit: () => void;
   onDelete: () => void;
}) {
   const { t } = useTranslation("members");
   const { can } = usePermissions();
   const [isOpen, setIsOpen] = useState(false);
   const buttonRef = useRef<HTMLButtonElement>(null);
   const canEditPayroll = can("payroll.edit");
   const canDeletePayroll = can("payroll.delete");

   const isManual =
      item.sourceType === "Manual" ||
      (item as any).source_type === "Manual" ||
      item.isManual === true ||
      (item as any).is_manual === true;

   const dropdownItems = [
      {
         id: "edit",
         label: t("payroll.actions.edit"),
         icon: Edit,
         onClick: onEdit,
         disabled: !isManual || !canEditPayroll,
         tooltip: !isManual
            ? {
                 label: t("payroll.tooltips.systemItem"),
              }
            : !canEditPayroll
            ? {
                 label: "No permission to edit",
              }
            : undefined,
      },
      {
         id: "delete",
         label: t("payroll.actions.delete"),
         icon: Trash,
         variant: "danger" as const,
         onClick: onDelete,
         disabled: !isManual || !canDeletePayroll,
         tooltip: !isManual
            ? {
                 label: t("payroll.tooltips.systemItem"),
              }
            : !canDeletePayroll
            ? {
                 label: "No permission to delete",
              }
            : undefined,
      },
   ];

   return (
      <>
         <button
            ref={buttonRef}
            onClick={() => setIsOpen(!isOpen)}
            data-row-menu-trigger
            className={`p-1 rounded-md transition-colors ${
               isOpen ? "bg-bg-weak" : "hover:bg-bg-weak"
            } ${isManual ? "cursor-pointer" : "cursor-not-allowed opacity-60"}`}>
            <MoreVertical className="" />
         </button>
         <Dropdown
            items={dropdownItems}
            isOpen={isOpen}
            onClose={() => setIsOpen(false)}
            anchorRef={buttonRef}
         />
      </>
   );
}

function PayrollSummaryCard({
   payroll,
}: {
   payroll: {
      base_salary: string;
      gross_total: string;
      deduction_total: string;
      net_pay: string;
      warnings?: Array<{ type: string; message: string }>;
      notes?: string;
   };
}) {
   const [isExpanded, setIsExpanded] = useState(false);

   const baseSalary = parseFloat(payroll.base_salary || "0");
   const totalEarnings = parseFloat(payroll.gross_total || "0");
   const totalDeductions = parseFloat(payroll.deduction_total || "0");
   const netPay = parseFloat(payroll.net_pay || "0");

   const hasWarnings = payroll.warnings && payroll.warnings.length > 0;
   const hasNotes = payroll.notes && payroll.notes.trim().length > 0;

   return (
      <div className="bg-background border border-border rounded-2xl overflow-hidden">
         {/* Clickable Header */}
