function MonthYearPicker({
   selectedYear,
   selectedMonth,
   onYearChange,
   onMonthChange,
   onClose,
   anchorRef,
}: {
   selectedYear: number;
   selectedMonth: number | null;
   onYearChange: (year: number) => void;
   onMonthChange: (month: number | null) => void;
   onClose: () => void;
   anchorRef: React.RefObject<HTMLElement>;
}) {
   const dropdownRef = useRef<HTMLDivElement>(null);
   const yearButtonRef = useRef<HTMLButtonElement>(null);
   const [isYearDropdownOpen, setIsYearDropdownOpen] = useState(false);
   const [position, setPosition] = useState<{ top: number; right: number } | null>(null);

   const months = [
      "Jan", "Feb", "Mar", "Apr", "May", "Jun",
      "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"
   ];
   const years = [2026, 2025];
   const YearIcon = ({ size = 6, className = "" }: { size?: number; className?: string }) => (
      <span
         className={`inline-block rounded-full bg-border ${className}`}
         style={{ width: size, height: size }}
      />
   );

   useLayoutEffect(() => {
      if (anchorRef.current) {
         const rect = anchorRef.current.getBoundingClientRect();
         setPosition({
            top: rect.bottom + 4,
            right: window.innerWidth - rect.right,
         });
      }
   }, [anchorRef]);

   useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
         if (
            dropdownRef.current &&
            !dropdownRef.current.contains(event.target as Node) &&
            anchorRef.current &&
            !anchorRef.current.contains(event.target as Node)
         ) {
            onClose();
         }
      };

      document.addEventListener("mousedown", handleClickOutside);
      return () => document.removeEventListener("mousedown", handleClickOutside);
   }, [onClose, anchorRef]);

   if (!position) {
      return null;
   }

   return (
      <div
         ref={dropdownRef}
         className="fixed bg-background border border-border rounded-2xl p-3 shadow-lg z-50 w-[280px]"
         style={{ top: `${position.top}px`, right: `${position.right}px` }}>
         {/* Year Selector */}
         <div className="flex items-center justify-between mb-3 pb-2 border-b border-border">
            <button
               ref={yearButtonRef}
               onClick={() => setIsYearDropdownOpen((prev) => !prev)}
               className="flex items-center gap-2 px-2.5 py-2 text-sm font-medium text-text-strong border border-border rounded-lg bg-background hover:bg-bg-weak transition-colors">
               <span>{selectedYear}</span>
               <ArrowDownSLine
                  className={`transition-transform ${isYearDropdownOpen ? "rotate-180" : ""}`}
                  size={16}
               />
            </button>
            <Dropdown
               isOpen={isYearDropdownOpen}
               onClose={() => setIsYearDropdownOpen(false)}
               anchorRef={yearButtonRef}
               items={years.map((year) => ({
                  id: String(year),
                  label: String(year),
                  icon: YearIcon,
                  onClick: () => {
                     onYearChange(year);
                     setIsYearDropdownOpen(false);
                  },
               }))}
               zIndex="z-[60]"
               variant="match-width"
            />
         </div>

         {/* Month Grid */}
         <div className="grid grid-cols-3 gap-1">
            {months.map((month, index) => (
               <button
                  key={month}
                  onClick={() => {
                     onMonthChange(index);
                     onClose();
                  }}
                  className={`px-2 py-1.5 rounded-lg text-sm transition-colors ${
                     selectedMonth === index
                        ? "bg-text-strong text-text-main"
                        : "hover:bg-bg-weak text-text-strong"
                  }`}>
                  {month}
               </button>
            ))}
         </div>
      </div>
   );
}

