import { useState, useMemo } from "react";
import { useTranslation } from "@/hooks/useTranslation";
import Modal from "@/designSystem/Modal";
import Button from "@/designSystem/Button";
import ConfirmModal from "@/designSystem/ConfirmModal";
import SearchableMultiSelect, {
	type DropdownItem,
} from "@/designSystem/SearchableMultiSelect";
import { useShifts } from "@/hooks/shifts/useShifts";
import { useListEmployees } from "@/hooks/employees/employee.queries";
import type { ViewShift } from "./types";
import type { Shift } from "@/services/shiftService";
import Loader from "@/designSystem/Loader";

type AssignEmployeesModalProps = {
	isOpen: boolean;
	onClose: () => void;
	shift: ViewShift;
	onSuccess?: () => void;
};

function AssignEmployeesModal({
	isOpen,
	onClose,
	shift,
	onSuccess,
}: AssignEmployeesModalProps) {
	const { t } = useTranslation("settings");
	const { t: tCommon } = useTranslation("common");
	const { useAssignEmployees, useListShifts } = useShifts();
	const assignMutation = useAssignEmployees();
	const { data: employeesData, isLoading: isLoadingEmployees } =
		useListEmployees();
	const { data: shiftsData } = useListShifts();
	const [selectedEmployees, setSelectedEmployees] = useState<
		Array<DropdownItem>
	>([]);
	const [isDirty, setIsDirty] = useState(false);
	const [showDiscardConfirm, setShowDiscardConfirm] = useState(false);

	// Get all assigned employee IDs across all shifts
	const assignedEmployeeIds = useMemo(() => {
		if (!shiftsData?.data) return new Set<number>();
		const ids = new Set<number>();
		(shiftsData.data as Shift[]).forEach((s) => {
			if (s.assignments) {
				s.assignments.forEach((a) => {
					if (a.assignment_type === 'Employee' && a.employee_id) {
						ids.add(a.employee_id);
					}
				});
			}
		});
		return ids;
	}, [shiftsData]);

	const employeeOptions = useMemo(() => {
		if (!employeesData?.data) return [];
		// Filter out employees who already have a shift assignment
		return employeesData.data
			.filter((emp: any) => !assignedEmployeeIds.has(emp.id))
			.map((emp: any) => ({
				id: emp.id,
				label: emp.name,
				subLabel: emp.email,
				avatar: emp.avatar || "/icons/defAvatar.png",
			}));
	}, [employeesData, assignedEmployeeIds]);

	const handleSubmit = async () => {
		if (selectedEmployees.length === 0) {
			return;
		}

		try {
			await assignMutation.mutateAsync({
				id: shift.id,
				data: { employeeIds: selectedEmployees.map((e) => Number(e.id)) },
			});
			if (onSuccess) onSuccess();
			setSelectedEmployees([]);
			setIsDirty(false);
			onClose();
		} catch (error) {
			console.error("Error assigning employees:", error);
		}
	};

	const handleSelectionChange = (items: Array<DropdownItem>) => {
		setSelectedEmployees(items);
		setIsDirty(items.length > 0);
	};

	const isLoading = assignMutation.isPending;

	const footer = (
		<div className="flex justify-end gap-3 w-full">
			<Button
				variant="secondary"
				onClick={() => {
					if (isDirty) {
						setShowDiscardConfirm(true);
						return;
					}
					onClose();
				}}
				disabled={isLoading}>
				{t("companySettings.shifts.modal.cancel")}
			</Button>
			<Button
				onClick={handleSubmit}
				disabled={isLoading || selectedEmployees.length === 0}>
				{isLoading && (
					<span className="animate-spin mr-2 w-4 h-4 border-2 border-white border-t-transparent rounded-full inline-block align-middle" />
				)}
				{t("companySettings.shifts.modal.assignButton")}
			</Button>
		</div>
	);

	return (
		<Modal
			isOpen={isOpen}
			onClose={() => {
				if (isDirty) {
					setShowDiscardConfirm(true);
					return;
				}
				onClose();
			}}
			title={t("companySettings.shifts.modal.assignTitle")}
			width="w-[30rem]"
			size="medium"
			overflow="visible"
			footer={footer}>
			<div className="flex flex-col gap-4">
				{/* Shift Name */}
				<div className="flex flex-col gap-1.5">
					<label className="text-sm font-medium text-text-strong">
						{t("companySettings.shifts.modal.shiftName")}
					</label>
					<div className="px-3 py-2.5 rounded-xl bg-bg-weak border border-border text-sm text-text-strong">
						{shift.name}
					</div>
				</div>

				{/* Employee Selection */}
				<div className="flex flex-col gap-1.5">
					<label className="text-sm font-medium text-text-strong">
						{t("companySettings.shifts.modal.selectEmployees")}
						<span className="text-danger ml-1">*</span>
					</label>
					{isLoadingEmployees ? (
						<Loader label={t("loading.employees")} />
					) : (
						<SearchableMultiSelect
							selectedItems={selectedEmployees}
							availableItems={employeeOptions}
							onChange={handleSelectionChange}
							placeholder={t(
								"companySettings.shifts.modal.selectEmployeesPlaceholder"
							)}
						/>
					)}
				</div>

				<p className="text-xs text-text-sub">
					{t("companySettings.shifts.modal.assignHelp")}
				</p>
			</div>

			<ConfirmModal
				isOpen={showDiscardConfirm}
				onClose={() => setShowDiscardConfirm(false)}
				onConfirm={() => {
					setShowDiscardConfirm(false);
					setSelectedEmployees([]);
					setIsDirty(false);
					onClose();
				}}
				title={tCommon("unsavedChanges.title")}
				description={tCommon("unsavedChanges.description")}
				confirmText={tCommon("unsavedChanges.confirm")}
				cancelText={tCommon("unsavedChanges.cancel")}
				variant="primary"
				icon="exclamation"
			/>
		</Modal>
	);
}

