const formatPermissionName = (name: string): string => {
   return name
      .split(/[._]/)
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
      .join(" ");
};

const formatScopeLabel = (scope: string): string | null => {
   // Handle exact matches first
   if (scope === "TEAM") return "My Team";
   if (scope === "MANAGED_BY") return "Managed By Me";
   if (scope === "ASSIGNED") return "Assigned To Me";

   // Handle patterns with <id>
   if (scope === "TEAM:<id>") return "Specific Team";
   if (scope === "MANAGED_BY:<id>") return "Specific Manager";
   if (scope === "ASSIGNED:<id>") return "Specific Employee";

   // Handle actual values with IDs (e.g., "TEAM:123")
   if (scope.startsWith("TEAM:")) return "Specific Team";
   if (scope.startsWith("MANAGED_BY:")) return "Specific Manager";
   if (scope.startsWith("ASSIGNED:")) return "Specific Employee";

   return scope
      .split("_")
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
      .join(" ");
};

type StepPermissionsProps = {
   formData: RoleFormData;
   updateFormData: (field: keyof RoleFormData, value: unknown) => void;
   permissionCategories?: PermissionCategory[];
   isLoading?: boolean;
   formRef?: MutableRefObject<UseFormReturn<any> | null>;
};

function StepPermissions({
   formData,
   updateFormData,
   permissionCategories = [],
   isLoading = false,
   formRef,
}: StepPermissionsProps) {
   const [searchQuery, setSearchQuery] = useState("");
   const [selectedPreset, setSelectedPreset] = useState<string | null>(null);
   const { t } = useTranslation("settings");

   // Fetch teams and employees for scope selectors
   const { data: teamsData } = useListTeams();
   const { data: employeesData } = useListEmployees();

   const currentPermissions = useMemo(
      () => formData.permissions || [],
      [formData.permissions]
   );

   const handlePermissionToggle = useCallback((
      permissionId: number,
      defaultScope?: string
   ) => {
      const isSelected = currentPermissions.some(
         (permission) => permission.permission_id === permissionId
      );

      const updated = isSelected
         ? currentPermissions.filter(
              (permission) => permission.permission_id !== permissionId
           )
         : [
              ...currentPermissions,
              {
                 permission_id: permissionId,
                 scope: defaultScope || "DEFAULT",
              },
           ];

      setSelectedPreset(null); // Clear preset when manually changing
      updateFormData("permissions", updated);
   }, [currentPermissions, updateFormData]);

   const handleScopeChange = useCallback((permissionId: number, scope: string) => {
      const updated = currentPermissions.map((permission) =>
         permission.permission_id === permissionId
            ? { ...permission, scope }
            : permission
      );
      setSelectedPreset(null); // Clear preset when manually changing scope
      updateFormData("permissions", updated);
   }, [currentPermissions, updateFormData]);

   const handleTeamChange = useCallback((permissionId: number, teamId: string) => {
      const updated = currentPermissions.map((permission) =>
         permission.permission_id === permissionId
            ? { ...permission, scope: teamId ? `TEAM:${teamId}` : "TEAM" }
            : permission
      );
      updateFormData("permissions", updated);
   }, [currentPermissions, updateFormData]);

   const handleManagerChange = useCallback((permissionId: number, managerId: string) => {
      const updated = currentPermissions.map((permission) =>
         permission.permission_id === permissionId
            ? { ...permission, scope: managerId ? `MANAGED_BY:${managerId}` : "MANAGED_BY" }
            : permission
      );
      updateFormData("permissions", updated);
   }, [currentPermissions, updateFormData]);

   const handleAssignedChange = useCallback((permissionId: number, employeeId: string) => {
      const updated = currentPermissions.map((permission) =>
         permission.permission_id === permissionId
            ? { ...permission, scope: employeeId ? `ASSIGNED:${employeeId}` : "ASSIGNED" }
            : permission
      );
      updateFormData("permissions", updated);
   }, [currentPermissions, updateFormData]);

   const applyPreset = useCallback((preset: PermissionPreset) => {
      // Toggle preset - if already selected, deselect and clear permissions
      if (selectedPreset === preset.name) {
         setSelectedPreset(null);
         updateFormData("permissions", []);
         toast.success(`Cleared "${preset.label}" preset`);
         return;
      }

      const newPermissions: Array<{ permission_id: number; scope: string }> = [];

      // Find each permission by name and add it
      preset.permissions.forEach((presetPerm) => {
         permissionCategories.forEach((category) => {
            const permission = category.permissions.find(
               (p) => p.permission_name === presetPerm.permission_name
            );
            if (permission) {
               newPermissions.push({
                  permission_id: permission.permission_id,
                  scope: presetPerm.scope || permission.scope_default || "DEFAULT",
               });
            }
         });
      });

      setSelectedPreset(preset.name);
      updateFormData("permissions", newPermissions);
      toast.success(`Applied "${preset.label}" preset`);
   }, [permissionCategories, selectedPreset, updateFormData]);

   const filteredCategories = useMemo(() => {
      if (!searchQuery) return permissionCategories;
      const query = searchQuery.toLowerCase();
      return permissionCategories
         .map((category) => ({
            ...category,
            permissions: category.permissions.filter(
               (permission) =>
                  permission.permission_name.toLowerCase().includes(query) ||
                  category.category.toLowerCase().includes(query)
            ),
         }))
         .filter((category) => category.permissions.length > 0);
   }, [permissionCategories, searchQuery]);

   const fields = useMemo(() => [
      {
         name: "permissions",
         type: "custom" as const,
         label: t("wizard.permissions.title"),
         render: () => (
            <>
               <div className="mb-4">
                  <h4 className="text-base sm:text-lg font-semibold text-text-strong">
                     {t("wizard.permissions.categoriesTitle")}
                  </h4>
               </div>

               {/* Permission Presets */}
               <div className="mb-4 space-y-2">
                  <label className="block text-sm font-medium text-text-strong">
                     {t("wizard.permissions.quickPresets")}
                  </label>
                  <div className="flex flex-wrap gap-2">
                     {PERMISSION_PRESETS.map((preset) => {
                        const isSelected = selectedPreset === preset.name;
                        return (
                           <Button
                              key={preset.name}
                              variant="secondary"
                              onClick={() => applyPreset(preset)}
                              className={`text-xs py-2 px-3 transition-all ${
                                 isSelected
                                    ? "bg-primary text-background border-primary hover:bg-primary-dark"
                                    : "border-primary/30 text-primary hover:bg-primary/10"
                              }`}
                              title={preset.description}>
                              {preset.label}
                           </Button>
                        );
                     })}
                  </div>
               </div>

               {/* Search */}
               <div className="relative mb-4">
                  <div className="absolute left-3 top-1/2 transform -translate-y-1/2">
                     <Search size={16} className="fill-text-soft" />
                  </div>
                  <input
                     type="text"
                     value={searchQuery}
                     onChange={(e) =>
                        setSearchQuery(e.target.value)
                     }
                     placeholder={t("wizard.permissions.searchPlaceholder")}
                     className="w-full pl-10 pr-4 py-2.5 text-sm rounded-xl border border-border bg-bg-weak text-text-strong placeholder:text-text-soft focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary focus:bg-background transition-all"
                  />
               </div>

               {/* Permissions List */}
               <div className="bg-bg-weak rounded-xl sm:rounded-2xl p-3">
                  <div className="space-y-6 flex flex-col">
                     {isLoading ? (
                        <div className="py-10 flex items-center justify-center">
                           <Loader label={t("wizard.permissions.loading")} />
                        </div>
                     ) : filteredCategories.length === 0 ? (
                        <div className="py-8 text-center">
                           <p className="text-sm text-text-soft">
                              {t("wizard.permissions.noPermissions")}
                           </p>
                        </div>
                     ) : (
                        filteredCategories.map((category) => (
                           <div
                              key={category.category}
                              className="space-y-3">
                              <div className="flex items-center">
                                 <h5 className="text-sm sm:text-base font-semibold text-text-strong">
                                    {formatPermissionName(
                                       category.category
                                    )}
                                 </h5>
                              </div>

                              <div className="space-y-2.5 flex-col">
                                 {category.permissions.map(
                                    (permission) => {
                                       const selectedPermission =
                                          currentPermissions.find(
                                             (selected) =>
                                                selected.permission_id ===
                                                permission.permission_id
                                          );

                                       // Get scope options - keep all options including TEAM, MANAGED_BY, ASSIGNED
                                       const rawScopeOptions = permission.scope_options || [];
                                       const scopeOptions = rawScopeOptions
                                          .map((opt: string) => {
                                             const label = formatScopeLabel(opt);
                                             return label ? { value: opt, label } : null;
                                          })
                                          .filter((opt): opt is { value: string; label: string } => opt !== null);

                                       // Determine if we need additional selectors
                                       const needsTeamSelect = selectedPermission && (
                                          selectedPermission.scope.startsWith("TEAM:") ||
                                          selectedPermission.scope === "TEAM:<id>"
                                       );
                                       const needsManagerSelect = selectedPermission && (
                                          selectedPermission.scope.startsWith("MANAGED_BY:") ||
                                          selectedPermission.scope === "MANAGED_BY:<id>"
                                       );
                                       const needsAssignedSelect = selectedPermission && (
                                          selectedPermission.scope.startsWith("ASSIGNED:") ||
                                          selectedPermission.scope === "ASSIGNED:<id>"
                                       );


                                       const teamId = selectedPermission?.scope?.startsWith("TEAM:") && selectedPermission.scope !== "TEAM:<id>" ? selectedPermission.scope.split(":")[1] : "";
                                       const managerId = selectedPermission?.scope?.startsWith("MANAGED_BY:") && selectedPermission.scope !== "MANAGED_BY:<id>" ? selectedPermission.scope.split(":")[1] : "";
                                       const assignedId = selectedPermission?.scope?.startsWith("ASSIGNED:") && selectedPermission.scope !== "ASSIGNED:<id>" ? selectedPermission.scope.split(":")[1] : "";

                                       return (
                                          <div
                                             key={permission.permission_id}
                                             className="space-y-2">
                                             <div className="flex items-center justify-between gap-3 py-1.5 px-2 rounded-lg hover:bg-background/80 transition-colors">
                                                <Checkbox
                                                   id={`permission-${permission.permission_id}`}
                                                   checked={!!selectedPermission}
                                                   onChange={() =>
                                                      handlePermissionToggle(
                                                         permission.permission_id,
                                                         permission.scope_default
                                                      )
                                                   }
                                                   label={formatPermissionName(
                                                      permission.permission_name
                                                   )}
                                                />
                                                <div className="flex items-center gap-2">
                                                   {selectedPermission &&
                                                      scopeOptions.length > 0 && (
                                                         <Select
                                                            options={scopeOptions}
                                                            value={
                                                               // Show "TEAM:<id>" option when scope has a specific team ID
                                                               selectedPermission.scope.startsWith("TEAM:") && selectedPermission.scope !== "TEAM" ? "TEAM:<id>" :
                                                               // Show "MANAGED_BY:<id>" option when scope has a specific manager ID
                                                               selectedPermission.scope.startsWith("MANAGED_BY:") && selectedPermission.scope !== "MANAGED_BY" ? "MANAGED_BY:<id>" :
                                                               // Show "ASSIGNED:<id>" option when scope has a specific employee ID
                                                               selectedPermission.scope.startsWith("ASSIGNED:") && selectedPermission.scope !== "ASSIGNED" ? "ASSIGNED:<id>" :
                                                               // Otherwise show the exact scope value (including TEAM, MANAGED_BY, ASSIGNED, DEFAULT, ALL)
                                                               selectedPermission.scope
                                                            }
                                                            onChange={(value) =>
                                                               handleScopeChange(
                                                                  permission.permission_id,
                                                                  value
                                                               )
                                                            }
                                                            className="text-xs [&_button]:py-2.5 [&_button]:px-3 [&_button]:text-xs [&_button]:rounded-xl [&_button]:h-[42px]"
                                                         />
                                                      )}

                                                   {/* Team Selector - inline */}
                                                   {needsTeamSelect && teamsData?.data && (
                                                      <SearchableSelect
                                                         placeholder="Select team..."
                                                         value={teamId}
                                                         onChange={(value) => handleTeamChange(permission.permission_id, value)}
                                                         options={teamsData.data.map(team => ({
                                                            id: String(team.id),
                                                            label: team.name,
                                                         }))}
                                                      />
                                                   )}

                                                   {/* Manager Selector - inline */}
                                                   {needsManagerSelect && employeesData?.data && (
                                                      <SearchableSelect
                                                         placeholder="Select manager..."
                                                         value={managerId}
                                                         onChange={(value) => handleManagerChange(permission.permission_id, value)}
                                                         options={employeesData.data.map(emp => ({
                                                            id: String(emp.id),
                                                            label: emp.name,
                                                            avatarUrl: emp.avatar || undefined,
                                                         }))}
                                                      />
                                                   )}

                                                   {/* Assigned Employee Selector - inline */}
                                                   {needsAssignedSelect && employeesData?.data && (
                                                      <SearchableSelect
                                                         placeholder="Select employee..."
                                                         value={assignedId}
                                                         onChange={(value) => handleAssignedChange(permission.permission_id, value)}
                                                         options={employeesData.data.map(emp => ({
                                                            id: String(emp.id),
                                                            label: emp.name,
                                                            avatarUrl: emp.avatar || undefined,
                                                         }))}
                                                      />
                                                   )}
                                                </div>
                                             </div>
                                          </div>
                                       );
                                    }
                                 )}
                              </div>
                           </div>
                        ))
                     )}
                  </div>
               </div>
            </>
         ),
      },
   ], [
      t,
      filteredCategories,
      currentPermissions,
      searchQuery,
      selectedPreset,
      isLoading,
      teamsData,
      employeesData,
      applyPreset,
      handleAssignedChange,
      handleManagerChange,
      handlePermissionToggle,
      handleScopeChange,
      handleTeamChange,
   ]); // Add missing deps

   return (
      <>
         <div className="w-full max-w-full">
            <div className="bg-background border rounded-xl sm:rounded-2xl border-border flex flex-col overflow-y-auto [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none] w-full max-w-full sm:max-w-2xl md:max-w-full xl:max-w-[2400px] h-auto min-h-[500px] sm:min-h-[600px] md:min-h-[650px] xl:h-[720px] p-4 sm:p-5 md:p-6 gap-4 sm:gap-5 md:gap-6 xl:gap-8">
               {/* Header */}
               <div className="shrink-0">
                  <h3 className="text-lg sm:text-xl font-semibold text-text-strong">
                     {t("wizard.permissions.title")}
                  </h3>
                  <p className="mt-1 text-xs sm:text-sm text-text-soft">
                     {t("wizard.permissions.subtitle")}
                  </p>
               </div>

               {/* Categories & Permissions Section */}
               <GenericForm<RoleFormData>
                  schema={roleSchema}
                  defaultValues={formData}
                  onSubmit={() => {}}
                  onFieldChange={updateFormData}
                  showSubmitButton={false}
                  mode="onChange"
                  className="space-y-4 flex-1"
                  fields={fields}
                  renderFields={(form) => {
                     if (formRef) {
                        formRef.current = form;
                     }

                     return fields.map((fieldConfig) => (
                        <GenericFormField
                           key={fieldConfig.name}
                           fieldConfig={fieldConfig}
                           form={form}
                           onFieldChange={(field, value) =>
                              updateFormData(field as keyof RoleFormData, value)
                           }
                        />
                     ));
                  }}
               />
            </div>
         </div>
      </>
   );
}

