         icon: Edit,
         onClick: () => {
            onEdit?.(incomeType);
            setIsOpen(false);
         },
         variant: "default",
      },
      {
         id: "delete",
         label: t("incomeTypes.actions.delete") || "Delete",
         icon: Trash,
         onClick: () => {
            onDelete(incomeType.income_type_id || incomeType.id!);
            setIsOpen(false);
         },
         variant: "danger",
      },
   ];

   return (
      <div className="flex justify-end">
         <button
            ref={buttonRef}
            type="button"
            aria-label={t("incomeTypes.actions.label") || "Actions"}
            className={`p-1.5 transition-colors rounded-lg flex items-center justify-center w-8 h-8 ${
               isOpen
                  ? "bg-bg-weak"
                  : "bg-transparent hover:bg-bg-weak active:bg-border"
            }`}
            data-row-menu-trigger
            onClick={() => setIsOpen(!isOpen)}>
            <MoreVertical size={20} />
         </button>

         <Dropdown
            items={dropdownItems}
            isOpen={isOpen}
            onClose={() => setIsOpen(false)}
            anchorRef={buttonRef}
         />
      </div>
   );
}

export default function IncomeTypesTab({ searchQuery, sortBy, onEdit }: IncomeTypesTabProps) {
   const { t } = useTranslation("settings");
   const [deleteModalOpen, setDeleteModalOpen] = useState(false);
   const [incomeTypeToDelete, setIncomeTypeToDelete] = useState<
      string | number | null
   >(null);
   const [incomeTypesToDelete, setIncomeTypesToDelete] = useState<
      (string | number)[]
   >([]);
   const [selectionResetSignal, setSelectionResetSignal] = useState(0);
   const [deleteModalState, setDeleteModalState] = useState<
      "idle" | "loading" | "success"
   >("idle");

   // Fetch income types from API
   const { data: incomeTypesResponse, isLoading } = useListIncomeTypes(
      undefined,
      { enabled: true }
   );

   // Delete mutation
   const deleteIncomeType = useDeleteIncomeType();

   // Get income types from response
   const incomeTypesData = incomeTypesResponse?.data || [];

   const handleDeleteClick = useCallback((id: string | number) => {
      setIncomeTypeToDelete(id);
      setIncomeTypesToDelete([]);
      setDeleteModalOpen(true);
   }, []);

   const handleBulkDelete = useCallback((data: IncomeType[]) => {
      setIncomeTypesToDelete(
         data.map((item) => item.income_type_id || item.id!)
      );
      setIncomeTypeToDelete(null);
      setDeleteModalOpen(true);
   }, []);

   const handleDeleteConfirm = useCallback(async () => {
      if (!incomeTypeToDelete && incomeTypesToDelete.length === 0) return;

      setDeleteModalState("loading");
      try {
         if (incomeTypeToDelete) {
            await deleteIncomeType.mutateAsync(incomeTypeToDelete);
         } else if (incomeTypesToDelete.length > 0) {
            await Promise.all(
               incomeTypesToDelete.map((id) =>
                  deleteIncomeType.mutateAsync(id)
               )
            );
         }

         toast.success(
            incomeTypeToDelete
               ? t("incomeTypes.toast.deleteSuccess") || "Income Type deleted successfully"
               : t("incomeTypes.toast.deleteMultipleSuccess") || "Income Types deleted successfully"
         );

         setSelectionResetSignal((prev) => prev + 1);
         setDeleteModalState("success");
         setTimeout(() => {
            setDeleteModalOpen(false);
            setIncomeTypeToDelete(null);
            setIncomeTypesToDelete([]);
            setDeleteModalState("idle");
         }, 600);
      } catch (error) {
         let errorMessage = t("incomeTypes.toast.deleteError") || "Error deleting Income Type";
         if (error instanceof Error && error.message) {
            errorMessage = error.message;
         }
         toast.error(errorMessage);
         setDeleteModalState("idle");
         setDeleteModalOpen(false);
         setIncomeTypeToDelete(null);
         setIncomeTypesToDelete([]);
      }
   }, [incomeTypeToDelete, incomeTypesToDelete, deleteIncomeType, t]);

   const handleDeleteCancel = useCallback(() => {
      if (deleteModalState === "loading") return;
      setDeleteModalOpen(false);
      setIncomeTypeToDelete(null);
      setIncomeTypesToDelete([]);
      setDeleteModalState("idle");
   }, [deleteModalState]);

   // Column definitions
   const columns = useMemo<ColumnDef<IncomeType>[]>(
      () => [
         {
            id: "select",
            header: ({ table }) => (
               <Checkbox
                  checked={table.getIsAllRowsSelected()}
                  onChange={table.getToggleAllRowsSelectedHandler()}
                  className="m-0 mb-0.5 me-0.5"
               />
            ),
            cell: ({ row }) => (
               <Checkbox
                  checked={row.getIsSelected()}
                  onChange={row.getToggleSelectedHandler()}
                  className="m-0 me-0.5"
               />
            ),
            size: 20,

         },
         {
            accessorKey: "name",
            header: () => (
               <span className="text-sm text-text-strong">
                  {t("incomeTypes.table.name") || "Name"}
               </span>
            ),
            cell: ({ row }) => {
               const name = row.original.type_name || row.original.name;
               return (
                  <p className="text-sm text-text-strong truncate">{name}</p>
               );
            },
            size: 300,

         },
         {
            accessorKey: "income_code",
            header: () => (
               <span className="text-sm text-text-strong">
                  {t("incomeTypes.table.incomeCode") ||
                     t("incomeTypes.table.glCode") ||
                     "Income Code"}
               </span>
            ),
            cell: ({ row }) => {
               const value =
                  row.original.income_code || row.original.gl_code || "-";
               return (
                  <p className="text-sm text-text-strong truncate">
                     {value}
                  </p>
               );
            },
            size: 200,

         },
         {
            id: "actions",
            header: () => <div />,
            cell: ({ row }) => (
               <ActionsCell
                  incomeType={row.original}
                  onDelete={handleDeleteClick}
                  onEdit={onEdit}
               />
            ),
            size: 64,
         },
      ],
      [t, handleDeleteClick, onEdit]
   );

   // Use local table data hook for client-side search, filtering, and sorting
   const { data: filteredIncomeTypes } = useLocalTableData({
      data: incomeTypesData,
      searchQuery,
      searchFields: ["name", "type_name", "income_code", "gl_code"],
      filters: {}, // No filters currently
      sortField: (() => {
         if (sortBy === "newest" || sortBy === "oldest") {
            return "created_at";
         }
         return (sortBy || "name_asc").split("_")[0];
      })(),
      sortDirection: (() => {
         if (sortBy === "newest") return "desc";
         if (sortBy === "oldest") return "asc";
         return (sortBy || "name_asc").split("_")[1] as "asc" | "desc";
      })(),
      customSortFn: (a, b, field, direction) => {
         if (field === "created_at") {
            const aDate = a.created_at ? new Date(a.created_at).getTime() : 0;
            const bDate = b.created_at ? new Date(b.created_at).getTime() : 0;
            return direction === "asc" ? aDate - bDate : bDate - aDate;
         }
         // fallback to default
         const aVal = a[field as keyof typeof a] as any;
         const bVal = b[field as keyof typeof b] as any;
         const comparison = String(aVal ?? "").localeCompare(String(bVal ?? ""));
         return direction === "asc" ? comparison : -comparison;
      },
   });

   const renderFloatingBar = useCallback(
      (selectedCount: number, selectedData: IncomeType[]) => (
         <IncomeTypesFloatingActionBar
            selectedCount={selectedCount}
            selectedRows={selectedData}
            onEdit={(incomeType) => onEdit?.(incomeType)}
            onDelete={(incomeTypes) => handleBulkDelete(incomeTypes)}
            resetSignal={selectionResetSignal}
         />
      ),
      [handleBulkDelete, onEdit, selectionResetSignal]
   );

   if (isLoading) {
      return (
         <LoadingState
            size="medium"
            label={t("incomeTypes.loading", "Loading income types...")}
         />
      );
   }

   return (
      <>
         <DataTable
            data={filteredIncomeTypes as IncomeType[]}
            columns={columns}
            enableRowSelection
            renderFloatingBar={renderFloatingBar}
            globalFilter={searchQuery}
            translationNamespace="settings"
            resetSelectionSignal={selectionResetSignal}
         />
         <DeleteIncomeTypeModal
            isOpen={deleteModalOpen}
            onClose={handleDeleteCancel}
            onConfirm={handleDeleteConfirm}
            isLoading={deleteModalState === "loading"}
            isSuccess={deleteModalState === "success"}
         />
      </>
   );
}

/** @format */

import { useState, useEffect, useRef } from "react";
import { useSearchParams } from "react-router-dom";
import { AnimatePresence, motion } from "framer-motion";
import { useTranslation } from "@/hooks/useTranslation";
import SearchInput from "@/designSystem/SearchInput";
import SortDropdown from "@/designSystem/SortDropdown";
import { Buildings, UsersGroup, Plus } from "@/Icons";
import CustomersTab from "./tabs/CustomersTab";
import AgentsTab from "./tabs/AgentsTab";
import AddCustomerModal from "./modals/AddCustomerModal";
import AddAgentModal from "./modals/AddAgentModal";
import { useCreateCustomer } from "@/hooks/customers/useCustomers";
import { useCreateAgent } from "@/hooks/agents/useAgents";
import StatusFilterDropdown, { StatusFilters } from "../../shared/StatusFilterDropdown";
import type { CreateCustomerRequest } from "@/services/customerService";
import type { CreateAgentRequest } from "@/services/agentService";

type TabType = "customers" | "agents";

function InvoiceProfilesView() {
	const { t } = useTranslation("settings");
	const [searchParams, setSearchParams] = useSearchParams();
	const tabParam = searchParams.get("tab");

	// Map URL tab query param to TabType, default to "customers"
	const activeTab: TabType = tabParam === "agents" ? "agents" : "customers";

	// Underline animation state
	const [underlineStyle, setUnderlineStyle] = useState<{
		left: number;
		width: number;
	}>({ left: 0, width: 0 });
	const tabRefs = useRef<{ [key: string]: HTMLButtonElement | null }>({});

	// Set default tab query param if not specified
	useEffect(() => {
		if (!tabParam) {
			setSearchParams({ tab: "customers" }, { replace: true });
		}
	}, [tabParam, setSearchParams]);

	// Update underline position when active tab changes
	useEffect(() => {
		const updateUnderline = () => {
			const activeTabElement = tabRefs.current[activeTab];
			if (activeTabElement) {
				const { offsetLeft, offsetWidth } = activeTabElement;
				setUnderlineStyle({
					left: offsetLeft,
					width: offsetWidth,
				});
			}
		};

		updateUnderline();
		window.addEventListener("resize", updateUnderline);
		return () => window.removeEventListener("resize", updateUnderline);
	}, [activeTab]);
	const [searchQuery, setSearchQuery] = useState("");
	const [isAddCustomerModalOpen, setIsAddCustomerModalOpen] = useState(false);
	const [isAddAgentModalOpen, setIsAddAgentModalOpen] = useState(false);
	const [customersFilters, setCustomersFilters] = useState<StatusFilters>({ status: [] });
	const [agentsFilters, setAgentsFilters] = useState<StatusFilters>({ status: [] });
	const [sortBy, setSortBy] = useState<string>("name_asc");

	// Create customer mutation
	const createCustomer = useCreateCustomer();

	// Create agent mutation
	const createAgent = useCreateAgent();

	const tabs = [
		{
			id: "customers" as TabType,
			icon: Buildings,
			label: t("invoiceProfiles.tabs.customers"),
		},
		{
			id: "agents" as TabType,
			icon: UsersGroup,
			label: t("invoiceProfiles.tabs.agents"),
		},
	];

	return (
		<div className='flex size-full flex-col gap-6'>
			{/* Horizontal Tabs */}
			<div className='relative flex gap-6 border-b border-border pb-3.5'>
				{tabs.map((tab) => {
					const Icon = tab.icon;
					const isActive = activeTab === tab.id;
					return (
						<button
							key={tab.id}
							ref={(el) => (tabRefs.current[tab.id] = el)}
							onClick={() =>
								setSearchParams({ tab: tab.id }, { replace: false })
							}
							className={`flex items-center gap-1.5 relative ${
								isActive ? "text-primary" : "text-text-sub"
							}`}>
							<Icon size={20} active={isActive} />
							<span className='text-sm font-medium leading-5 tracking-[-0.084px]'>
								{tab.label}
							</span>
						</button>
					);
				})}
				{/* Animated Underline */}
				<span
					className='absolute -bottom-0.5 h-0.5 bg-primary transition-all duration-300 ease-in-out rounded-t-lg'
					style={{
						left: `${underlineStyle.left}px`,
						width: `${underlineStyle.width}px`,
					}}
				/>
			</div>

			{/* Title and Description */}
			<div className='flex flex-col gap-1'>
				<h1 className='text-lg font-medium leading-6 tracking-[-0.27px] text-text-strong'>
					{t(`invoiceProfiles.tabs.${activeTab}`)}
				</h1>
				<p className='text-sm leading-5 tracking-[-0.084px] text-text-sub'>
					{t("invoiceProfiles.description")}
				</p>
			</div>

			{/* Action Bar */}
			<div className='flex items-center justify-between w-full'>
				<SearchInput
					value={searchQuery}
					onChange={setSearchQuery}
					placeholder={t(`invoiceProfiles.searchPlaceholder.${activeTab}`)}
					className='w-[280px]'
				/>

				<div className='flex items-center gap-2'>
					<StatusFilterDropdown 
						onApply={activeTab === "customers" ? setCustomersFilters : setAgentsFilters}
						translationNamespace="settings"
						translationPrefix={`invoiceProfiles.${activeTab}`}
					/>

					<SortDropdown
						label={t("invoiceProfiles.sortBy")}
						options={[
							{
								id: "name_asc",
								label: t("invoiceProfiles.sortOptions.nameAsc"),
							},
							{
								id: "name_desc",
								label: t("invoiceProfiles.sortOptions.nameDesc"),
							},
							{
								id: "newest",
								label: t("invoiceProfiles.sortOptions.newest"),
							},
							{
								id: "oldest",
								label: t("invoiceProfiles.sortOptions.oldest"),
							},
						]}
						onSelect={(id) => setSortBy(id)}
					/>

					<button
						className='bg-text-strong text-background flex items-center gap-1.5 px-3 py-2 rounded-lg hover:bg-bg-dark/90 transition-colors text-sm font-medium leading-5 tracking-[-0.084px] shrink-0'
						onClick={() => {
							if (activeTab === "customers") {
								setIsAddCustomerModalOpen(true);
							} else {
								setIsAddAgentModalOpen(true);
							}
						}}>
						<Plus size={20} className='fill-background' />
						{t(`invoiceProfiles.addButton.${activeTab}`)}
					</button>
				</div>
			</div>

			{/* Content based on active tab */}
			<AnimatePresence mode='wait'>
				{activeTab === "customers" ? (
					<motion.div
						key='customers'
						initial={{ opacity: 0, y: 20 }}
						animate={{ opacity: 1, y: 0 }}
						exit={{ opacity: 0, y: -20 }}
						transition={{ duration: 0.3, ease: "easeInOut" }}>
						<CustomersTab searchQuery={searchQuery} filters={customersFilters} sortBy={sortBy} />
					</motion.div>
				) : activeTab === "agents" ? (
					<motion.div
						key='agents'
						initial={{ opacity: 0, y: 20 }}
						animate={{ opacity: 1, y: 0 }}
						exit={{ opacity: 0, y: -20 }}
						transition={{ duration: 0.3, ease: "easeInOut" }}>
						<AgentsTab searchQuery={searchQuery} filters={agentsFilters} sortBy={sortBy} />
					</motion.div>
				) : null}
			</AnimatePresence>

			{/* Modals */}
			<AddCustomerModal
				isOpen={isAddCustomerModalOpen}
				onClose={() => setIsAddCustomerModalOpen(false)}
				isLoading={createCustomer.isPending}
				onSuccess={async (customerData) => {
					try {
						// Transform form data to API format
						// Handle status: form uses lowercase "active"|"inactive", API expects "Active"|"Inactive"
						const statusValue = String(customerData.status || "").toLowerCase();
						const payload: CreateCustomerRequest = {
							customer_name: customerData.name || "",
							customer_type: customerData.type || "Individual",
							contact_number: customerData.contactNumber || "",
							email: customerData.email || "",
							trn: customerData.trnId || "",
							status: statusValue === "active" ? "Active" : "Inactive",
							// Optional fields not in form - can be added later
							// address: undefined,
							// notes: undefined,
							// mobile_no: undefined,
						};

						await createCustomer.mutateAsync(payload);
						setIsAddCustomerModalOpen(false);
					} catch (error) {
						console.error("Error creating customer:", error);
					}
				}}
			/>
			<AddAgentModal
				isOpen={isAddAgentModalOpen}
				onClose={() => setIsAddAgentModalOpen(false)}
				isLoading={createAgent.isPending}
				onSuccess={async (agentData) => {
					try {
						// Transform form data to API format
						// Handle status: form uses lowercase "active"|"inactive", API expects "Active"|"Inactive"
						const statusValue = String(agentData.status || "").toLowerCase();

						const payload: CreateAgentRequest = {
							name: agentData.name || "",
							number: (agentData as any).number || "",
							contact_number: agentData.contactNumber || "",
							email: agentData.email || "",
							address: (agentData as any).address || undefined,
							notes: (agentData as any).notes || undefined,
							status: statusValue === "active" ? "Active" : "Inactive",
						};

						await createAgent.mutateAsync(payload);
						setIsAddAgentModalOpen(false);
					} catch (error) {
						console.error("Error creating agent:", error);
					}
				}}
			/>
		</div>
	);
}

export default InvoiceProfilesView;

/** @format */

import { useMemo, useState } from "react";
import { useTranslation } from "@/hooks/useTranslation";
import Modal from "@/designSystem/Modal";
import GenericForm, { FieldConfig } from "@/designSystem/GenericForm";
import Button from "@/designSystem/Button";
import ConfirmModal from "@/designSystem/ConfirmModal";
import PhoneInput from "@/designSystem/ui/PhoneInput";
import * as yup from "yup";
import type { Agent } from "../types";

type AddAgentModalProps = {
	isOpen: boolean;
	onClose: () => void;
	isLoading?: boolean;
	agent?: Agent | null; // For editing
	onSuccess?: (agent: Omit<Agent, "id">) => void;
};

type AgentFormValues = {
	name: string;
	number: string;
	contactNumber: string;
	email: string;
	address?: string;
	notes?: string;
	status: "active" | "inactive";
};

function AddAgentModal({
	isOpen,
	onClose,
	isLoading = false,
	agent,
	onSuccess,
}: AddAgentModalProps) {
	const { t } = useTranslation("settings");
	const { t: tCommon } = useTranslation("common");
	const isEditMode = !!agent;
	const [isDirty, setIsDirty] = useState(false);
	const [showDiscardConfirm, setShowDiscardConfirm] = useState(false);

	const schema = yup.object().shape({
		name: yup.string().required(t("validation.required")),
		number: yup.string().required(t("validation.required")),
		contactNumber: yup.string().required(t("validation.required")),
		email: yup
			.string()
			.email(t("validation.email"))
			.required(t("validation.required")),
		address: yup.string().optional(),
		notes: yup.string().optional(),
		status: yup
			.string()
			.oneOf(["active", "inactive"])
			.required(t("validation.required")),
	});

	const fields: FieldConfig[] = useMemo(
		() => [
			{
				name: "name",
				label: t("invoiceProfiles.modal.agentName"),
				placeholder: t("invoiceProfiles.modal.agentNamePlaceholder"),
				type: "text",
				required: true,
				disabled: isLoading,
			},
			{
				name: "number",
				label: t("invoiceProfiles.modal.agentNumber"),
				placeholder: t("invoiceProfiles.modal.agentNumberPlaceholder"),
				type: "text",
				required: true,
				disabled: isLoading,
			},
			{
				name: "contactNumber",
				type: "custom",
				label: t("invoiceProfiles.modal.contactNumber"),
				required: true,
				render: (form) => (
					<div className='flex flex-col gap-1'>
						<label className='block text-sm font-medium text-text-strong'>
							{t("invoiceProfiles.modal.contactNumber")}
							<span className='text-primary'>*</span>
						</label>
						<PhoneInput
							value={form.watch("contactNumber") || ""}
							onChange={(value) => {
								form.setValue("contactNumber", value || "", {
									shouldValidate: true,
									shouldDirty: true,
								});
							}}
							placeholder={t("invoiceProfiles.modal.contactNumberPlaceholder")}
							disabled={isLoading}
						/>
						{form.formState.errors.contactNumber && (
							<p className='text-sm text-danger mt-1'>
								{form.formState.errors.contactNumber.message as string}
							</p>
						)}
					</div>
				),
			},
			{
				name: "email",
				type: "custom",
				label: t("invoiceProfiles.modal.emailAddress"),
				required: true,
				render: (form) => (
					<div className='flex flex-col gap-1'>
						<label className='block text-sm font-medium text-text-strong'>
							{t("invoiceProfiles.modal.emailAddress")}
							<span className='text-primary'>*</span>
						</label>
						<input
							type='email'
							{...form.register("email")}
							placeholder={t("invoiceProfiles.modal.emailAddressPlaceholder")}
							disabled={isLoading}
							className='w-full px-3 py-2.5 text-sm rounded-[10px] border border-border bg-background text-text-sub placeholder:text-text-soft focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent transition-colors disabled:opacity-50 disabled:cursor-not-allowed'
						/>
						{form.formState.errors.email && (
							<p className='text-sm text-danger mt-1'>
								{form.formState.errors.email.message as string}
							</p>
						)}
					</div>
				),
			},
			{
				name: "address",
				label: t("invoiceProfiles.modal.address"),
				placeholder: t("invoiceProfiles.modal.addressPlaceholder"),
				type: "text",
				required: false,
				disabled: isLoading,
			},
			{
				name: "notes",
				label: t("invoiceProfiles.modal.notes"),
				placeholder: t("invoiceProfiles.modal.notesPlaceholder"),
				type: "textarea",
				required: false,
				disabled: isLoading,
			},
			{
				name: "status",
				label: t("invoiceProfiles.modal.status"),
				placeholder: t("invoiceProfiles.modal.statusPlaceholder"),
				type: "select",
				required: true,
				disabled: isLoading,
				options: [
					{ id: "active", label: t("invoiceProfiles.status.active") },
					{ id: "inactive", label: t("invoiceProfiles.status.inactive") },
				],
			},
		],
		[t, isLoading]
	);

	const handleSubmit = async (data: AgentFormValues) => {
		if (isLoading) {
			return;
		}
		if (onSuccess) {
			onSuccess({
				name: data.name,
				number: data.number,
				contactNumber: data.contactNumber,
				email: data.email,
				address: data.address,
				notes: data.notes,
				status: data.status,
			} as any);
		}
		onClose();
	};

	// Compute default values based on agent prop
	const defaultValues = useMemo(() => {
		if (agent) {
			return {
				name: agent.name || "",
				number: agent.number || agent.agent_code || "",
				contactNumber: agent.contact_number || agent.contactNumber || "",
				email: agent.email || "",
				address: agent.address || "",
				notes: agent.notes || "",
				status: (agent.status?.toLowerCase() || "active") as "active" | "inactive",
			};
		}
		return {
			name: "",
			number: "",
			contactNumber: "",
			email: "",
			address: "",
			notes: "",
			status: "active" as "active" | "inactive",
		};
	}, [agent]);

	const handleClose = () => {
		if (isLoading) return;
		if (isDirty) {
			setShowDiscardConfirm(true);
			return;
		}
		onClose();
	};

	const footer = (
		<div className='flex justify-end gap-3 w-full'>
			<Button variant='secondary' onClick={handleClose} disabled={isLoading}>
				{t("invoiceProfiles.modal.cancel")}
			</Button>
			<Button type='submit' form='add-agent-form' disabled={isLoading}>
				{isLoading && (
					<span className='animate-spin mr-2 w-4 h-4 border-2 border-white border-t-transparent rounded-full inline-block align-middle' />
				)}
				{t(isEditMode ? "invoiceProfiles.modal.updateAgentButton" : "invoiceProfiles.modal.addAgentButton")}
			</Button>
		</div>
	);

	return (
		<Modal
			isOpen={isOpen}
			onClose={handleClose}
			title={t(isEditMode ? "invoiceProfiles.modal.editAgentTitle" : "invoiceProfiles.modal.addAgentTitle")}
			width='w-[30rem]'
			size='medium'
			overflow='visible'
			footer={footer}>
			<GenericForm<AgentFormValues>
				key={agent?.agent_id || agent?.id || "new"} // Force remount when switching between create/edit
				id='add-agent-form'
				schema={schema}
				onSubmit={handleSubmit}
				fields={fields}
				showSubmitButton={false}
				defaultValues={defaultValues}
				onDirtyChange={setIsDirty}
			/>
			<ConfirmModal
				isOpen={showDiscardConfirm}
				onClose={() => setShowDiscardConfirm(false)}
				onConfirm={onClose}
				title={tCommon("unsavedChanges.title")}
				description={tCommon("unsavedChanges.description")}
				confirmText={tCommon("unsavedChanges.confirm")}
				cancelText={tCommon("unsavedChanges.cancel")}
				variant='primary'
				icon='exclamation'
			/>
		</Modal>
	);
}

