		filters: filters.status.length ? { status: filters.status } : {},
		customFilterFn: (item, activeFilters) => {
			if (activeFilters.status && activeFilters.status.length) {
				const itemStatus = (item.status || "").toString().toLowerCase();
				const allowed = (activeFilters.status as string[]).map((s) =>
					s.toLowerCase()
				);
				if (!allowed.includes(itemStatus)) return false;
			}
			return true;
		},
		sortField,
		sortDirection,
		customSortFn: (a, b, field, direction) => {
			if (field === "created_at") {
				const aDate = a.created_at ? new Date(a.created_at).getTime() : 0;
				const bDate = b.created_at ? new Date(b.created_at).getTime() : 0;
				return direction === "asc" ? aDate - bDate : bDate - aDate;
			}
			const aVal = a[field as keyof typeof a] as any;
			const bVal = b[field as keyof typeof b] as any;
			const comparison = String(aVal ?? "").localeCompare(String(bVal ?? ""));
			return direction === "asc" ? comparison : -comparison;
		},
	});

	// Bulk actions handlers (must be before early return)
	const handleBulkDelete = useCallback((rows: Customer[]) => {
		setCustomersToDelete(rows);
		setIsDeleteModalOpen(true);
	}, []);

	const handleEditCustomer = useCallback((customer: Customer) => {
		setSelectedCustomer(customer);
		setIsModalOpen(true);
	}, []);

	const handleDeleteCustomer = useCallback(
		(customer: Customer) => {
			if (getCustomerInvoicesCount(customer) > 0) {
				toast.error(t("invoiceProfiles.dependency.customerHasInvoices"));
				return;
			}
			setCustomersToDelete([customer]);
			setIsDeleteModalOpen(true);
		},
		[t]
	);

	const confirmDelete = useCallback(async () => {
		if (customersToDelete.length === 0) return;
		setDeleteModalState("loading");

		try {
			await Promise.all(
				customersToDelete.map((customer) =>
					deleteCustomer.mutateAsync(customer.customer_id || customer.id!)
				)
			);

			const message =
				customersToDelete.length > 1
					? t("invoiceProfiles.toast.customers.deleteMultipleSuccess", {
							count: customersToDelete.length,
					  })
					: t("invoiceProfiles.toast.customers.deleteSuccess", {
							name:
								customersToDelete[0].customer_name ||
								customersToDelete[0].name ||
								"",
					  });

			toast.success(message);
			setSelectionResetSignal((prev) => prev + 1);
			setDeleteModalState("success");
			setTimeout(() => {
				setIsDeleteModalOpen(false);
				setCustomersToDelete([]);
				setDeleteModalState("idle");
			}, 600);
		} catch (error) {
			let errorMessage = t("invoiceProfiles.toast.customers.deleteError");
			const backendError = getBackendErrorCode(error);
			if (backendError === "CUSTOMER_HAS_INVOICES") {
				errorMessage = t("invoiceProfiles.dependency.customerHasInvoices");
			} else if (
				error &&
				typeof error === "object" &&
				"message" in error &&
				typeof (error as { message?: string }).message === "string"
			) {
				errorMessage =
					(error as { message?: string }).message ||
					errorMessage;
			}
			toast.error(errorMessage);
			setIsDeleteModalOpen(false);
			setCustomersToDelete([]);
			setDeleteModalState("idle");
		}
	}, [customersToDelete, deleteCustomer, t]);

	// Floating action bar
	const renderFloatingBar = useCallback(
		(selectedCount: number, selectedRows: Customer[]) => (
			<CustomersFloatingActionBar
				selectedCount={selectedCount}
				selectedRows={selectedRows}
				onDelete={handleBulkDelete}
				onEdit={handleEditCustomer}
				resetSignal={selectionResetSignal}
			/>
		),
		[handleBulkDelete, handleEditCustomer, selectionResetSignal]
	);

	const columns: ColumnDef<Customer>[] = useMemo(
		() => [
			// Selection checkbox column
			{
				id: "select",
				header: ({ table }) => (
					<div className='[&>div]:gap-0'>
						<Checkbox
							checked={table.getIsAllPageRowsSelected()}
							onChange={(e) =>
								table.toggleAllPageRowsSelected(e.target.checked)
							}
							className='m-0 mb-0.5 me-0.5'
						/>
					</div>
				),
				cell: ({ row }) => {
					const invoiceCount = getCustomerInvoicesCount(row.original);
					const hasDependencies = invoiceCount > 0;
					const dependenciesText = `${invoiceCount} ${
						invoiceCount === 1
							? t("invoiceProfiles.dependency.invoice")
							: t("invoiceProfiles.dependency.invoices")
					}`;

					return (
						<div
							className='[&>div]:gap-0'
							title={
								hasDependencies
									? `${t("invoiceProfiles.dependency.cannotDelete")}: ${dependenciesText}`
									: undefined
							}>
							<Checkbox
								checked={row.getIsSelected()}
								onChange={(e) => row.toggleSelected(e.target.checked)}
								className='m-0 me-0.5'
							/>
						</div>
					);
				},
				size: 20,

			},
			// Customer Name column
			{
				accessorKey: "customer_name",
				header: () => (
					<span className='text-sm text-text-strong pl-4'>
						{t("invoiceProfiles.table.customerName")}
					</span>
				),
				cell: ({ row }) => (
					<p className='text-sm text-text-strong pl-4'>
						{row.original.customer_name || row.original.name || "-"}
					</p>
				),
				size: 200,

			},
			// Type column
			{
				accessorKey: "customer_type",
				header: () => (
					<span className='text-sm text-text-strong'>
						{t("invoiceProfiles.table.type")}
					</span>
				),
				cell: ({ row }) => {
					const type =
						row.original.customer_type || row.original.type || "Individual";
					return (
						<span className='text-sm text-text-sub bg-bg-weak px-2.5 py-0.5 rounded-full'>
							{type}
						</span>
					);
				},
				size: 150,

			},
			// TRN/ID column
			{
				accessorKey: "trn",
				header: () => (
					<span className='text-sm text-text-strong'>
						{t("invoiceProfiles.table.trnId")}
					</span>
				),
				cell: ({ row }) => (
					<p className='text-sm text-text-strong'>
						{row.original.trn || row.original.trnId || "-"}
					</p>
				),
				size: 150,

			},
			// Contact Number column
			{
				accessorKey: "contact_number",
				header: () => (
					<span className='text-sm text-text-strong'>
						{t("invoiceProfiles.table.contactNumber")}
					</span>
				),
				cell: ({ row }) => {
					const contactNumber =
						row.original.contact_number || row.original.contactNumber || "";
					return contactNumber ? (
						<a
							href={`tel:${contactNumber}`}
							className='text-sm text-primary underline hover:opacity-80'>
							{contactNumber}
						</a>
					) : (
						<span className='text-sm text-text-sub'>-</span>
					);
				},
				size: 180,

			},
			// Email column
			{
				accessorKey: "email",
				header: () => (
					<span className='text-sm text-text-strong'>
						{t("invoiceProfiles.table.email")}
					</span>
				),
				cell: ({ row }) => {
					const email = row.original.email || "";
					return email ? (
						<a
							href={`mailto:${email}`}
							className='text-sm text-primary underline hover:opacity-80'>
							{email}
						</a>
					) : (
						<span className='text-sm text-text-sub'>-</span>
					);
				},
				size: 220,

			},
			// Status column
			{
				accessorKey: "status",
				header: () => (
					<span className='text-sm text-text-strong'>
						{t("invoiceProfiles.table.status")}
					</span>
				),
				cell: ({ row }) => {
					const status = row.original.status?.toLowerCase() || "active";
					const statusKey = status === "active" ? "active" : "inactive";
					return (
						<StatusTag
							label={t(`invoiceProfiles.status.${statusKey}`)}
							variant={statusKey}
							className='border-border border flex items-center justify-center ps-1! pe-2! py-0.5!'
						/>
					);
				},
				size: 150,

			},
			// Actions column
			{
				id: "actions",
				header: () => <div />,
				cell: ({ row }) => (
					<ActionsCell
						customer={row.original}
						onDelete={handleDeleteCustomer}
						onEdit={handleEditCustomer}
					/>
				),
				size: 64,
			},
		],
		[handleDeleteCustomer, handleEditCustomer, t]
	);

	// Show loader while fetching data (after all hooks)
	if (isLoading) {
		return (
			<div className="w-full">
				<LoadingState size="medium" label={t("invoiceProfiles.customers.loading")} />
			</div>
		);
	}

	if (error) {
		return (
			<div className='flex items-center justify-center py-8'>
				<div className='flex flex-col items-center gap-2'>
					<span className='text-error'>
						Error loading customers. Please try again.
					</span>
					{process.env.NODE_ENV === "development" && (
						<span className='text-xs text-text-sub'>
							{error instanceof Error ? error.message : String(error)}
						</span>
					)}
				</div>
			</div>
		);
	}

	return (
		<>
			<DataTable
				columns={columns}
				data={customers as Customer[]}
				enableRowSelection={true}
				showPagination={true}
				pageSize={7}
				globalFilter={searchQuery}
				translationNamespace='settings'
				renderFloatingBar={renderFloatingBar}
				resetSelectionSignal={selectionResetSignal}
			/>
			<AddCustomerModal
				isOpen={isModalOpen}
				onClose={() => {
					setIsModalOpen(false);
					setSelectedCustomer(null);
				}}
				customer={selectedCustomer}
				isLoading={
					selectedCustomer ? updateCustomer.isPending : createCustomer.isPending
				}
				onSuccess={async (customerData) => {
					try {
						const statusValue = String(customerData.status || "").toLowerCase();
						const displayName =
							customerData.name ||
							customerData.customer_name ||
							selectedCustomer?.customer_name ||
							t("invoiceProfiles.table.customerName");

						if (selectedCustomer) {
							// Update existing customer
							const customerId =
								selectedCustomer.customer_id || selectedCustomer.id;
							if (customerId) {
								const payload: UpdateCustomerRequest = {
									customer_name: customerData.name || undefined,
									customer_type: customerData.type || undefined,
									contact_number: customerData.contactNumber || undefined,
									email: customerData.email || undefined,
									trn: customerData.trnId || undefined,
									status: statusValue === "active" ? "Active" : "Inactive",
								};
								await updateCustomer.mutateAsync({
									id: customerId,
									payload,
								});
								toast.success(
									t("invoiceProfiles.toast.customers.updateSuccess", {
										name: displayName,
									})
								);
							}
						} else {
							// Create new customer (shouldn't happen from tab, but handle it)
							const payload: CreateCustomerRequest = {
								customer_name: customerData.name || "",
								customer_type: customerData.type || "Individual",
								contact_number: customerData.contactNumber || "",
								email: customerData.email || "",
								trn: customerData.trnId || "",
								status: statusValue === "active" ? "Active" : "Inactive",
							};
							await createCustomer.mutateAsync(payload);
							toast.success(
								t("invoiceProfiles.toast.customers.createSuccess", {
									name: displayName,
								})
							);
						}
						setIsModalOpen(false);
						setSelectedCustomer(null);
					} catch (error) {
						console.error("Error saving customer:", error);
						toast.error(t("invoiceProfiles.toast.customers.saveError"));
					}
				}}
			/>
			<DeleteCustomerModal
				isOpen={isDeleteModalOpen}
				onClose={() => {
					if (deleteModalState === "loading") return;
					setIsDeleteModalOpen(false);
					setCustomersToDelete([]);
					setDeleteModalState("idle");
				}}
				onConfirm={confirmDelete}
				count={customersToDelete.length}
				isLoading={deleteModalState === "loading"}
				isSuccess={deleteModalState === "success"}
			/>
		</>
	);
}

export default CustomersTab;

/** @format */

import { useMemo, useState, useRef, useCallback } from "react";
import { ColumnDef } from "@tanstack/react-table";
import { DataTable } from "@/designSystem/ui/data-table";
import { useTranslation } from "@/hooks/useTranslation";
import Checkbox from "@/designSystem/Checkbox";
import StatusTag from "@/designSystem/StatusTag";
import Dropdown, { DropdownItem } from "@/designSystem/Dropdown";
import { MoreVertical, Edit, Trash } from "@/Icons";
import { PrettyCashName } from "../types";
import PrettyCashNamesFloatingActionBar from "./PrettyCashNamesFloatingActionBar";
import DeletePrettyCashNameModal from "../modals/DeletePrettyCashNameModal";
import { useListPrettyCashNames, useDeletePrettyCashName } from "@/hooks/prettyCashNames/usePrettyCashNames";
import toast from "@/utilities/toast";
import { StatusFilters } from "../../../shared/StatusFilterDropdown";
import LoadingState from "@/designSystem/LoadingState";
import { useLocalTableData } from "@/hooks/table/useLocalTableData";

interface PrettyCashNamesTabProps {
   searchQuery: string;
   filters: StatusFilters;
   sortBy: string;
   onEdit: (prettyCashName: PrettyCashName) => void;
}

// Actions Cell Component
function ActionsCell({
   prettyCashName,
   onDelete,
   onEdit,
}: {
   prettyCashName: PrettyCashName;
   onDelete: (id: string) => void;
   onEdit?: (prettyCashName: PrettyCashName) => void;
}) {
   const { t } = useTranslation("settings");
   const [isOpen, setIsOpen] = useState(false);
   const buttonRef = useRef<HTMLButtonElement>(null);

   const dropdownItems: DropdownItem[] = [
      {
         id: "edit",
         label: t("prettyCashNames.actions.edit"),
         icon: Edit,
         onClick: () => {
            onEdit?.(prettyCashName);
            setIsOpen(false);
         },
         variant: "default",
      },
      {
         id: "delete",
         label: t("prettyCashNames.actions.delete"),
         icon: Trash,
         onClick: () => {
            onDelete(String(prettyCashName.id));
            setIsOpen(false);
         },
         variant: "danger",
      },
   ];

   return (
      <div className="flex justify-end">
         <button
            ref={buttonRef}
            type="button"
            aria-label={t("prettyCashNames.actions.label")}
            className={`p-1.5 transition-colors rounded-lg flex items-center justify-center w-8 h-8 ${
               isOpen
                  ? "bg-bg-weak"
                  : "bg-transparent hover:bg-bg-weak active:bg-border"
            }`}
            data-row-menu-trigger
            onClick={() => setIsOpen(!isOpen)}>
            <MoreVertical size={20} />
         </button>

         <Dropdown
            items={dropdownItems}
            isOpen={isOpen}
            onClose={() => setIsOpen(false)}
            anchorRef={buttonRef}
         />
      </div>
   );
}

function PrettyCashNamesTab({ searchQuery, filters, sortBy, onEdit }: PrettyCashNamesTabProps) {
   const { t } = useTranslation("settings");
   const [deleteModalOpen, setDeleteModalOpen] = useState(false);
   const [prettyCashNameToDelete, setPrettyCashNameToDelete] = useState<
      string | number | null
   >(null);
   const [prettyCashNamesToDelete, setPrettyCashNamesToDelete] = useState<(string | number)[]>(
      []
   );
   const [selectionResetSignal, setSelectionResetSignal] = useState(0);
   const [deleteModalState, setDeleteModalState] = useState<
      "idle" | "loading" | "success"
   >("idle");

   // Fetch pretty cash names from API
   const { data: prettyCashNamesData, isLoading } = useListPrettyCashNames();
   const deleteMutation = useDeletePrettyCashName();

   // Use local table data hook for client-side search, filtering, and sorting
   const { data: filteredPrettyCashNames } = useLocalTableData({
      data: prettyCashNamesData?.data || [],
      searchQuery,
      searchFields: ["name"],
      filters: filters.status.length ? { status: filters.status } : {},
      customFilterFn: (item, activeFilters) => {
         if (activeFilters.status && activeFilters.status.length) {
            const itemStatus = (item.status || "").toString().toLowerCase();
            const allowed = (activeFilters.status as string[]).map((s) =>
               s.toLowerCase()
            );
            if (!allowed.includes(itemStatus)) return false;
         }
         return true;
      },
      sortField: (() => {
         if (sortBy === "status_active" || sortBy === "status_inactive") {
            return "status";
         }
         if (sortBy === "newest" || sortBy === "oldest") {
            return "created_at";
         }
         return (sortBy || "name_asc").split("_")[0];
      })(),
      sortDirection: (() => {
         if (sortBy === "status_active") return "desc"; // active first
         if (sortBy === "status_inactive") return "asc"; // inactive first
         if (sortBy === "newest") return "desc";
         if (sortBy === "oldest") return "asc";
         return (sortBy || "name_asc").split("_")[1] as "asc" | "desc";
      })(),
      customSortFn: (a, b, field, direction) => {
         if (field === "status") {
            const order = sortBy === "status_inactive" ? ["inactive", "active"] : ["active", "inactive"];
            const aStatus = (a.status || "").toString().toLowerCase();
            const bStatus = (b.status || "").toString().toLowerCase();
            const aIndex = order.indexOf(aStatus);
            const bIndex = order.indexOf(bStatus);
            return aIndex - bIndex;
         }
         if (field === "created_at") {
            const aDate = a.created_at ? new Date(a.created_at).getTime() : 0;
            const bDate = b.created_at ? new Date(b.created_at).getTime() : 0;
            return direction === "asc" ? aDate - bDate : bDate - aDate;
         }
         const aVal = a[field as keyof typeof a] as any;
         const bVal = b[field as keyof typeof b] as any;
         const comparison = String(aVal ?? "").localeCompare(String(bVal ?? ""));
         return direction === "asc" ? comparison : -comparison;
      },
   });

   const handleDeleteClick = useCallback((id: string | number) => {
      setPrettyCashNameToDelete(id);
      setPrettyCashNamesToDelete([]);
      setDeleteModalOpen(true);
   }, []);

   // Bulk actions handlers
   const handleBulkDelete = useCallback((items: PrettyCashName[]) => {
      setPrettyCashNamesToDelete(items.map((item) => item.id));
      setPrettyCashNameToDelete(null);
      setDeleteModalOpen(true);
   }, []);

   const handleDeleteConfirm = useCallback(async () => {
      if (!prettyCashNameToDelete && prettyCashNamesToDelete.length === 0) return;

      setDeleteModalState("loading");
      try {
         if (prettyCashNameToDelete) {
            await deleteMutation.mutateAsync(prettyCashNameToDelete);
         } else if (prettyCashNamesToDelete.length > 0) {
            await Promise.all(
               prettyCashNamesToDelete.map((id) => deleteMutation.mutateAsync(id))
            );
         }

         toast.success(
            prettyCashNameToDelete
               ? t("prettyCashNames.toast.deleteSuccess")
               : t("prettyCashNames.toast.deleteMultipleSuccess")
         );

         setSelectionResetSignal((prev) => prev + 1);
         setDeleteModalState("success");
         setTimeout(() => {
            setDeleteModalOpen(false);
            setPrettyCashNameToDelete(null);
            setPrettyCashNamesToDelete([]);
            setDeleteModalState("idle");
         }, 600);
      } catch (error) {
         let errorMessage = t("prettyCashNames.toast.deleteError");
         if (error instanceof Error && error.message) {
            errorMessage = error.message;
         }
         toast.error(errorMessage);
         setDeleteModalState("idle");
         setDeleteModalOpen(false);
         setPrettyCashNameToDelete(null);
         setPrettyCashNamesToDelete([]);
      }
   }, [prettyCashNameToDelete, prettyCashNamesToDelete, deleteMutation, t]);

   const handleDeleteCancel = useCallback(() => {
      if (deleteModalState === "loading") return;
      setDeleteModalOpen(false);
      setPrettyCashNameToDelete(null);
      setPrettyCashNamesToDelete([]);
      setDeleteModalState("idle");
   }, [deleteModalState]);

   // Floating action bar
   const renderFloatingBar = useCallback(
      (selectedCount: number, selectedData: PrettyCashName[]) => (
         <PrettyCashNamesFloatingActionBar
            selectedCount={selectedCount}
            selectedRows={selectedData}
            onEdit={(item) => onEdit?.(item)}
            onDelete={(items) => handleBulkDelete(items)}
            resetSignal={selectionResetSignal}
         />
      ),
      [handleBulkDelete, onEdit, selectionResetSignal]
   );

   const columns: ColumnDef<PrettyCashName>[] = useMemo(
      () => [
         // Selection checkbox column
         {
            id: "select",
            header: ({ table }) => (
               <Checkbox
                  checked={table.getIsAllPageRowsSelected()}
                  onChange={(e) =>
                     table.toggleAllPageRowsSelected(e.target.checked)
                  }
                  className="m-0 mb-0.5 me-0.5"
               />
            ),
            cell: ({ row }) => (
               <Checkbox
                  checked={row.getIsSelected()}
                  onChange={(e) => row.toggleSelected(e.target.checked)}
                  className="m-0 me-0.5"
               />
            ),
            size: 20,

         },
         // Name column
         {
            accessorKey: "name",
            header: () => (
               <span className="text-sm text-text-strong">
                  {t("prettyCashNames.table.name")}
               </span>
            ),
            cell: ({ getValue }) => (
               <p className="text-sm text-text-strong truncate">
                  {getValue() as string}
               </p>
            ),

         },
         // Balance column
         {
            accessorKey: "balance",
            header: () => (
               <span className="text-sm text-text-strong">
                  {t("prettyCashNames.table.balance")}
               </span>
            ),
            cell: ({ getValue }) => (
               <p className="text-sm text-text-strong truncate">
                  {getValue() as string}
               </p>
            ),

         },
         // Status column
         {
            accessorKey: "status",
            header: () => (
               <span className="text-sm text-text-strong">
                  {t("prettyCashNames.table.status")}
               </span>
            ),
            cell: ({ getValue, row }) => {
               const status = row.original.status || getValue();
               // Normalize status to lowercase for translation key
               const normalizedStatus = typeof status === "string" ? status.toLowerCase() : "inactive";
               const displayStatus = normalizedStatus === "active" ? "active" : normalizedStatus === "inactive" ? "inactive" : "fullyPaid";
               return (
                  <StatusTag
                     label={t(`prettyCashNames.status.${displayStatus}`)}
                     variant={displayStatus === "fullyPaid" ? "active" : displayStatus}
                     className="border-border border flex items-center justify-center ps-1! pe-2! py-0.5!"
                  />
               );
            },

         },
         // Actions column
         {
            id: "actions",
            header: () => <div />,
            cell: ({ row }) => (
               <ActionsCell
                  prettyCashName={row.original}
                  onDelete={handleDeleteClick}
                  onEdit={onEdit}
               />
            ),
            size: 64,
         },
      ],
      [t, handleDeleteClick, onEdit]
   );

   // Show loader while fetching data (after all hooks)
   if (isLoading) {
      return (
         <div className="w-full">
            <LoadingState size="medium" label={t("prettyCashNames.loading")} />
         </div>
      );
   }

   return (
      <>
            <DataTable
               data={filteredPrettyCashNames as PrettyCashName[]}
               columns={columns}
               enableRowSelection
               renderFloatingBar={renderFloatingBar}
               resetSelectionSignal={selectionResetSignal}
            />
         <DeletePrettyCashNameModal
            isOpen={deleteModalOpen}
            onClose={handleDeleteCancel}
            onConfirm={handleDeleteConfirm}
            isLoading={deleteModalState === "loading"}
            isSuccess={deleteModalState === "success"}
         />
      </>
   );
}

export default PrettyCashNamesTab;

/** @format */

import { useMemo, useState, useRef, useCallback } from "react";
import { ColumnDef } from "@tanstack/react-table";
import { DataTable } from "@/designSystem/ui/data-table";
import { useTranslation } from "@/hooks/useTranslation";
import Checkbox from "@/designSystem/Checkbox";
import StatusTag from "@/designSystem/StatusTag";
import Dropdown, { DropdownItem } from "@/designSystem/Dropdown";
import { MoreVertical, Edit, Trash } from "@/Icons";
import DeleteCategoryModal from "../../modals/DeleteCategoryModal";
import CategoriesFloatingActionBar from "./CategoriesFloatingActionBar";
import LoadingState from "@/designSystem/LoadingState";
import { CategoriesFilters } from "./CategoriesFilterDropdown";
import { useDeleteCategory, useListCategories } from "@/hooks/categories/useCategory";
import { Category } from "@/services/categoryService";
import toast from "@/utilities/toast";
import { useLocalTableData } from "@/hooks/table/useLocalTableData";

interface CategoriesTabProps {
   searchQuery: string;
   filters: CategoriesFilters;
   sortBy: string;
   onEdit: (category: Category) => void;
}

// Actions Cell Component
function ActionsCell({
   category,
   onDelete,
   onEdit,
}: {
   category: Category;
   onDelete: (cat: Category) => void;
   onEdit: (cat: Category) => void;
}) {
   const { t } = useTranslation("settings");
   const [isOpen, setIsOpen] = useState(false);
   const buttonRef = useRef<HTMLButtonElement>(null);

   const dropdownItems: DropdownItem[] = [
      {
         id: "edit",
         label: t("serviceCatalog.floatingBar.editCategory"),
         icon: Edit,
         onClick: () => {
            onEdit(category);
            setIsOpen(false);
         },
         variant: "default",
      },
      {
         id: "delete",
         label: t("serviceCatalog.floatingBar.deleteCategory"),
         icon: Trash,
         onClick: () => {
            onDelete(category);
            setIsOpen(false);
         },
         variant: "danger",
      },
   ];

   return (
      <div className="flex justify-end">
         <button
            ref={buttonRef}
            type="button"
            aria-label={t("serviceCatalog.actions.more")}
            className={`p-1.5 transition-colors rounded-lg flex items-center justify-center w-8 h-8 ${
               isOpen
                  ? "bg-bg-weak"
                  : "bg-transparent hover:bg-bg-weak active:bg-border"
            }`}
            data-row-menu-trigger
            onClick={() => setIsOpen(!isOpen)}>
            <MoreVertical size={20} />
         </button>

         <Dropdown
            items={dropdownItems}
            isOpen={isOpen}
            onClose={() => setIsOpen(false)}
            anchorRef={buttonRef}
         />
      </div>
   );
}

function CategoriesTab({ searchQuery, filters, sortBy, onEdit }: CategoriesTabProps) {
   const { t } = useTranslation("settings");
   const [categoryToDelete, setCategoryToDelete] = useState<Category | null>(
      null
   );
   const [categoriesToDelete, setCategoriesToDelete] = useState<
      Category[] | null
   >(null);
   const [deleteButtonState, setDeleteButtonState] = useState<
      "idle" | "loading" | "success"
   >("idle");
   const [bulkDeleteButtonState, setBulkDeleteButtonState] = useState<
      "idle" | "loading" | "success"
   >("idle");
   const [selectionResetSignal, setSelectionResetSignal] = useState(0);

   // Map UI sort options to backend column/order
   const sortConfig: Record<string, { field: string; order: "asc" | "desc" }> =
      {
         nameAsc: { field: "nameEn", order: "asc" },
         nameDesc: { field: "nameEn", order: "desc" },
         newest: { field: "created_at", order: "desc" },
         oldest: { field: "created_at", order: "asc" },
      };
   const { field: sortField, order: sortOrder } =
      sortConfig[sortBy] || sortConfig.newest;

   // Fetch all categories; filter/sort client-side
   const { data: categoriesResponse, isLoading, error } = useListCategories(
      undefined,
      { enabled: true }
   );

   const { data: categories } = useLocalTableData({
      data: categoriesResponse?.data || [],
      searchQuery,
      searchFields: ["code", "nameEn", "nameAr", "departmentNameEn", "departmentNameAr"],
      filters: filters.status.length ? { status: filters.status } : {},
      customFilterFn: (item, activeFilters) => {
         if (activeFilters.status && activeFilters.status.length) {
            const itemStatus = (item.status || "").toString().toLowerCase();
            const allowed = (activeFilters.status as string[]).map((s) =>
               s.toLowerCase()
            );
            if (!allowed.includes(itemStatus)) return false;
         }
         return true;
      },
      sortField,
      sortDirection: sortOrder,
      customSortFn: (a, b, field, direction) => {
         if (field === "created_at") {
            const aDate = a.created_at ? new Date(a.created_at).getTime() : 0;
            const bDate = b.created_at ? new Date(b.created_at).getTime() : 0;
            return direction === "asc" ? aDate - bDate : bDate - aDate;
         }
         const aVal = a[field as keyof typeof a] as any;
         const bVal = b[field as keyof typeof b] as any;
         const comparison = String(aVal ?? "").localeCompare(String(bVal ?? ""));
         return direction === "asc" ? comparison : -comparison;
      },
   });

   const deleteMutation = useDeleteCategory();

   // Bulk actions handlers
   const handleBulkDelete = useCallback((categories: Category[]) => {
      setCategoriesToDelete(categories);
   }, []);

   const handleEditCategory = useCallback(
      (category: Category) => {
         onEdit(category);
      },
      [onEdit]
   );

   // Floating action bar
   const renderFloatingBar = useCallback(
      (selectedCount: number, selectedRows: Category[]) => (
         <CategoriesFloatingActionBar
            selectedCount={selectedCount}
            selectedRows={selectedRows}
            onDelete={handleBulkDelete}
            onEdit={handleEditCategory}
            resetSignal={selectionResetSignal}
         />
      ),
      [handleBulkDelete, handleEditCategory, selectionResetSignal]
   );

   const columns: ColumnDef<Category>[] = useMemo(
      () => [
         // Selection checkbox column
         {
            id: "select",
            header: ({ table }) => (
               <Checkbox
                  checked={table.getIsAllPageRowsSelected()}
                  onChange={(e) =>
                     table.toggleAllPageRowsSelected(e.target.checked)
                  }
                  className="m-0 mb-0.5 me-0.5"
               />
            ),
            cell: ({ row }) => {
               const category = row.original;
               const hasDependencies = (category.servicesCount ?? 0) > 0;

               const services = category.servicesCount ?? 0;
               const dependenciesText = `${services} ${services === 1 ? t("serviceCatalog.dependency.service") : t("serviceCatalog.dependency.services")}`;

               return (
                  <div
                     className="relative group"
                     title={
                        hasDependencies
                           ? `${t("serviceCatalog.dependency.cannotDelete")}: ${dependenciesText}`
                           : undefined
                     }>
                     <Checkbox
                        checked={row.getIsSelected()}
                        onChange={(e) => row.toggleSelected(e.target.checked)}
                        className="m-0 me-0.5"
                     />
                  </div>
               );
            },
            size: 20,

         },
         // Category ID column
         {
            accessorKey: "code",
            header: () => (
               <span className="text-sm text-text-strong">
                  {t("serviceCatalog.table.categoryId")}
               </span>
            ),
            cell: ({ row }) => {
               const { departmentNameEn, department } = row.original as Category & {
                  department?: { department_name_en?: string; department_name_ar?: string };
               };
               const name =
                  departmentNameEn ||
                  department?.department_name_en ||
                  department?.department_name_ar ||
                  t("serviceCatalog.table.departmentPlaceholder");

               return <p className="text-sm text-text-strong">{name}</p>;
            },
            size: 148,

         },
         // Category Name (EN) column
         {
            accessorKey: "nameEn",
            header: () => (
               <span className="text-sm text-text-strong">
                  {t("serviceCatalog.table.categoryNameEn")}
               </span>
            ),
            cell: ({ getValue }) => (
               <p className="text-sm text-text-strong">
                  {getValue() as string}
               </p>
            ),
            size: 300,

         },
         // Department column
         // Department column
         {
            accessorKey: "departmentNameEn",
            header: () => (
               <span className="text-sm text-text-strong">
                  {t("serviceCatalog.table.department")}
               </span>
            ),
            cell: ({ row }) => {
               const category = row.original as Category & {
                  department?: { department_name_en?: string; department_name_ar?: string };
               };

               const departmentLabel =
                  category.departmentNameEn ||
                  category.department?.department_name_en ||
                  category.departmentNameAr ||
                  category.department?.department_name_ar ||
                  "-";

               return (
                  <p className="text-sm text-text-strong">{departmentLabel}</p>
               );
            },
            size: 300,

         },
         // Status column
         {
            accessorKey: "status",
            header: () => (
               <span className="text-sm text-text-strong">
                  {t("serviceCatalog.table.status")}
               </span>
            ),
            cell: ({ getValue }) => {
               const statusValue = getValue() as string;
               // Convert backend format (Active/Inactive) to frontend format (active/inactive)
               const status = (statusValue?.toLowerCase() || "inactive") as
                  | "active"
                  | "inactive";
               return (
                  <StatusTag
                     label={t(`serviceCatalog.status.${status}`)}
                     variant={status}
                     className="border-border border flex items-center justify-center ps-1! pe-2! py-0.5!"
                  />
               );
            },
            size: 230,

         },
         // Actions column
         {
            id: "actions",
            header: () => <div />,
            cell: ({ row }) => (
               <ActionsCell
                  category={row.original}
                  onDelete={setCategoryToDelete}
                  onEdit={handleEditCategory}
               />
            ),
            size: 64,
         },
      ],
      [t, handleEditCategory]
   );

   return (
      <>
         {isLoading ? (
            <LoadingState
               size="medium"
               label={t("serviceCatalog.categories.loading")}
               minHeight="16rem"
            />
         ) : error ? (
            <div className="flex items-center justify-center h-64 text-danger">
               Error loading categories: {error.message}
            </div>
         ) : (
            <DataTable
               columns={columns}
               data={categories as Category[]}
               enableRowSelection={true}
               showPagination={true}
               pageSize={7}
               globalFilter={searchQuery}
               translationNamespace="settings"
               renderFloatingBar={renderFloatingBar}
               resetSelectionSignal={selectionResetSignal}
            />
         )}
         <DeleteCategoryModal
            isOpen={!!categoryToDelete}
            onClose={() => {
               if (deleteButtonState !== "loading") {
                  setCategoryToDelete(null);
                  setDeleteButtonState("idle");
               }
            }}
            onConfirm={() => {
               if (categoryToDelete?.id) {
                  setDeleteButtonState("loading");
                  deleteMutation.mutate(categoryToDelete.id, {
                     onSuccess: () => {
                        setDeleteButtonState("success");
                        toast.success(
                           `${t("serviceCatalog.modal.deleteCategorySuccess")} (ID: ${categoryToDelete.code})`
                        );
                        setTimeout(() => {
                           setCategoryToDelete(null);
                           setDeleteButtonState("idle");
                           setSelectionResetSignal((prev) => prev + 1);
                        }, 600);
                     },
                     onError: (error: unknown) => {
                        setDeleteButtonState("idle");
                        setCategoryToDelete(null);

                        let errorMessage = t("serviceCatalog.modal.deleteCategoryError");

                        // Check if it's an Axios error with response data
                        if (
                           error &&
                           typeof error === "object" &&
                           "response" in error &&
                           error.response &&
                           typeof error.response === "object" &&
                           "data" in error.response
                        ) {
                           const responseData = (error.response as { data: unknown }).data;
                           if (
                              responseData &&
                              typeof responseData === "object" &&
                              "message" in responseData
                           ) {
                              errorMessage = (responseData as { message: string }).message;
                           }
                        } else if (error && typeof error === "object" && "message" in error) {
                           errorMessage = (error as { message: string }).message;
                        } else if (error instanceof Error) {
                           errorMessage = error.message;
                        }

                        toast.error(errorMessage);
                     },
                  });
               }
            }}
            isLoading={deleteButtonState === "loading"}
            isSuccess={deleteButtonState === "success"}
         />
         <DeleteCategoryModal
            isOpen={!!categoriesToDelete}
            onClose={() => {
               if (bulkDeleteButtonState !== "loading") {
                  setCategoriesToDelete(null);
                  setBulkDeleteButtonState("idle");
               }
            }}
            onConfirm={async () => {
               if (categoriesToDelete && categoriesToDelete.length > 0) {
                  setBulkDeleteButtonState("loading");

                  try {
                     // Delete all categories sequentially
                     for (const cat of categoriesToDelete) {
                        await new Promise<void>((resolve, reject) => {
                           deleteMutation.mutate(cat.id, {
                              onSuccess: () => {
                                 toast.success(
                                    `${t("serviceCatalog.modal.deleteCategorySuccess")} (ID: ${cat.code})`
                                 );
                                 resolve();
                              },
                              onError: (error) => reject(error),
                           });
                        });
                     }

                     setBulkDeleteButtonState("success");
                     setTimeout(() => {
                        setCategoriesToDelete(null);
                        setBulkDeleteButtonState("idle");
                        setSelectionResetSignal((prev) => prev + 1);
                     }, 600);
                  } catch (err) {
                     setBulkDeleteButtonState("idle");
                     setCategoriesToDelete(null);

                     let errorMessage = t("serviceCatalog.modal.deleteCategoryError");

                     // Check if it's an Axios error with response data
                     if (
                        err &&
                        typeof err === "object" &&
                        "response" in err &&
                        err.response &&
                        typeof err.response === "object" &&
                        "data" in err.response
                     ) {
                        const responseData = (err.response as { data: unknown }).data;
                        if (
                           responseData &&
                           typeof responseData === "object" &&
                           "message" in responseData
                        ) {
                           errorMessage = (responseData as { message: string }).message;
                        }
                     } else if (err && typeof err === "object" && "message" in err) {
                        errorMessage = (err as { message: string }).message;
                     } else if (err instanceof Error) {
                        errorMessage = err.message;
                     }

                     toast.error(errorMessage);
                  }
               }
            }}
            isLoading={bulkDeleteButtonState === "loading"}
            isSuccess={bulkDeleteButtonState === "success"}
         />
      </>
   );
}

export default CategoriesTab;

