                     @page { margin: 0.5in; }
                  }
               </style>
            </head>
            <body>${voucherContent}</body>
         </html>
      `);

      printWindow.document.close();
      printWindow.focus();
      setTimeout(() => {
         printWindow.print();
         printWindow.close();
      }, 250);
