import { MouseEvent, useEffect, useRef, useState } from "react";
import {
   useReactTable,
   getCoreRowModel,
   getPaginationRowModel,
   getSortedRowModel,
   getFilteredRowModel,
   ColumnDef,
   flexRender,
   SortingState,
   ColumnFiltersState,
   RowSelectionState,
   Table as TanStackTable,
} from "@tanstack/react-table";
import {
   TableBody,
   TableCell,
   TableHead,
   TableHeader,
   TableRow,
} from "@/designSystem/ui/table";
import { useTranslation } from "@/hooks/useTranslation";
import { cn } from "@/utilities/index";
import type { Namespace } from "@/config/i18n";
import Dropdown from "@/designSystem/Dropdown";
import { ArrowDownSLine, Dot } from "@/Icons";
import Loader from "@/designSystem/Loader";

export interface DataTableProps<TData, TValue> {
   columns: ColumnDef<TData, TValue>[];
   data: TData[];
   pageSize?: number;
   globalFilter?: string;
   onRowSelectionChange?: (selectedRows: TData[]) => void;
   enableRowSelection?: boolean;
   showPagination?: boolean;
   className?: string;
   translationNamespace?: Namespace;
   renderFloatingBar?: (
      selectedCount: number,
      selectedRows: TData[]
   ) => React.ReactNode;
   onRowClick?: (row: TData) => void;
   pagination?: {
      pageIndex: number;
      pageSize: number;
   };
   onPaginationChange?: (updater: any) => void;
   manualPagination?: boolean;
   pageCount?: number;
   resetSelectionSignal?: number;
   isLoading?: boolean;
}

interface DataTablePaginationProps<TData> {
   table: TanStackTable<TData>;
   translationNamespace?: Namespace;
}

function DataTablePagination<TData>({
   table,
   translationNamespace = "common",
}: DataTablePaginationProps<TData>) {
   const { t } = useTranslation(translationNamespace);
   const currentPage = table.getState().pagination.pageIndex + 1;
   const totalPages = table.getPageCount();
   const pageSizeOptions = [10, 20, 50, 100];
   const [isPageSizeDropdownOpen, setIsPageSizeDropdownOpen] =
      useState(false);
   const pageSizeButtonRef = useRef<HTMLButtonElement>(null);

   const pageSizeLabel = `${table.getState().pagination.pageSize} ${
      t("pagination.perPage")
   }`;

   const pageSizeItems = pageSizeOptions.map((pageSize) => ({
      id: String(pageSize),
      label: `${pageSize} ${t("pagination.perPage")}`,
      icon: Dot,
      onClick: () => {
         table.setPageSize(pageSize);
         setIsPageSizeDropdownOpen(false);
      },
   }));

   return (
      <div className="flex flex-wrap items-center justify-between gap-3 md:gap-4 xl:gap-4 px-3 md:px-4 xl:px-4 py-3 md:py-4 xl:py-4 border border-border border-t-0 rounded-b-lg">
         <div className="text-sm text-text-sub">
            {t("pagination.page")} {currentPage} {t("pagination.of")}{" "}
            {totalPages}
         </div>

         <div className="flex items-center gap-2">
            <button
               onClick={() => table.setPageIndex(0)}
               disabled={!table.getCanPreviousPage()}
               className="px-2 py-1 text-sm text-text-sub hover:bg-bg-weak rounded disabled:opacity-50 disabled:cursor-not-allowed transition-colors">
               «
            </button>
            <button
               onClick={() => table.previousPage()}
               disabled={!table.getCanPreviousPage()}
               className="px-2 py-1 text-sm text-text-sub hover:bg-bg-weak rounded disabled:opacity-50 disabled:cursor-not-allowed transition-colors">
               ‹
            </button>

            {Array.from({ length: totalPages }, (_, i) => i).map(
               (pageIndex) => {
                  if (
                     pageIndex === 0 ||
                     pageIndex === totalPages - 1 ||
                     (pageIndex >= currentPage - 2 && pageIndex <= currentPage)
                  ) {
                     return (
                        <button
                           key={pageIndex}
                           onClick={() => table.setPageIndex(pageIndex)}
                           className={`px-3 py-1 text-sm rounded ${
                              pageIndex === currentPage - 1
                                 ? "bg-primary text-text-main"
                                 : "text-text-sub hover:bg-bg-weak"
                           }`}>
                           {pageIndex + 1}
                        </button>
                     );
                  } else if (
                     pageIndex === currentPage - 3 ||
                     pageIndex === currentPage + 1
                  ) {
                     return (
                        <span key={pageIndex} className="px-2 text-text-sub">
                           ...
                        </span>
                     );
                  }
                  return null;
               }
            )}

            <button
               onClick={() => table.nextPage()}
               disabled={!table.getCanNextPage()}
               className="px-2 py-1 text-sm text-text-sub hover:bg-bg-weak rounded disabled:opacity-50 disabled:cursor-not-allowed transition-colors">
               ›
            </button>
            <button
               onClick={() => table.setPageIndex(totalPages - 1)}
               disabled={!table.getCanNextPage()}
               className="px-2 py-1 text-sm text-text-sub hover:bg-bg-weak rounded disabled:opacity-50 disabled:cursor-not-allowed transition-colors">
               »
            </button>
         </div>

         <div className="flex items-center gap-2">
            <span className="text-sm text-text-sub hidden sm:inline">
               {t("pagination.rowsPerPage")}
            </span>
            <button
               ref={pageSizeButtonRef}
               onClick={() =>
                  setIsPageSizeDropdownOpen((prev) => !prev)
               }
               className="inline-flex items-center gap-2 px-3 py-1 text-sm text-text-sub border border-border rounded-lg bg-background hover:bg-bg-weak transition-colors">
               <span>{pageSizeLabel}</span>
               <ArrowDownSLine size={14} className="fill-current" />
            </button>
            <Dropdown
               isOpen={isPageSizeDropdownOpen}
               onClose={() => setIsPageSizeDropdownOpen(false)}
               anchorRef={pageSizeButtonRef}
               items={pageSizeItems}
               zIndex="z-50"
            />
         </div>
      </div>
   );
}

export function DataTable<TData, TValue>({
   columns,
   data,
   pageSize = 10,
   globalFilter = "",
   onRowSelectionChange,
   enableRowSelection = false,
   showPagination = true,
   className,
   translationNamespace = "common",
   renderFloatingBar,
   onRowClick,
   resetSelectionSignal,
   manualPagination,
   pageCount,
   pagination,
   onPaginationChange,
   isLoading = false,
}: DataTableProps<TData, TValue>) {
   const { t } = useTranslation(translationNamespace);
   const [sorting, setSorting] = useState<SortingState>([]);
   const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([]);
   const [rowSelection, setRowSelection] = useState<RowSelectionState>({});

   useEffect(() => {
      if (resetSelectionSignal !== undefined) {
         setRowSelection({});
      }
   }, [resetSelectionSignal]);

   const table = useReactTable({
      data,
      columns,
      state: {
         sorting,
         columnFilters,
         rowSelection,
         globalFilter,
         ...(pagination && { pagination }),
      },
      manualPagination,
      pageCount,
      onPaginationChange,
      enableRowSelection,
      onRowSelectionChange: (updater) => {
         setRowSelection(updater);
         if (onRowSelectionChange) {
            const newSelection =
               typeof updater === "function" ? updater(rowSelection) : updater;
            const selectedRows = Object.keys(newSelection)
               .filter((key) => newSelection[key])
               .map((key) => data[parseInt(key)]);
            onRowSelectionChange(selectedRows);
         }
      },
      onSortingChange: setSorting,
      onColumnFiltersChange: setColumnFilters,
      getCoreRowModel: getCoreRowModel(),
      getSortedRowModel: getSortedRowModel(),
      getFilteredRowModel: getFilteredRowModel(),
      ...(manualPagination ? {} : { getPaginationRowModel: getPaginationRowModel() }),
      globalFilterFn: "includesString",
      autoResetPageIndex: false, // Prevent auto-reset which causes infinite loops
      initialState: {
         pagination: {
            pageSize,
         },
      },
   });

   const handleRowClick = (
      event: MouseEvent<HTMLTableRowElement>,
      rowData: TData
   ) => {
      const target = event.target as HTMLElement | null;

      // Avoid triggering row actions when interacting with buttons/inputs/links inside the row
      if (
         target?.closest(
            "button, a, input, textarea, select, option, [data-row-click-ignore]"
         )
      ) {
         return;
      }

      if (onRowClick) {
         onRowClick(rowData);
         return;
      }

      // No preview handler, try to open the row action menu if it exists
      const menuTrigger =
         event.currentTarget.querySelector<HTMLElement>(
            "[data-row-menu-trigger]"
         );

      if (menuTrigger) {
