                              </TableHead>
                           ))}
                        </TableRow>
                     ))}
                  </TableHeader>
                     <TableBody className="bg-background">
                     {isLoading ? (
                        <TableRow>
                           <TableCell
                              colSpan={columns.length}
                              className="h-24 text-center">
                              <div className="flex justify-center items-center py-8">
                                 <Loader label={t("common:loading")} />
                              </div>
                           </TableCell>
                        </TableRow>
                     ) : table.getRowModel().rows.length ? (
                        table.getRowModel().rows.map((row) => (
                           <TableRow
                              key={row.id}
                              data-state={row.getIsSelected() && "selected"}
                              className={cn(
                                 "border-b border-border last:border-b-0",
                                 onRowClick &&
                                    "cursor-pointer hover:bg-bg-weak transition-colors"
                              )}
                              onClick={(event) =>
                                 handleRowClick(event, row.original)
                              }>
                              {row.getVisibleCells().map((cell) => (
                                 <TableCell
                                    key={cell.id}
                                    className={cn(
                                       "px-3 md:px-4 xl:px-4 py-2 md:py-2.5 xl:py-2.5",
                                       cell.column.id === "select" &&
                                          "ps-3! pe-3!",
                                       cell.column.id === "name" &&
                                          "pe-3! px-0!"
                                    )}
                                    style={{ width: cell.column.getSize() }}>
                                    {flexRender(
                                       cell.column.columnDef.cell,
                                       cell.getContext()
                                    )}
                                 </TableCell>
                              ))}
                           </TableRow>
                        ))
                     ) : (
                        <TableRow>
                           <TableCell
                              colSpan={columns.length}
                              className="h-24 text-center text-text-sub">
                              {t("table.noResults")}
                           </TableCell>
                        </TableRow>
                     )}
                  </TableBody>
               </table>
            </div>
            {renderFloatingBar &&
               renderFloatingBar(
                  Object.keys(rowSelection).filter((key) => rowSelection[key])
                     .length,
                  Object.keys(rowSelection)
                     .filter((key) => rowSelection[key])
                     .map((key) => data[parseInt(key)])
               )}
         </div>
         </div>
         {showPagination && (
            <DataTablePagination table={table} translationNamespace="common" />
         )}
      </div>
   );
}

