/** @format */

import { useMemo } from "react";

interface UseLocalTableDataOptions<T, TSort extends string = string> {
	data: T[];
	searchQuery?: string;
	searchFields?: (keyof T)[];
	sortField?: TSort;
	sortDirection?: "asc" | "desc";
	filters?: Record<string, any>;
	customFilterFn?: (item: T, filters: Record<string, any>) => boolean;
	customSortFn?: (a: T, b: T, field: TSort, direction: "asc" | "desc") => number;
}

/**
 * Hook for processing table data locally (client-side)
 * Use for tables with <1000 rows for instant sorting/filtering
 */
export function useLocalTableData<T, TSort extends string = string>({
	data,
	searchQuery = "",
	searchFields = [],
	sortField,
	sortDirection = "asc",
	filters = {},
	customFilterFn,
	customSortFn,
}: UseLocalTableDataOptions<T, TSort>) {
	const processedData = useMemo(() => {
		let result = [...data];

		// 1. Apply search
		if (searchQuery && searchFields.length > 0) {
			const query = searchQuery.toLowerCase().trim();
			result = result.filter((item) =>
				searchFields.some((field) => {
					const value = item[field];
					if (value === null || value === undefined) return false;
					return String(value).toLowerCase().includes(query);
				})
			);
		}

		// 2. Apply filters
		if (Object.keys(filters).length > 0) {
			result = result.filter((item) => {
				if (customFilterFn) {
					return customFilterFn(item, filters);
				}
				// Default filter logic - exact match
				return Object.entries(filters).every(([key, value]) => {
					if (value === undefined || value === null) return true;

					const itemValue = item[key as keyof T];

					// Handle array filters (e.g., status in ['active', 'pending'])
					if (Array.isArray(value)) {
						return value.includes(itemValue);
					}

					return itemValue === value;
				});
			});
		}

		// 3. Apply sorting
		if (sortField) {
			result.sort((a, b) => {
				if (customSortFn) {
					return customSortFn(a, b, sortField, sortDirection);
				}

				const aVal = a[sortField as unknown as keyof T];
				const bVal = b[sortField as unknown as keyof T];

				// Handle null/undefined
				if (aVal === null || aVal === undefined) return 1;
				if (bVal === null || bVal === undefined) return -1;
				if (aVal === bVal) return 0;

				// Type-aware comparison
				if (typeof aVal === "number" && typeof bVal === "number") {
					return sortDirection === "asc" ? aVal - bVal : bVal - aVal;
				}

				if (aVal instanceof Date && bVal instanceof Date) {
					return sortDirection === "asc"
						? aVal.getTime() - bVal.getTime()
						: bVal.getTime() - aVal.getTime();
				}

				// String comparison
				const comparison = String(aVal).localeCompare(String(bVal));
				return sortDirection === "asc" ? comparison : -comparison;
			});
		}

		return result;
	}, [
		data,
		searchQuery,
		searchFields,
		sortField,
		sortDirection,
		filters,
		customFilterFn,
		customSortFn,
	]);

	return {
		data: processedData,
		totalCount: data.length,
		filteredCount: processedData.length,
		isFiltered: processedData.length !== data.length,
	};
}

/** @format */

import { useState, useCallback } from "react";

interface UseTableFilterOptions<T> {
	initialFilters?: Partial<T>;
	onFilterChange?: (filters: Partial<T>) => void;
}

export function useTableFilter<T extends Record<string, any>>(
	options?: UseTableFilterOptions<T>
) {
	const [filters, setFilters] = useState<Partial<T>>(
		options?.initialFilters || {}
	);

	const updateFilter = useCallback(
		(key: keyof T, value: T[keyof T] | undefined) => {
			setFilters((prev) => {
				const newFilters = { ...prev };
				if (
					value === undefined ||
					value === null ||
					value === "" ||
					(Array.isArray(value) && value.length === 0)
				) {
					delete newFilters[key];
				} else {
					newFilters[key] = value;
				}
				options?.onFilterChange?.(newFilters);
				return newFilters;
			});
		},
		[options]
	);

	const updateFilters = useCallback(
		(newFilters: Partial<T>) => {
			setFilters(newFilters);
			options?.onFilterChange?.(newFilters);
		},
		[options]
	);

	const clearFilters = useCallback(() => {
		setFilters({});
		options?.onFilterChange?.({});
	}, [options]);

	const hasActiveFilters = Object.keys(filters).length > 0;

	return {
		filters,
		updateFilter,
		updateFilters,
		clearFilters,
		setFilters,
		hasActiveFilters,
	};
}

import { useCallback, useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import {
	enqueueTestPush,
	ensureWebPushRegistered,
	getLastWebPushToken,
	getOrCreateWebPushDeviceId,
	isWebPushSupported,
	revokeWebPush,
} from "@/services/push/webPush";
import { getLoginStatus } from "@/config/axios";

type PushUiStatus = {
	supported: boolean;
	loggedIn: boolean;
	permission: NotificationPermission | "unsupported";
	deviceId: string;
};

export function usePushNotifications() {
	const notificationToastOptions = useMemo(
		() => ({ position: "top-center" as const }),
		[]
	);
	const [supported, setSupported] = useState(false);
	const [permission, setPermission] = useState<NotificationPermission | "unsupported">(
		"unsupported"
	);
	const [busy, setBusy] = useState(false);

	const deviceId = useMemo(() => getOrCreateWebPushDeviceId(), []);
	const loggedIn = getLoginStatus();
	const lastToken = useMemo(() => getLastWebPushToken(), []);

	const refresh = useCallback(async () => {
		const ok = await isWebPushSupported();
		setSupported(ok);
		setPermission(ok ? Notification.permission : "unsupported");
	}, []);

	useEffect(() => {
		void refresh();
	}, [refresh, notificationToastOptions]);

	const status: PushUiStatus = {
		supported,
		loggedIn,
		permission,
		deviceId,
	};

	const enable = useCallback(async () => {
		setBusy(true);
		try {
			const result = await ensureWebPushRegistered({ promptPermission: true });
			if (!result.ok) {
				if (result.reason === "not_logged_in") {
					toast.error("Login required to enable notifications", notificationToastOptions);
					return;
				}
				if (result.reason === "permission_denied") {
					toast.error("Notification permission denied", notificationToastOptions);
					return;
				}
				if (result.reason === "unsupported") {
					toast.error("Push notifications not supported in this browser/origin", notificationToastOptions);
					return;
				}
				toast.error("Failed to enable notifications", notificationToastOptions);
				return;
			}

			if (result.backendRegistered) {
				toast.success("Notifications enabled", notificationToastOptions);
			} else {
				toast(
					`Permission granted, but backend registration failed${
						result.backendError ? `: ${result.backendError}` : ""
					}`,
					notificationToastOptions
				);
			}
		} catch (e: any) {
			toast.error(e?.message || "Failed to enable notifications", notificationToastOptions);
		} finally {
			await refresh();
			setBusy(false);
		}
	}, [refresh, notificationToastOptions]);

	const disable = useCallback(async () => {
		setBusy(true);
		try {
			await revokeWebPush();
			toast("Notifications disabled (device revoked)", notificationToastOptions);
		} catch (e: any) {
			toast.error(e?.message || "Failed to disable notifications", notificationToastOptions);
		} finally {
			await refresh();
			setBusy(false);
		}
	}, [refresh, notificationToastOptions]);

	const sendTest = useCallback(async () => {
		setBusy(true);
		try {
			await enqueueTestPush();
			toast.success("Test push queued", notificationToastOptions);
		} catch (e: any) {
			toast.error(
				e?.response?.data?.message ||
					e?.response?.data?.error ||
					e?.message ||
					"Failed to send test push",
				notificationToastOptions
			);
		} finally {
			setBusy(false);
		}
	}, [notificationToastOptions]);

	return { status, busy, refresh, enable, disable, sendTest, lastToken };
}

