// Types
// Backend uses: Draft, Pending, Partially_Paid, Fully_Paid, Cancelled, Refunded, Gov_Paid
export type InvoiceStatus =
	| "Draft"
	| "Pending"
	| "Partially_Paid"
	| "Fully_Paid"
	| "Cancelled"
	| "Refunded"
	| "Gov_Paid";

export interface InvoiceItem {
	id?: string | number;
	item_id?: string | number;
	invoice_id?: string | number;
	service_id?: string | number;
	service_name?: string;
	service_code?: string | null;
	application_number?: string;
	applicant_name?: string;
	description?: string;
	quantity: number;
	unit_price: number;
	government_fee?: number;
	service_charge?: number;
	fine_amount?: number;
	discount_type?: "Percentage" | "Fixed";
	discount_value?: number;
	discount_amount?: number;
	discount?: number; // Legacy field
	tax_rate?: number;
	tax_amount?: number;
	tax?: number; // Legacy field
	subtotal?: number;
	total: number;
	assigned_employee?: {
		employee_id: string | number;
		name?: string;
	} | null;
	assigned_employee_id?: string | number | null;
	notes?: string | null;
	sort_order?: number;
	created_at?: string;
	updated_at?: string;
}

export interface Invoice {
	invoice_id: string | number;
	invoice_code: string;
	token?: string;
	invoice_type?: string;
	invoice_date: string;
	due_date?: string;
	customer: {
		customer_id: string | number;
		customer_name: string;
		customer_trn?: string;
		customer_contact?: string;
		customer_address?: string;
	};
	agent: {
		agent_id: string | number;
		agent_name?: string;
	};
	status: InvoiceStatus;
	subtotal?: number;
	total_discount?: number;
	discount?: number; // Legacy field
	total_tax?: number;
	tax?: number; // Legacy field
	total_amount: number;
	amount_paid: number;
	balance_due: number;
	payment_type?: string | null;
	currency?: string;
	remarks?: string;
	internal_notes?: string;
	notes?: string; // Legacy field
	items?: InvoiceItem[];
	created_by?: {
		employee_id: string | number;
		name?: string;
		first_name?: string;
		last_name?: string;
	};
	updated_by?: {
		employee_id: string | number;
		name?: string;
		first_name?: string;
		last_name?: string;
	};
