import apiClient from "@/config/axios";
import endPoints from "@/config/endPoints";

// Frontend types (camelCase)
export interface PrettyCashName {
	petty_cash_id: string | number;
	account_id: string | number;
	name: string;
	account_name: string;
	account_code?: string | null;
	currency: string;
	opening_balance: number;
	current_balance: number;
	status: "Active" | "Inactive";
	is_active: boolean;
	last_reconciled_at?: string | null;
	created_at: string;
	updated_at: string;
	// Legacy fields for backward compatibility
	id?: string | number;
	balance?: string; // Formatted balance string for display
}

export interface PrettyCashNameListResponse {
	success: boolean;
	data: PrettyCashName[];
	pagination: {
		page: string | number;
		limit: string | number;
		total: number;
		total_pages?: number;
	};
}

export interface CreatePrettyCashNameRequest {
	name: string;
	account_id: string | number;
	opening_balance: number;
	currency?: string;
	status: "Active" | "Inactive";
}

export interface UpdatePrettyCashNameRequest {
	name?: string;
	account_id?: string | number;
	opening_balance?: number;
	currency?: string;
	status?: "Active" | "Inactive";
}

// Transform backend response to frontend format
const transformPrettyCashName = (prettyCash: any): PrettyCashName => {
	// Format balance for display: "5000 AED"
	const formattedBalance = `${prettyCash.current_balance || prettyCash.opening_balance || 0} ${prettyCash.currency || "AED"}`;

	return {
		...prettyCash,
		// Add legacy fields for backward compatibility
		id: prettyCash.petty_cash_id,
		balance: formattedBalance,
		// Status is kept as backend format in the object, but we'll use lowercase for display in components
	};
};

// Service functions
export const prettyCashNameService = {
	// GET - List pretty cash names
	list: async (filters?: {
		page?: number;
		limit?: number;
		search?: string;
	}): Promise<PrettyCashNameListResponse> => {
		const response = await apiClient.get(endPoints.prettyCashNames.getAll, {
			params: filters,
		});

		// Backend returns { success: true, data: [...], pagination: {...} }
		const backendData = response.data;
		return {
			success: backendData.success,
			data: backendData.data.map(transformPrettyCashName),
			pagination: backendData.pagination,
		};
	},

	// GET - Get pretty cash name by ID
	getById: async (id: string | number): Promise<PrettyCashName> => {
		const response = await apiClient.get(endPoints.prettyCashNames.getById(id));
		// Backend returns { success: true, data: {...} } or just the pretty cash object
		const prettyCash = response.data?.data || response.data;
		return transformPrettyCashName(prettyCash);
	},

	// POST - Create pretty cash name
	create: async (payload: CreatePrettyCashNameRequest): Promise<PrettyCashName> => {
		const response = await apiClient.post(
			endPoints.prettyCashNames.create,
			payload
		);
		// Backend returns { success: true, data: {...} } or just the pretty cash object
		const prettyCash = response.data?.data || response.data;
		return transformPrettyCashName(prettyCash);
	},

	// PUT - Update pretty cash name
	update: async (
		id: string | number,
		payload: UpdatePrettyCashNameRequest
	): Promise<PrettyCashName> => {
		const response = await apiClient.put(
			endPoints.prettyCashNames.update(id),
			payload
		);
		// Backend returns { success: true, data: {...} } or just the pretty cash object
		const prettyCash = response.data?.data || response.data;
		return transformPrettyCashName(prettyCash);
	},

	// DELETE - Delete pretty cash name
	delete: async (id: string | number): Promise<void> => {
		await apiClient.delete(endPoints.prettyCashNames.delete(id));
	},
};

import { useEffect } from "react";
import { toast } from "sonner";
import { useNavigate } from "react-router-dom";
import { getLoginStatus } from "@/config/axios";
import { addNotification, markRead } from "@/services/notifications/notificationsStore";
import {
	ensureWebPushRegistered,
	listenForForegroundPushMessages,
	listenForPushNotificationClicks,
	listenForPushNotificationReceived,
	type PushClickMessage,
	type PushMessage,
} from "@/services/push/webPush";

function routeFromPayload(navigate: ReturnType<typeof useNavigate>, payload: any) {
	const url = payload?.url || payload?.href;
	if (typeof url === "string" && url) {
		window.location.assign(url);
		return;
	}

	const path = payload?.path || payload?.route;
	if (typeof path === "string" && path) {
		navigate(path);
	}
}

function handleClick(navigate: ReturnType<typeof useNavigate>, msg: PushClickMessage) {
	toast(`Notification click${msg.action ? `: ${msg.action}` : ""}`, {
		position: "top-center",
	});
	if (msg.source_event_key) markRead(String(msg.source_event_key));
	routeFromPayload(navigate, msg.payload);
}

function handleForegroundMessage(msg: PushMessage) {
	addNotification({
		title: msg.title,
		body: msg.body,
		notificationType: msg.type || null,
		sourceEventKey: msg.source_event_key || null,
		actionProtocolVersion: msg.action_protocol_version || "1",
		actions: msg.actions || [],
		payload: msg.payload || {},
		createdAt: new Date().toISOString(),
	});
	toast(`${msg.title}${msg.body ? ` — ${msg.body}` : ""}`, {
		position: "top-center",
	});
}

export default function PushNotificationsBootstrap() {
	const navigate = useNavigate();

	useEffect(() => {
		if (!getLoginStatus()) return;
		void ensureWebPushRegistered({ promptPermission: false }).catch(() => undefined);
	}, []);

	useEffect(() => {
		let unsub = () => {};
		void listenForPushNotificationClicks((msg) => handleClick(navigate, msg)).then(
			(fn) => (unsub = fn)
		).catch(() => undefined);
		return () => unsub();
	}, [navigate]);

	useEffect(() => {
		let unsub = () => {};

		const setup = async () => {
			unsub();
			unsub = () => {};

			if (!getLoginStatus()) return;
			if (typeof window === "undefined") return;
			if (!("Notification" in window)) return;
			if (Notification.permission !== "granted") return;

			unsub = await listenForForegroundPushMessages((msg) => handleForegroundMessage(msg));
		};

		void setup();

		const onRegistered = () => void setup();
		window.addEventListener("push:registered", onRegistered);

		let permStatus: PermissionStatus | null = null;
		const maybeBindPermissionsChange = async () => {
			try {
				if (!navigator.permissions?.query) return;
				permStatus = await navigator.permissions.query({
					// TS DOM doesn't always include 'notifications' in PermissionName depending on lib versions
					name: "notifications" as any,
				});
				permStatus.onchange = () => void setup();
			} catch {
				// ignore
			}
		};

		void maybeBindPermissionsChange();

		return () => {
			unsub();
			window.removeEventListener("push:registered", onRegistered);
			if (permStatus) permStatus.onchange = null;
		};
	}, []);

	useEffect(() => {
		let unsub = () => {};
		void listenForPushNotificationReceived((msg) => {
			addNotification({
				title: msg.title,
				body: msg.body,
				notificationType: msg.notification_type || null,
				sourceEventKey: msg.source_event_key || null,
				actionProtocolVersion: msg.action_protocol_version || "1",
				actions: msg.actions || [],
				payload: msg.payload || {},
				createdAt: msg.received_at,
			});
		}).then((fn) => (unsub = fn));
		return () => unsub();
	}, []);

	return null;
}

import apiClient from "@/config/axios";
import { getLoginStatus } from "@/config/axios";

export type PushAction = {
	action: string;
	title: string;
	style?: string;
	icon?: string;
};

export type PushMessage = {
	title: string;
	body: string;
	type?: string;
	source_event_key?: string;
	action_protocol_version?: string;
	actions: PushAction[];
	payload: Record<string, unknown> | null;
};

export type PushClickMessage = {
	type: "push_notification_click";
	action: string | null;
	action_protocol_version: string;
	source_event_key?: string | null;
	notification_type?: string | null;
	title?: string | null;
	body?: string | null;
	actions?: PushAction[];
	payload: Record<string, unknown>;
};

export type PushReceivedMessage = {
	type: "push_notification_received";
	title: string;
	body: string;
	notification_type: string | null;
	source_event_key: string | null;
	action_protocol_version: string;
	actions: PushAction[];
	payload: Record<string, unknown>;
	received_at: string;
};

const DEVICE_ID_KEY = "push_device_id";
const LAST_TOKEN_KEY = "push_fcm_token";

function isSecureOrigin() {
	if (typeof window === "undefined") return false;
	if (window.isSecureContext) return true;
	return window.location.hostname === "localhost";
}

function parseJsonMaybe(value: unknown) {
	if (!value || typeof value !== "string") return null;
	try {
		return JSON.parse(value);
	} catch {
		return null;
	}
}

function normalizeActions(actions: unknown): PushAction[] {
	if (!Array.isArray(actions)) return [];
	return actions
		.filter((a) => a && typeof a === "object")
		.map((a: any) => ({
			action: String(a.action || ""),
			title: String(a.title || ""),
			style: a.style ? String(a.style) : undefined,
			icon: a.icon ? String(a.icon) : undefined,
		}))
		.filter((a) => a.action && a.title)
		.slice(0, 2);
}

function getFirebaseWebConfigFromEnv() {
	const cfg = {
		apiKey: import.meta.env.VITE_FIREBASE_API_KEY,
		authDomain: import.meta.env.VITE_FIREBASE_AUTH_DOMAIN,
		projectId: import.meta.env.VITE_FIREBASE_PROJECT_ID,
		storageBucket: import.meta.env.VITE_FIREBASE_STORAGE_BUCKET,
		messagingSenderId: import.meta.env.VITE_FIREBASE_MESSAGING_SENDER_ID,
		appId: import.meta.env.VITE_FIREBASE_APP_ID,
		measurementId: import.meta.env.VITE_FIREBASE_MEASUREMENT_ID,
	};

	const missing = Object.entries(cfg)
		.filter(([, v]) => !v)
		.map(([k]) => k);

	if (missing.length > 0) {
		throw new Error(`MISSING_FIREBASE_ENV:${missing.join(",")}`);
	}

	return cfg as Required<typeof cfg>;
}

function getFirebaseVapidKeyFromEnv() {
	const vapidKey = import.meta.env.VITE_FIREBASE_VAPID_KEY;
	if (!vapidKey) throw new Error("MISSING_FIREBASE_ENV:VITE_FIREBASE_VAPID_KEY");
	return vapidKey;
}

export function getOrCreateWebPushDeviceId() {
	const existing = localStorage.getItem(DEVICE_ID_KEY);
	if (existing) return existing;

	const id =
		typeof crypto !== "undefined" && "randomUUID" in crypto
			? crypto.randomUUID()
			: `web-${Math.random().toString(16).slice(2)}-${Date.now()}`;

	localStorage.setItem(DEVICE_ID_KEY, id);
	return id;
}

export async function isWebPushSupported() {
	if (typeof window === "undefined") return false;
	if (!isSecureOrigin()) return false;
	if (!("Notification" in window)) return false;
	if (!("serviceWorker" in navigator)) return false;

	const { isSupported } = await import("firebase/messaging");
	return await isSupported();
}

export async function registerFirebaseMessagingServiceWorker() {
	return await navigator.serviceWorker.register("/firebase-messaging-sw.js", {
		scope: "/",
		type: "module",
	});
}

async function getFirebaseMessaging() {
	const { initializeApp, getApps, getApp } = await import("firebase/app");
	const { getMessaging } = await import("firebase/messaging");

	const config = getFirebaseWebConfigFromEnv();
	const app = getApps().length ? getApp() : initializeApp(config);
	return getMessaging(app);
}

function normalizeFcmPayload(payload: any): PushMessage {
	const title =
		payload?.notification?.title ||
		payload?.data?.title ||
		"Notification";
	const body = payload?.notification?.body || payload?.data?.body || "";
	const type = payload?.data?.type || undefined;
	const source_event_key =
		payload?.data?.source_event_key || payload?.data?.sourceEventKey || undefined;
	const action_protocol_version =
		payload?.data?.action_protocol_version ||
		payload?.data?.actionProtocolVersion ||
		undefined;

	const actions = normalizeActions(parseJsonMaybe(payload?.data?.actions));
	const routedPayload = (parseJsonMaybe(payload?.data?.payload) || null) as
		| Record<string, unknown>
		| null;

	return {
		title,
		body,
		type,
		source_event_key,
		action_protocol_version,
		actions,
		payload: routedPayload,
	};
}

function normalizeReceivedMessage(msg: any): PushReceivedMessage | null {
	if (!msg || msg.type !== "push_notification_received") return null;
	return {
		type: "push_notification_received",
		title: String(msg.title || "Notification"),
		body: String(msg.body || ""),
		notification_type:
			msg.notification_type != null ? String(msg.notification_type) : null,
		source_event_key: msg.source_event_key != null ? String(msg.source_event_key) : null,
		action_protocol_version: String(msg.action_protocol_version || "1"),
		actions: normalizeActions(msg.actions),
		payload:
			msg.payload && typeof msg.payload === "object"
				? (msg.payload as Record<string, unknown>)
				: {},
		received_at: String(msg.received_at || new Date().toISOString()),
	};
}

export async function listenForForegroundPushMessages(
	handler: (message: PushMessage) => void
) {
	if (!(await isWebPushSupported())) return () => {};
	const permission = Notification.permission;
	if (permission !== "granted") return () => {};

	const { onMessage } = await import("firebase/messaging");
	try {
		const messaging = await getFirebaseMessaging();
		return onMessage(messaging, (payload) => handler(normalizeFcmPayload(payload)));
	} catch {
		return () => {};
	}
}

export async function listenForPushNotificationClicks(
	handler: (msg: PushClickMessage) => void
) {
	if (typeof window === "undefined") return () => {};
	if (!("serviceWorker" in navigator)) return () => {};

	const listener = (event: MessageEvent) => {
		const msg = event?.data;
		if (!msg || msg.type !== "push_notification_click") return;

		handler({
			type: "push_notification_click",
			action: msg.action || null,
			action_protocol_version: String(msg.action_protocol_version || "1"),
			source_event_key:
				msg.source_event_key != null ? String(msg.source_event_key) : null,
			notification_type:
				msg.notification_type != null ? String(msg.notification_type) : null,
			title: msg.title != null ? String(msg.title) : null,
			body: msg.body != null ? String(msg.body) : null,
			actions: normalizeActions(msg.actions),
			payload: (msg.payload && typeof msg.payload === "object" ? msg.payload : {}) as Record<
				string,
				unknown
			>,
		});
	};

	navigator.serviceWorker.addEventListener("message", listener);

	const ready = () =>
		navigator.serviceWorker.ready
			.then((reg) => reg.active?.postMessage({ type: "push_click_ready" }))
			.catch(() => undefined);
	void ready();

	return () => navigator.serviceWorker.removeEventListener("message", listener);
}

export async function listenForPushNotificationReceived(
	handler: (msg: PushReceivedMessage) => void
) {
	if (typeof window === "undefined") return () => {};
	if (!("serviceWorker" in navigator)) return () => {};

	const listener = (event: MessageEvent) => {
		const normalized = normalizeReceivedMessage(event?.data);
		if (!normalized) {
			return;
		}
		handler(normalized);
	};

	navigator.serviceWorker.addEventListener("message", listener);
	return () => navigator.serviceWorker.removeEventListener("message", listener);
}

export async function ensureWebPushRegistered(options?: { promptPermission?: boolean }) {
	const promptPermission = options?.promptPermission ?? false;

	if (!(await isWebPushSupported())) {
		return { ok: false as const, reason: "unsupported" as const };
	}
	if (!getLoginStatus()) {
		return { ok: false as const, reason: "not_logged_in" as const };
	}

	let permission = Notification.permission;
	if (permission === "default" && promptPermission) {
		permission = await Notification.requestPermission();
	}
	if (permission !== "granted") {
		return { ok: false as const, reason: "permission_denied" as const, permission };
	}

	const swRegistration = await registerFirebaseMessagingServiceWorker();
	const vapidKey = getFirebaseVapidKeyFromEnv();

	const { getToken } = await import("firebase/messaging");
	const messaging = await getFirebaseMessaging();

	const token = await getToken(messaging, {
		vapidKey,
		serviceWorkerRegistration: swRegistration,
	});

	if (!token) {
		return { ok: false as const, reason: "token_unavailable" as const };
	}

	const deviceId = getOrCreateWebPushDeviceId();
	const lastToken = localStorage.getItem(LAST_TOKEN_KEY);

	// Skip backend registration if token hasn't changed
	let backendRegistered = true;
	let backendError: string | null = null;

	if (lastToken !== token) {
		// Token changed or first time - register with backend
		try {
			await apiClient.post("/push/register", { platform: "web", deviceId, token });
			localStorage.setItem(LAST_TOKEN_KEY, token);
		} catch (e: any) {
			backendRegistered = false;
			backendError = e?.response?.data?.error || e?.message || "Failed to register device";
		}
	}

	if (typeof window !== "undefined") {
		window.dispatchEvent(new Event("push:registered"));
	}

	return { ok: true as const, deviceId, token, backendRegistered, backendError };
}

export async function revokeWebPush() {
	const deviceId = getOrCreateWebPushDeviceId();
	localStorage.removeItem(LAST_TOKEN_KEY);

	if (getLoginStatus()) {
		await apiClient.post("/push/revoke", { platform: "web", deviceId });
	}

	if (!(await isWebPushSupported())) return;
	if (Notification.permission !== "granted") return;

	try {
		const { deleteToken } = await import("firebase/messaging");
		const messaging = await getFirebaseMessaging();
		await deleteToken(messaging);
	} catch {
		// Best-effort cleanup.
	}
}

export async function enqueueTestPush(input?: {
	title?: string;
