}

export interface AttendanceRequestsResponse {
   data: Array<{
      id: string;
      employee: {
         id: number;
         name: string;
         email: string;
         avatar?: string | null;
         job_title?: string | null;
      };
      log_date: string;
      check_in_time: string;
      check_out_time: string;
