   rejectTimeOff: async (
      id: number,
      rejectionReason: string
   ): Promise<VacationRejectionResponse> => {
      const response = await apiClient.post(
         endPoints.requests.timeOff.reject(id),
         { rejection_reason: rejectionReason }
